{
  "name": "Meathead: Tactical Shoulder Charge",
  "description": "A high-octane 2D side-scrolling shooter where muscle meets metal. Play as Meathead, a beefy hero who swaps Mega Man's slide for a devastating shoulder charge.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum GameStatus {
  START = 'START',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret';
  behavior: 'patrol' | 'shoot' | 'hover';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

export interface LevelConfig {
  blocks: { x: number; y: number; w: number; h: number; type: string }[];
  enemies: Enemy[];
  spawnPoint: Vector2;
  bossPoint: Vector2;
}

export const CANVAS_WIDTH = 800;
export const CANVAS_HEIGHT = 600;

export const GRAVITY = 0.5;
export const FRICTION = 0.85;

export const PLAYER_SPEED = 5;
export const PLAYER_JUMP_FORCE = -12;
export const CHARGE_SPEED = 15;
export const CHARGE_DURATION = 15; // frames
export const CHARGE_COOLDOWN = 60; // frames

export const COLORS = {
  MEATHEAD: '#FF5733',
  MEATHEAD_GLOW: '#FFC300',
  GROUND: '#2C3E50',
  ENEMY_DRONE: '#8E44AD',
  ENEMY_TANK: '#C0392B',
  PROJECTILE_PLAYER: '#3498DB',
  PROJECTILE_ENEMY: '#E74C3C',
  BG_DARK: '#1A1A1A',
  BG_LIGHT: '#34495E',
};

export const INITIAL_PLAYER_HEALTH = 100;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getBossTaunt(bossName: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a short, menacing one-line taunt from a robotic boss named "${bossName}" directed at a hero named "Meathead" who is basically a wall of muscle. Keep it under 15 words.`,
      config: {
        temperature: 0.9,
      }
    });
    return response.text || "PREPARE FOR TERMINATION, MUSCLE-BRAIN.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "MEATHEAD... YOUR GAINS END HERE.";
  }
}

export async function getMissionBriefing() {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: "Write a 2-sentence mission briefing for 'Meathead'. He needs to infiltrate the Cyber-Slaughterhouse and defeat the Protein-Processor. Be punny about fitness and meat.",
      config: {
        temperature: 1.0,
      }
    });
    return response.text || "Infiltrate the facility and tenderize those robots.";
  } catch (error) {
    return "Infiltrate the base and defeat the machines. Go, Meathead!";
  }
}

import React from 'react';

interface HUDProps {
  health: number;
  maxHealth: number;
  chargeCooldown: number;
  maxChargeCooldown: number;
  score: number;
}

const HUD: React.FC<HUDProps> = ({ health, maxHealth, chargeCooldown, maxChargeCooldown, score }) => {
  const healthPercent = Math.max(0, (health / maxHealth) * 100);
  const chargePercent = Math.max(0, ((maxChargeCooldown - chargeCooldown) / maxChargeCooldown) * 100);

  return (
    <div className="absolute top-0 left-0 p-6 w-full flex justify-between items-start pointer-events-none select-none z-10">
      <div className="flex flex-col gap-2">
        <div className="flex items-center gap-4">
          <span className="text-white text-xs">HP</span>
          <div className="w-48 h-4 bg-gray-900 border-2 border-white overflow-hidden">
            <div 
              className="h-full bg-red-600 transition-all duration-150" 
              style={{ width: `${healthPercent}%` }}
            />
          </div>
        </div>
        <div className="flex items-center gap-4">
          <span className="text-white text-xs">PWR</span>
          <div className="w-48 h-4 bg-gray-900 border-2 border-white overflow-hidden">
            <div 
              className={`h-full transition-all duration-150 ${chargeCooldown === 0 ? 'bg-yellow-400' : 'bg-blue-500'}`}
              style={{ width: `${chargePercent}%` }}
            />
          </div>
        </div>
      </div>
      <div className="text-white text-sm">
        SCORE: {score.toString().padStart(6, '0')}
      </div>
    </div>
  );
};

export default HUD;

import React from 'react';
import { GameStatus } from '../types';

interface OverlayProps {
  status: GameStatus;
  onStart: () => void;
  bossTaunt?: string;
  briefing?: string;
  score?: number;
}

const Overlay: React.FC<OverlayProps> = ({ status, onStart, bossTaunt, briefing, score }) => {
  if (status === GameStatus.PLAYING) return null;

  return (
    <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center z-50 p-10 text-center">
      {status === GameStatus.START && (
        <div className="animate-pulse">
          <h1 className="text-6xl text-red-600 mb-4 font-bold tracking-tighter shadow-red-500 shadow-sm">MEATHEAD</h1>
          <p className="text-white text-sm mb-10 max-w-md leading-relaxed">
            {briefing || "THE CYBER-SLAUGHTERHOUSE AWAITS. SHOULDER CHARGE THROUGH THE METAL!"}
          </p>
          <button 
            onClick={onStart}
            className="px-8 py-4 bg-red-700 hover:bg-red-500 text-white text-xl border-b-4 border-red-900 active:border-b-0 transition-all"
          >
            START MISSION
          </button>
          <div className="mt-8 text-gray-400 text-[10px] space-y-2">
            <p>WASD / ARROWS - MOVE & JUMP</p>
            <p>X / K - SHOOT | SHIFT / L - SHOULDER CHARGE</p>
          </div>
        </div>
      )}

      {status === GameStatus.BOSS_INTRO && (
        <div className="bg-red-950 border-4 border-red-600 p-8 max-w-xl">
          <h2 className="text-3xl text-red-500 mb-4 font-bold">WARNING: BOSS DETECTED</h2>
          <p className="text-white italic text-lg mb-8">"{bossTaunt}"</p>
          <button 
            onClick={onStart}
            className="px-6 py-3 bg-red-600 text-white text-sm hover:bg-red-400"
          >
            BRING IT ON!
          </button>
        </div>
      )}

      {status === GameStatus.GAME_OVER && (
        <div>
          <h2 className="text-5xl text-red-700 mb-4">Wasted.</h2>
          <p className="text-white text-lg mb-8">Final Score: {score}</p>
          <button 
            onClick={onStart}
            className="px-8 py-4 bg-red-700 hover:bg-red-500 text-white text-xl"
          >
            TRY AGAIN
          </button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="animate-bounce">
          <h2 className="text-5xl text-yellow-400 mb-4">VICTORY</h2>
          <p className="text-white text-lg mb-8">MISSION ACCOMPLISHED.<br/>Score: {score}</p>
          <button 
            onClick={onStart}
            className="px-8 py-4 bg-yellow-600 hover:bg-yellow-400 text-white text-xl"
          >
            REPLAY MISSION
          </button>
        </div>
      )}
    </div>
  );
};

export default Overlay;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import HUD from './components/HUD';
import Overlay from './components/Overlay';
import GameCanvas from './components/GameCanvas';
import { GameStatus } from './types';
import { INITIAL_PLAYER_HEALTH, CHARGE_COOLDOWN } from './constants';
import { getBossTaunt, getMissionBriefing } from './services/geminiService';

const App: React.FC = () => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.START);
  const [health, setHealth] = useState(INITIAL_PLAYER_HEALTH);
  const [chargeCooldown, setChargeCooldown] = useState(0);
  const [score, setScore] = useState(0);
  const [bossTaunt, setBossTaunt] = useState("YOU'RE TOAST.");
  const [briefing, setBriefing] = useState("");

  const audioContextRef = useRef<AudioContext | null>(null);

  // Initialize data on mount
  useEffect(() => {
    const fetchBriefing = async () => {
      const b = await getMissionBriefing();
      setBriefing(b);
    };
    fetchBriefing();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleStart = useCallback(() => {
    if (status === GameStatus.START || status === GameStatus.GAME_OVER || status === GameStatus.VICTORY) {
      setHealth(INITIAL_PLAYER_HEALTH);
      setScore(0);
      setChargeCooldown(0);
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_INTRO) {
      setStatus(GameStatus.PLAYING);
    }
  }, [status]);

  const handleBossEncounter = useCallback(async () => {
    setStatus(GameStatus.BOSS_INTRO);
    const taunt = await getBossTaunt("Steel Muscle");
    setBossTaunt(taunt);
  }, []);

  const handleGameOver = useCallback((victory: boolean) => {
    setStatus(victory ? GameStatus.VICTORY : GameStatus.GAME_OVER);
  }, []);

  const handlePlayerUpdate = useCallback((h: number, cc: number, s: number) => {
    setHealth(h);
    setChargeCooldown(cc);
    setScore(s);
  }, []);

  return (
    <div className="relative w-screen h-screen flex items-center justify-center bg-black overflow-hidden">
      <div className="relative shadow-2xl border-4 border-gray-800 bg-[#121212]" style={{ width: 800, height: 600 }}>
        <HUD 
          health={health} 
          maxHealth={INITIAL_PLAYER_HEALTH} 
          chargeCooldown={chargeCooldown} 
          maxChargeCooldown={CHARGE_COOLDOWN}
          score={score}
        />

        <Overlay 
          status={status} 
          onStart={handleStart} 
          bossTaunt={bossTaunt}
          briefing={briefing}
          score={score}
        />

        <GameCanvas 
          status={status}
          onPlayerUpdate={handlePlayerUpdate}
          onBossEncounter={handleBossEncounter}
          onGameOver={handleGameOver}
        />
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, LevelConfig, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH 
} from '../constants';

interface GameCanvasProps {
  status: GameStatus;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, onPlayerUpdate, onBossEncounter, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 100, y: 100 },
      vel: { x: 0, y: 0 },
      width: 40,
      height: 60,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    frame: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    state.blocks = [
      // Floor
      { x: 0, y: 550, w: 2000, h: 50, type: 'ground' },
      { x: 2200, y: 550, w: 1000, h: 50, type: 'ground' },
      { x: 3400, y: 550, w: 2000, h: 50, type: 'ground' },
      // Platforms
      { x: 300, y: 450, w: 150, h: 20, type: 'platform' },
      { x: 500, y: 350, w: 150, h: 20, type: 'platform' },
      { x: 750, y: 280, w: 200, h: 20, type: 'platform' },
      { x: 1000, y: 400, w: 300, h: 20, type: 'platform' },
      { x: 1400, y: 450, w: 200, h: 20, type: 'platform' },
      { x: 1700, y: 350, w: 200, h: 20, type: 'platform' },
      { x: 2300, y: 450, w: 400, h: 20, type: 'platform' },
      { x: 2800, y: 350, w: 200, h: 20, type: 'platform' },
      { x: 3100, y: 250, w: 100, h: 20, type: 'platform' },
    ];

    state.enemies = [
      { id: 'e1', pos: { x: 600, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 30, maxHealth: 30, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 600, shootTimer: 0 },
      { id: 'e2', pos: { x: 1200, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 30, maxHealth: 30, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 1200, shootTimer: 0 },
      { id: 'e3', pos: { x: 1800, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 100, maxHealth: 100, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 1800, shootTimer: 0 },
      { id: 'e4', pos: { x: 2500, y: 490 }, vel: { x: -3, y: 0 }, width: 40, height: 40, health: 30, maxHealth: 30, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 300, initialX: 2500, shootTimer: 0 },
      { id: 'e5', pos: { x: 3800, y: 490 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 500, maxHealth: 500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 3800, shootTimer: 0 },
    ];
  }, []);

  const spawnParticles = (pos: Vector2, color: string, count: number = 10) => {
    for (let i = 0; i < count; i++) {
      gameStateRef.current.particles.push({
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * 10, y: (Math.random() - 0.5) * 10 },
        life: 30 + Math.random() * 20,
        color,
        size: 2 + Math.random() * 4
      });
    }
  };

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;

    // Player Movement
    if (!player.isCharging) {
      if (keys.current['a'] || keys.current['arrowleft']) {
        player.vel.x = -PLAYER_SPEED;
        player.facing = -1;
      } else if (keys.current['d'] || keys.current['arrowright']) {
        player.vel.x = PLAYER_SPEED;
        player.facing = 1;
      } else {
        player.vel.x *= FRICTION;
      }

      if ((keys.current['w'] || keys.current['arrowup'] || keys.current[' ']) && player.isGrounded) {
        player.vel.y = PLAYER_JUMP_FORCE;
        player.isGrounded = false;
      }

      // Charge trigger
      if ((keys.current['shift'] || keys.current['l']) && player.chargeCooldown === 0) {
        player.isCharging = true;
        player.chargeDuration = CHARGE_DURATION;
        player.chargeCooldown = CHARGE_COOLDOWN;
        player.vel.x = player.facing * CHARGE_SPEED;
        player.vel.y = 0; // Hover while charging
        spawnParticles(player.pos, COLORS.MEATHEAD_GLOW, 20);
      }

      // Shoot trigger
      if ((keys.current['x'] || keys.current['k']) && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`,
          pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.pos.y + 25 },
          vel: { x: player.facing * 12, y: 0 },
          width: 15, height: 6,
          health: 1, maxHealth: 1,
          type: 'projectile',
          damage: 10,
          owner: 'player'
        });
        player.shootCooldown = 15;
      }
    } else {
      // Is Charging
      player.chargeDuration--;
      player.vel.x = player.facing * CHARGE_SPEED;
      player.vel.y = 0;
      if (player.chargeDuration <= 0) {
        player.isCharging = false;
      }
      // Charging trail particles
      if (state.frame % 2 === 0) {
        spawnParticles(player.pos, COLORS.MEATHEAD_GLOW, 2);
      }
    }

    if (player.chargeCooldown > 0) player.chargeCooldown--;
    if (player.shootCooldown > 0) player.shootCooldown--;

    // Gravity
    if (!player.isCharging) {
      player.vel.y += GRAVITY;
    }

    // Apply Velocities
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    // Collision detection (Blocks)
    player.isGrounded = false;
    blocks.forEach(block => {
      // Horizontal
      if (
        player.pos.x < block.x + block.w &&
        player.pos.x + player.width > block.x &&
        player.pos.y < block.y + block.h &&
        player.pos.y + player.height > block.y
      ) {
        // Resolve collision
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);

        if (overlapX < overlapY) {
          if (player.pos.x + player.width / 2 < block.x + block.w / 2) {
            player.pos.x = block.x - player.width;
          } else {
            player.pos.x = block.x + block.w;
          }
          player.vel.x = 0;
        } else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) {
            player.pos.y = block.y - player.height;
            player.isGrounded = true;
            player.vel.y = 0;
          } else {
            player.pos.y = block.y + block.h;
            player.vel.y = 0;
          }
        }
      }
    });

    // Enemies Logic
    state.enemies = enemies.filter(enemy => {
      // Behavior
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) {
          enemy.vel.x *= -1;
        }
      } else if (enemy.behavior === 'shoot') {
        enemy.shootTimer++;
        if (enemy.shootTimer > 60) {
          projectiles.push({
            id: `ep-${Date.now()}`,
            pos: { x: enemy.pos.x, y: enemy.pos.y + enemy.height / 2 },
            vel: { x: player.pos.x < enemy.pos.x ? -6 : 6, y: 0 },
            width: 10, height: 10,
            health: 1, maxHealth: 1,
            type: 'projectile',
            damage: 15,
            owner: 'enemy'
          });
          enemy.shootTimer = 0;
        }
      }

      // Collision with player charge
      if (player.isCharging && 
          player.pos.x < enemy.pos.x + enemy.width &&
          player.pos.x + player.width > enemy.pos.x &&
          player.pos.y < enemy.pos.y + enemy.height &&
          player.pos.y + player.height > enemy.pos.y) {
        enemy.health -= 50;
        spawnParticles(enemy.pos, COLORS.ENEMY_DRONE, 15);
        state.score += 50;
        // Bump player back a bit or continue through
      } else if (!player.isCharging && 
          player.pos.x < enemy.pos.x + enemy.width &&
          player.pos.x + player.width > enemy.pos.x &&
          player.pos.y < enemy.pos.y + enemy.height &&
          player.pos.y + player.height > enemy.pos.y) {
          // Take damage from touch
          if (state.frame % 30 === 0) {
            player.health -= 10;
          }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && Math.abs(player.pos.x - enemy.pos.x) < 400) {
        state.bossSpawned = true;
        onBossEncounter();
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 5000 : 100;
        spawnParticles(enemy.pos, enemy.type === 'boss' ? '#FFD700' : COLORS.ENEMY_TANK, 30);
        if (enemy.type === 'boss') {
          setTimeout(() => onGameOver(true), 1500);
        }
        return false;
      }
      return true;
    });

    // Projectiles logic
    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      p.pos.y += p.vel.y;

      // Offscreen
      if (p.pos.x < state.camera.x - 100 || p.pos.x > state.camera.x + CANVAS_WIDTH + 100) return false;

      // Hit blocks
      for (const block of blocks) {
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          spawnParticles(p.pos, p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY, 5);
          return false;
        }
      }

      // Hit enemy
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            enemy.health -= p.damage;
            spawnParticles(p.pos, COLORS.PROJECTILE_PLAYER, 5);
            return false;
          }
        }
      } else {
        // Hit player
        if (!player.isCharging && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage;
          spawnParticles(p.pos, COLORS.PROJECTILE_ENEMY, 5);
          return false;
        }
      }

      return true;
    });

    // Particles logic
    state.particles = particles.filter(p => {
      p.pos.x += p.vel.x;
      p.pos.y += p.vel.y;
      p.life--;
      return p.life > 0;
    });

    // Camera follow
    state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);

    // Death check
    if (player.health <= 0 || player.pos.y > 1000) {
      onGameOver(false);
    }

    onPlayerUpdate(player.health, player.chargeCooldown, state.score);

  }, [status, onPlayerUpdate, onBossEncounter, onGameOver]);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    // Clear and background
    ctx.fillStyle = COLORS.BG_DARK;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Parallax background (simulated)
    ctx.fillStyle = COLORS.BG_LIGHT;
    for (let i = 0; i < 5; i++) {
      ctx.fillRect((i * 500 - camera.x * 0.2) % (2000), 50, 200, 300);
    }

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    // Draw Blocks
    ctx.fillStyle = COLORS.GROUND;
    blocks.forEach(block => {
      ctx.fillRect(block.x, block.y, block.w, block.h);
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1;
      ctx.strokeRect(block.x, block.y, block.w, block.h);
    });

    // Draw Player
    ctx.fillStyle = player.isCharging ? COLORS.MEATHEAD_GLOW : COLORS.MEATHEAD;
    ctx.fillRect(player.pos.x, player.pos.y, player.width, player.height);
    // Muscle details
    ctx.fillStyle = 'rgba(0,0,0,0.2)';
    ctx.fillRect(player.pos.x + (player.facing === 1 ? 25 : 5), player.pos.y + 10, 10, 20);
    // Eyes
    ctx.fillStyle = '#fff';
    ctx.fillRect(player.pos.x + (player.facing === 1 ? 30 : 5), player.pos.y + 5, 5, 5);

    // Draw Enemies
    enemies.forEach(enemy => {
      ctx.fillStyle = enemy.type === 'boss' ? '#FFD700' : (enemy.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
      ctx.fillRect(enemy.pos.x, enemy.pos.y, enemy.width, enemy.height);
      // Health bar above enemy
      ctx.fillStyle = 'red';
      ctx.fillRect(enemy.pos.x, enemy.pos.y - 10, enemy.width, 4);
      ctx.fillStyle = 'green';
      ctx.fillRect(enemy.pos.x, enemy.pos.y - 10, (enemy.health / enemy.maxHealth) * enemy.width, 4);
    });

    // Draw Projectiles
    projectiles.forEach(p => {
      ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
      ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
    });

    // Draw Particles
    particles.forEach(p => {
      ctx.globalAlpha = p.life / 50;
      ctx.fillStyle = p.color;
      ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
    });
    ctx.globalAlpha = 1;

    ctx.restore();
  }, []);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => {
      update();
      draw();
      animationFrameId = window.requestAnimationFrame(loop);
    };

    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        // Reset player
        gameStateRef.current.player.pos = { x: 100, y: 100 };
        gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH;
        gameStateRef.current.score = 0;
        gameStateRef.current.bossSpawned = false;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else if (status === GameStatus.START || status === GameStatus.GAME_OVER || status === GameStatus.VICTORY) {
      gameStateRef.current.frame = 0;
      draw(); // Draw final state
    }

    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return (
    <canvas 
      ref={canvasRef} 
      width={CANVAS_WIDTH} 
      height={CANVAS_HEIGHT}
      className="bg-black"
    />
  );
};

export default GameCanvas;

export const CANVAS_WIDTH = 800;
export const CANVAS_HEIGHT = 600;

export const GRAVITY = 0.5;
export const FRICTION = 0.85;

export const PLAYER_SPEED = 5;
export const PLAYER_JUMP_FORCE = -12;
export const CHARGE_SPEED = 18;
export const CHARGE_DURATION = 25; // Longer charge duration
export const CHARGE_COOLDOWN = 50; // Slightly faster cooldown
export const JUMP_PREP_FRAMES = 6;
export const LAND_FRAMES = 8;

export const COLORS = {
  MEATHEAD_SKIN: '#E67E22',
  MEATHEAD_PANTS: '#273746',
  MEATHEAD_GLOW: '#FFC300',
  GUN: '#5D6D7E',
  GROUND: '#1C2833',
  ENEMY_DRONE: '#8E44AD',
  ENEMY_TANK: '#C0392B',
  PROJECTILE_PLAYER: '#F1C40F',
  PROJECTILE_ENEMY: '#E74C3C',
  BG_DARK: '#0B0B0B',
  BG_LIGHT: '#1B2631',
};

export const INITIAL_PLAYER_HEALTH = 100;

export enum GameStatus {
  START = 'START',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret';
  behavior: 'patrol' | 'shoot' | 'hover';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

export interface LevelConfig {
  blocks: { x: number; y: number; w: number; h: number; type: string }[];
  enemies: Enemy[];
  spawnPoint: Vector2;
  bossPoint: Vector2;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getBossTaunt(bossName: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a short, menacing one-line taunt from a robotic boss named "${bossName}" directed at a beefy shirtless man named "Meathead" who has a scowl and a handgun. Keep it under 15 words.`,
      config: {
        temperature: 0.9,
      }
    });
    return response.text || "PREPARE FOR TERMINATION, MUSCLE-BRAIN.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "MEATHEAD... YOUR GAINS END HERE.";
  }
}

export async function getMissionBriefing() {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: "Write a short mission briefing for Meathead. The first sentence MUST be: 'Your mission is to kill everyone for no apparent reason.' The second sentence should be a beefy pun.",
      config: {
        temperature: 1.0,
      }
    });
    return response.text || "Your mission is to kill everyone for no apparent reason. It's time to beef up the body count.";
  } catch (error) {
    return "Your mission is to kill everyone for no apparent reason. Go, Meathead!";
  }
}

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES 
} from '../constants';

interface GameCanvasProps {
  status: GameStatus;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, onPlayerUpdate, onBossEncounter, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 100, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    frame: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});

  const playGunSound = () => {
    if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    const ctx = audioCtxRef.current;

    // Crack noise
    const noiseBuffer = ctx.createBuffer(1, ctx.sampleRate * 0.1, ctx.sampleRate);
    const output = noiseBuffer.getChannelData(0);
    for (let i = 0; i < noiseBuffer.length; i++) {
      output[i] = Math.random() * 2 - 1;
    }

    const noise = ctx.createBufferSource();
    noise.buffer = noiseBuffer;

    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'lowpass';
    noiseFilter.frequency.setValueAtTime(2000, ctx.currentTime);
    noiseFilter.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.1);

    const noiseEnvelope = ctx.createGain();
    noiseEnvelope.gain.setValueAtTime(0.5, ctx.currentTime);
    noiseEnvelope.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);

    noise.connect(noiseFilter);
    noiseFilter.connect(noiseEnvelope);
    noiseEnvelope.connect(ctx.destination);
    noise.start();

    // Bass "oomph"
    const osc = ctx.createOscillator();
    const oscGain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(150, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.15);
    oscGain.gain.setValueAtTime(0.4, ctx.currentTime);
    oscGain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.15);
    osc.connect(oscGain);
    oscGain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.15);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    state.blocks = [
      { x: 0, y: 550, w: 2500, h: 50, type: 'ground' },
      { x: 2700, y: 550, w: 2000, h: 50, type: 'ground' },
      { x: 300, y: 450, w: 150, h: 20, type: 'platform' },
      { x: 500, y: 350, w: 150, h: 20, type: 'platform' },
      { x: 800, y: 280, w: 200, h: 20, type: 'platform' },
      { x: 1200, y: 400, w: 300, h: 20, type: 'platform' },
      { x: 1600, y: 300, w: 200, h: 20, type: 'platform' },
      { x: 2000, y: 200, w: 150, h: 20, type: 'platform' },
      { x: 3000, y: 550, w: 2000, h: 50, type: 'ground' },
    ];

    state.enemies = [
      { id: 'e1', pos: { x: 700, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 700, shootTimer: 0 },
      { id: 'e2', pos: { x: 1400, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 1400, shootTimer: 0 },
      { id: 'e3', pos: { x: 2200, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 150, maxHealth: 150, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 2200, shootTimer: 0 },
      { id: 'e4', pos: { x: 4200, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 600, maxHealth: 600, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 4200, shootTimer: 0 },
    ];
  }, []);

  const spawnParticles = (pos: Vector2, color: string, count: number = 10) => {
    for (let i = 0; i < count; i++) {
      gameStateRef.current.particles.push({
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * 10, y: (Math.random() - 0.5) * 10 },
        life: 30 + Math.random() * 20,
        color,
        size: 2 + Math.random() * 4
      });
    }
  };

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'] || keys.current['l'];
    const shootRequested = keys.current['x'] || keys.current['k'];

    // Player State Machine
    if (!player.isCharging) {
      if (player.jumpPrepTimer > 0) {
        player.jumpPrepTimer--;
        if (player.jumpPrepTimer === 0) {
          player.vel.y = PLAYER_JUMP_FORCE;
          player.isGrounded = false;
        }
      } else if (player.landTimer > 0) {
        player.landTimer--;
        player.vel.x *= 0.5; // Friction on land
      } else {
        // Normal movement
        if (moveLeft) {
          player.vel.x = -PLAYER_SPEED;
          player.facing = -1;
        } else if (moveRight) {
          player.vel.x = PLAYER_SPEED;
          player.facing = 1;
        } else {
          player.vel.x *= FRICTION;
        }

        if (jumpRequested && player.isGrounded) {
          player.jumpPrepTimer = JUMP_PREP_FRAMES;
        }

        if (chargeRequested && player.chargeCooldown === 0) {
          player.isCharging = true;
          player.chargeDuration = CHARGE_DURATION;
          player.chargeCooldown = CHARGE_COOLDOWN;
          player.vel.x = player.facing * CHARGE_SPEED;
          // Air charge stays mostly level
          player.vel.y = player.isGrounded ? 0 : -1; 
          spawnParticles(player.pos, COLORS.MEATHEAD_GLOW, 20);
        }

        if (shootRequested && player.shootCooldown <= 0) {
          projectiles.push({
            id: `p-${Date.now()}`,
            pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.pos.y + 25 },
            vel: { x: player.facing * 14, y: 0 },
            width: 14, height: 4,
            health: 1, maxHealth: 1,
            type: 'projectile',
            damage: 15,
            owner: 'player'
          });
          player.shootCooldown = 12;
          playGunSound();
        }
      }
    } else {
      // Is Charging
      player.chargeDuration--;
      player.vel.x = player.facing * CHARGE_SPEED;
      // Maintain air dash
      if (!player.isGrounded) player.vel.y *= 0.8;

      if (player.chargeDuration <= 0) {
        player.isCharging = false;
        // Maintain some forward momentum after charge
        player.vel.x = player.facing * (PLAYER_SPEED + 2);
      }
      if (state.frame % 2 === 0) spawnParticles(player.pos, COLORS.MEATHEAD_GLOW, 2);
    }

    if (player.chargeCooldown > 0) player.chargeCooldown--;
    if (player.shootCooldown > 0) player.shootCooldown--;

    // Physics
    if (!player.isCharging && player.jumpPrepTimer <= 0) {
      player.vel.y += GRAVITY;
    }

    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    // Collision (Blocks)
    const wasGrounded = player.isGrounded;
    player.isGrounded = false;
    blocks.forEach(block => {
      if (
        player.pos.x < block.x + block.w &&
        player.pos.x + player.width > block.x &&
        player.pos.y < block.y + block.h &&
        player.pos.y + player.height > block.y
      ) {
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);

        if (overlapX < overlapY) {
          player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w;
          player.vel.x = 0;
        } else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) {
            player.pos.y = block.y - player.height;
            player.isGrounded = true;
            player.vel.y = 0;
            if (!wasGrounded) player.landTimer = LAND_FRAMES;
          } else {
            player.pos.y = block.y + block.h;
            player.vel.y = 0;
          }
        }
      }
    });

    // Enemies
    state.enemies = enemies.filter(enemy => {
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot') {
        enemy.shootTimer++;
        if (enemy.shootTimer > 70) {
          projectiles.push({
            id: `ep-${Date.now()}`,
            pos: { x: enemy.pos.x, y: enemy.pos.y + 20 },
            vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 },
            width: 12, height: 12,
            health: 1, maxHealth: 1,
            type: 'projectile',
            damage: 20,
            owner: 'enemy'
          });
          enemy.shootTimer = 0;
        }
      }

      // Hit Logic
      const isHit = player.pos.x < enemy.pos.x + enemy.width &&
                   player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height &&
                   player.pos.y + player.height > enemy.pos.y;

      if (isHit) {
        if (player.isCharging) {
          enemy.health -= 60;
          spawnParticles(enemy.pos, COLORS.ENEMY_DRONE, 15);
          state.score += 50;
        } else if (state.frame % 40 === 0) {
          player.health -= 15;
          spawnParticles(player.pos, COLORS.MEATHEAD_SKIN, 5);
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && Math.abs(player.pos.x - enemy.pos.x) < 400) {
        state.bossSpawned = true;
        onBossEncounter();
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 10000 : 200;
        spawnParticles(enemy.pos, '#fff', 25);
        if (enemy.type === 'boss') setTimeout(() => onGameOver(true), 2000);
        return false;
      }
      return true;
    });

    // Projectiles
    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 100 || p.pos.x > state.camera.x + CANVAS_WIDTH + 100) return false;

      let hit = false;
      for (const block of blocks) {
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          hit = true; break;
        }
      }
      if (hit) {
        spawnParticles(p.pos, '#666', 3);
        return false;
      }

      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            enemy.health -= p.damage;
            spawnParticles(p.pos, COLORS.PROJECTILE_PLAYER, 5);
            return false;
          }
        }
      } else {
        if (!player.isCharging && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage;
          spawnParticles(p.pos, COLORS.PROJECTILE_ENEMY, 5);
          return false;
        }
      }
      return true;
    });

    state.particles = particles.filter(p => {
      p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0;
    });

    state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);
    if (player.health <= 0 || player.pos.y > 1000) onGameOver(false);
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);

  }, [status, onPlayerUpdate, onBossEncounter, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    ctx.save();

    let drawX = p.pos.x;
    let drawY = p.pos.y;
    let drawW = p.width;
    let drawH = p.height;

    // Animation: Squish for Jump Prep and Land
    if (p.jumpPrepTimer > 0 || p.landTimer > 0) {
      drawY += 10;
      drawH -= 10;
      drawX -= 2;
      drawW += 4;
    }

    // Animation: Stretch for Charge
    if (p.isCharging) {
      drawW += 10;
      drawX -= 5;
    }

    // Body (Shirtless)
    ctx.fillStyle = COLORS.MEATHEAD_SKIN;
    ctx.fillRect(drawX, drawY, drawW, drawH * 0.6); // Torso

    // Pants
    ctx.fillStyle = COLORS.MEATHEAD_PANTS;
    ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);

    // Musculature lines
    ctx.strokeStyle = 'rgba(0,0,0,0.1)';
    ctx.beginPath();
    ctx.moveTo(drawX + drawW * 0.3, drawY + 10);
    ctx.lineTo(drawX + drawW * 0.3, drawY + drawH * 0.5);
    ctx.moveTo(drawX + drawW * 0.7, drawY + 10);
    ctx.lineTo(drawX + drawW * 0.7, drawY + drawH * 0.5);
    ctx.stroke();

    // Scowling Face
    ctx.fillStyle = '#000';
    const eyeY = drawY + 10;
    const eyeX = p.facing === 1 ? drawX + drawW - 15 : drawX + 5;
    ctx.fillRect(eyeX, eyeY, 10, 2); // Scowling brow/eyes

    // Handgun
    ctx.fillStyle = COLORS.GUN;
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 10;
    const gunY = drawY + drawH * 0.4;
    ctx.fillRect(gunX, gunY, 20, 8); // Gun barrel
    ctx.fillRect(p.facing === 1 ? gunX : gunX + 15, gunY, 5, 12); // Grip

    if (p.isCharging) {
      ctx.strokeStyle = COLORS.MEATHEAD_GLOW;
      ctx.lineWidth = 3;
      ctx.strokeRect(drawX - 2, drawY - 2, drawW + 4, drawH + 4);
    }

    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    ctx.fillStyle = COLORS.BG_DARK;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Parallax
    ctx.fillStyle = COLORS.BG_LIGHT;
    for (let i = 0; i < 6; i++) {
      ctx.fillRect((i * 600 - camera.x * 0.1) % (3000), 100, 300, 450);
    }

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    // Blocks
    ctx.fillStyle = COLORS.GROUND;
    blocks.forEach(b => {
      ctx.fillRect(b.x, b.y, b.w, b.h);
      ctx.strokeStyle = '#2C3E50';
      ctx.strokeRect(b.x, b.y, b.w, b.h);
    });

    // Enemies
    enemies.forEach(e => {
      ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
      ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      ctx.fillStyle = 'red'; ctx.fillRect(e.pos.x, e.pos.y - 12, e.width, 5);
      ctx.fillStyle = 'green'; ctx.fillRect(e.pos.x, e.pos.y - 12, (e.health / e.maxHealth) * e.width, 5);
    });

    // Player
    drawPlayer(ctx, player);

    // Projectiles
    projectiles.forEach(p => {
      ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
      ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
    });

    // Particles
    particles.forEach(p => {
      ctx.globalAlpha = p.life / 50;
      ctx.fillStyle = p.color;
      ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
    });
    ctx.globalAlpha = 1;

    ctx.restore();
  }, []);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => {
      update();
      draw();
      animationFrameId = window.requestAnimationFrame(loop);
    };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player.pos = { x: 100, y: 100 };
        gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH;
        gameStateRef.current.score = 0;
        gameStateRef.current.bossSpawned = false;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black" />;
};

export default GameCanvas;

