import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES 
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED",
  "SUCK ON THIS", "BITE ME", "HELL NO", "BULLSHIT", "DUMBASS"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "SON OF A WHORE", 
  "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL", "FUCKING HELL"
];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const isSpeakingRef = useRef(false);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (isSpeakingRef.current || (window.speechSynthesis && window.speechSynthesis.speaking)) return;

    let pool = KILL_VULGARITIES;
    if (category === 'hurt') pool = HURT_VULGARITIES;
    if (category === 'death') pool = DEATH_VULGARITIES;

    const text = pool[Math.floor(Math.random() * pool.length)];
    gameStateRef.current.lastVulgarity = text;
    gameStateRef.current.vulgarityTimer = 60;

    if ('speechSynthesis' in window) {
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.2;
      utterance.rate = 1.1;
      utterance.volume = 1.0;
      utterance.onstart = () => { isSpeakingRef.current = true; };
      utterance.onend = () => { isSpeakingRef.current = false; };
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    const ctx = audioCtxRef.current;

    const noiseBuffer = ctx.createBuffer(1, ctx.sampleRate * 0.1, ctx.sampleRate);
    const output = noiseBuffer.getChannelData(0);
    for (let i = 0; i < noiseBuffer.length; i++) output[i] = Math.random() * 2 - 1;

    const noise = ctx.createBufferSource();
    noise.buffer = noiseBuffer;
    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'lowpass';
    noiseFilter.frequency.setValueAtTime(3000, ctx.currentTime);
    noiseFilter.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.1);
    const noiseEnvelope = ctx.createGain();
    noiseEnvelope.gain.setValueAtTime(0.7, ctx.currentTime);
    noiseEnvelope.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.12);
    noise.connect(noiseFilter);
    noiseFilter.connect(noiseEnvelope);
    noiseEnvelope.connect(ctx.destination);
    noise.start();

    const osc = ctx.createOscillator();
    const oscGain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(120, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.15);
    oscGain.gain.setValueAtTime(0.6, ctx.currentTime);
    oscGain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.15);
    osc.connect(oscGain);
    oscGain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.15);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;

    // Default level shell
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 3000, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: 3000, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: 3000, h: 50, type: 'ground' },
    ];

    // Stage specific layout
    if (stageId === 'Artie Avalanche') {
      state.blocks.push(
        { x: 400, y: 450, w: 200, h: 20, type: 'platform' },
        { x: 700, y: 350, w: 200, h: 20, type: 'platform' },
        { x: 1000, y: 250, w: 200, h: 20, type: 'platform' },
        { x: 1300, y: 400, w: 200, h: 20, type: 'platform' },
        { x: 1600, y: 300, w: 200, h: 20, type: 'platform' }
      );
    } else if (stageId === 'Victor Volcano') {
      state.blocks.push(
        { x: 300, y: 480, w: 100, h: 70, type: 'block' },
        { x: 600, y: 480, w: 100, h: 70, type: 'block' },
        { x: 900, y: 480, w: 100, h: 70, type: 'block' },
        { x: 1200, y: 480, w: 100, h: 70, type: 'block' },
        { x: 1500, y: 400, w: 400, h: 20, type: 'platform' }
      );
    } else if (stageId === 'Ernie Earthquake') {
      state.blocks.push(
        { x: 200, y: 500, w: 800, h: 50, type: 'block' },
        { x: 400, y: 450, w: 400, h: 50, type: 'block' },
        { x: 600, y: 400, w: 200, h: 50, type: 'block' },
        { x: 1200, y: 450, w: 600, h: 20, type: 'platform' }
      );
    } else { // Hector Hurricane
      state.blocks.push(
        { x: 300, y: 400, w: 150, h: 20, type: 'platform' },
        { x: 600, y: 300, w: 150, h: 20, type: 'platform' },
        { x: 900, y: 200, w: 150, h: 20, type: 'platform' },
        { x: 1200, y: 300, w: 150, h: 20, type: 'platform' },
        { x: 1500, y: 400, w: 150, h: 20, type: 'platform' }
      );
    }

    state.enemies = [
      { id: 'e1', pos: { x: 500, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 500, shootTimer: 0 },
      { id: 'e2', pos: { x: 1200, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 1200, shootTimer: 0 },
      { id: 'e3', pos: { x: 1800, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 150, maxHealth: 150, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 1800, shootTimer: 0 },
      { id: 'boss', pos: { x: 2500, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 600, maxHealth: 600, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 2500, shootTimer: 0 },
    ];
  }, [stageId]);

  const spawnParticles = (pos: Vector2, color: string, count: number = 10) => {
    for (let i = 0; i < count; i++) {
      gameStateRef.current.particles.push({
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * 10, y: (Math.random() - 0.5) * 10 },
        life: 30 + Math.random() * 20,
        color,
        size: 2 + Math.random() * 4
      });
    }
  };

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;

    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) {
        player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE;
        player.isGrounded = false;
        if (player.isCharging) spawnParticles(player.pos, COLORS.MEATHEAD_GLOW, 25);
      }
    } else if (player.landTimer > 0) {
      player.landTimer--;
      player.vel.x *= 0.5;
    } else {
      if (!player.isCharging) {
        if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
        else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
        else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--;
        player.vel.x = player.facing * CHARGE_SPEED;
        if (!player.isGrounded) player.vel.y *= 0.9;
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;

        if (player.chargeDuration <= 0) {
          player.isCharging = false;
          player.vel.x = player.facing * (PLAYER_SPEED + 6); 
        }
        if (state.frame % 2 === 0) spawnParticles(player.pos, COLORS.MEATHEAD_GLOW, 2);
      }

      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging) {
        player.isCharging = true;
        player.chargeDuration = CHARGE_DURATION;
        player.chargeCooldown = CHARGE_COOLDOWN;
        player.vel.x = player.facing * CHARGE_SPEED;
        player.vel.y = player.isGrounded ? 0 : -3; 
        spawnParticles(player.pos, COLORS.MEATHEAD_GLOW, 20);
      }

      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`,
          pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.pos.y + 25 },
          vel: { x: player.facing * 16, y: 0 },
          width: 14, height: 4,
          health: 1, maxHealth: 1,
          type: 'projectile',
          damage: 15,
          owner: 'player'
        });
        player.shootCooldown = 10;
        playGunSound();
      }
    }

    if (player.chargeCooldown > 0) player.chargeCooldown--;
    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.jumpPrepTimer <= 0) player.vel.y += GRAVITY;

    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    // Collision (Blocks)
    const wasGrounded = player.isGrounded;
    player.isGrounded = false;
    blocks.forEach(block => {
      if (
        player.pos.x < block.x + block.w &&
        player.pos.x + player.width > block.x &&
        player.pos.y < block.y + block.h &&
        player.pos.y + player.height > block.y
      ) {
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);

        if (overlapX < overlapY) {
          player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w;
          player.vel.x = 0;
        } else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) {
            player.pos.y = block.y - player.height;
            player.isGrounded = true;
            player.vel.y = 0;
            if (!wasGrounded) player.landTimer = LAND_FRAMES;
          } else {
            player.pos.y = block.y + block.h;
            player.vel.y = 0;
          }
        }
      }
    });

    // Enemies
    state.enemies = enemies.filter(enemy => {
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot') {
        enemy.shootTimer++;
        if (enemy.shootTimer > 70) {
          projectiles.push({
            id: `ep-${Date.now()}`,
            pos: { x: enemy.pos.x, y: enemy.pos.y + 20 },
            vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 },
            width: 12, height: 12,
            health: 1, maxHealth: 1,
            type: 'projectile',
            damage: 20,
            owner: 'enemy'
          });
          enemy.shootTimer = 0;
        }
      }

      const distToPlayer = Math.abs(enemy.pos.x - player.pos.x);
      if (enemy.type === 'boss' && distToPlayer < 400 && !state.bossSpawned) {
        state.bossSpawned = true;
        onBossEncounter();
      }

      const isHit = player.pos.x < enemy.pos.x + enemy.width &&
                   player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height &&
                   player.pos.y + player.height > enemy.pos.y;

      if (isHit) {
        if (player.isCharging) {
          enemy.health -= 100;
          spawnParticles(enemy.pos, '#fff', 15);
        } else if (state.frame % 40 === 0) {
          player.health -= 15;
          speakVulgarity('hurt');
        }
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 10000 : 250;
        spawnParticles(enemy.pos, '#fff', 30);
        speakVulgarity('kill');
        if (enemy.type === 'boss') setTimeout(() => onGameOver(true), 2000);
        return false;
      }
      return true;
    });

    // Projectiles
    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 100 || p.pos.x > state.camera.x + CANVAS_WIDTH + 100) return false;

      let hitBlock = false;
      for (const block of blocks) {
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          hitBlock = true; break;
        }
      }
      if (hitBlock) return false;

      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            enemy.health -= p.damage;
            spawnParticles(p.pos, COLORS.PROJECTILE_PLAYER, 5);
            return false;
          }
        }
      } else {
        if (!player.isCharging && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage;
          spawnParticles(p.pos, COLORS.PROJECTILE_ENEMY, 5);
          speakVulgarity('hurt');
          return false;
        }
      }
      return true;
    });

    state.particles = particles.filter(p => {
      p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0;
    });

    state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);

    if (player.health <= 0 || player.pos.y > 1000) {
      if (player.health > 0) player.health = 0; 
      speakVulgarity('death');
      player.vel.x = 0; player.vel.y = 0;
      setTimeout(() => onGameOver(false), 1500);
    }

    onPlayerUpdate(player.health, player.chargeCooldown, state.score);

  }, [status, onPlayerUpdate, onBossEncounter, onGameOver]);

  const getStageColor = () => {
    switch (stageId) {
      case 'Artie Avalanche': return '#EBF5FB';
      case 'Victor Volcano': return '#922B21';
      case 'Ernie Earthquake': return '#5D4037';
      case 'Hector Hurricane': return '#006064';
      default: return COLORS.GROUND;
    }
  };

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    ctx.save();
    let drawX = p.pos.x;
    let drawY = p.pos.y;
    let drawW = p.width;
    let drawH = p.height;

    if (p.jumpPrepTimer > 0 || p.landTimer > 0) {
      drawY += 12; drawH -= 12; drawX -= 4; drawW += 8;
    }
    if (p.isCharging) {
      drawW += 20; drawX -= p.facing === 1 ? 5 : 15;
      ctx.translate(drawX + drawW/2, drawY + drawH/2);
      ctx.rotate(p.facing * 0.1);
      ctx.translate(-(drawX + drawW/2), -(drawY + drawH/2));
    }

    ctx.fillStyle = COLORS.MEATHEAD_SKIN;
    ctx.fillRect(drawX, drawY, drawW, drawH * 0.65);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS;
    ctx.fillRect(drawX, drawY + drawH * 0.65, drawW, drawH * 0.35);

    const eyeX = p.facing === 1 ? drawX + drawW - 14 : drawX + 4;
    const eyeY = drawY + 12;
    ctx.fillStyle = '#000';
    ctx.fillRect(eyeX, eyeY - 2, 12, 3);
    ctx.fillStyle = '#fff';
    ctx.fillRect(eyeX + 2, eyeY + 1, 3, 2);
    ctx.fillRect(eyeX + 7, eyeY + 1, 3, 2);

    ctx.fillStyle = '#222';
    const gunX = p.facing === 1 ? drawX + drawW - 8 : drawX - 12;
    const gunY = drawY + drawH * 0.45;
    ctx.fillRect(gunX, gunY, 22, 9);
    ctx.fillRect(p.facing === 1 ? gunX + 2 : gunX + 15, gunY + 5, 5, 12);

    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"';
      const measure = ctx.measureText(txt);
      const bgW = measure.width + 10;
      ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
      ctx.fillRect(drawX + drawW/2 - bgW/2, drawY - 35, bgW, 20);
      ctx.fillStyle = 'white';
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20);
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    ctx.fillStyle = COLORS.BG_DARK;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      ctx.fillStyle = getStageColor();
      ctx.fillRect(b.x, b.y, b.w, b.h);
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      ctx.strokeRect(b.x, b.y, b.w, b.h);
    });

    enemies.forEach(e => {
      ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
      ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      ctx.fillStyle = '#440000'; ctx.fillRect(e.pos.x, e.pos.y - 12, e.width, 4);
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 12, (e.health / e.maxHealth) * e.width, 4);
    });

    drawPlayer(ctx, player);

    projectiles.forEach(p => {
      ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
      ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
    });

    particles.forEach(p => {
      ctx.globalAlpha = p.life / 50;
      ctx.fillStyle = p.color;
      ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
    });
    ctx.globalAlpha = 1;

    ctx.restore();
  }, [stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => {
      update();
      draw();
      animationFrameId = window.requestAnimationFrame(loop);
    };

    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = {
          ...gameStateRef.current.player,
          pos: { x: 150, y: 100 },
          vel: { x: 0, y: 0 },
          health: INITIAL_PLAYER_HEALTH,
          isCharging: false,
          chargeCooldown: 0,
          chargeDuration: 0,
          isGrounded: false
        };
        gameStateRef.current.score = 0;
        gameStateRef.current.bossSpawned = false;
        gameStateRef.current.projectiles = [];
        gameStateRef.current.particles = [];
        gameStateRef.current.lastVulgarity = "";
        gameStateRef.current.vulgarityTimer = 0;
        gameStateRef.current.camera = { x: 0, y: 0 };
        isSpeakingRef.current = false;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      gameStateRef.current.frame = 0;
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-2 border-gray-700" />;
};

export default GameCanvas;

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  isDucking: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret';
  behavior: 'patrol' | 'shoot' | 'hover';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getBossTaunt(bossName: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a short, menacing one-line taunt from a robotic boss named "${bossName}" directed at a beefy shirtless man named "Meathead". Keep it under 15 words.`,
      config: {
        temperature: 0.9,
      }
    });
    return response.text || "PREPARE FOR TERMINATION, MUSCLE-BRAIN.";
  } catch (error) {
    return "MEATHEAD... YOUR GAINS END HERE.";
  }
}

export async function getMissionBriefing() {
  return "Your mission is to kill everything in sight.";
}

export async function getMeatheadVictorySpeech(bossName: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a long, verbose, and overly intellectual monologue delivered by "Meathead" (a beefy shirtless man) standing over the wreckage of "${bossName}". He should sound weirdly poetic about how he just destroyed them with pure muscle. Make it 3-4 sentences and very dramatic.`,
      config: {
        temperature: 1.0,
      }
    });
    return response.text || "Thy metallic shell could not withstand the sheer pressure of my pectorals. Thou art but scrap metal now.";
  } catch (error) {
    return "You were fast, but my muscles are faster. Rest in pieces.";
  }
}

import React, { useState, useEffect, useCallback } from 'react';
import HUD from './components/HUD';
import Overlay from './components/Overlay';
import GameCanvas from './components/GameCanvas';
import { GameStatus } from './types';
import { INITIAL_PLAYER_HEALTH, CHARGE_COOLDOWN } from './constants';
import { getBossTaunt, getMissionBriefing, getMeatheadVictorySpeech } from './services/geminiService';

const App: React.FC = () => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.START);
  const [health, setHealth] = useState(INITIAL_PLAYER_HEALTH);
  const [chargeCooldown, setChargeCooldown] = useState(0);
  const [score, setScore] = useState(0);
  const [bossTaunt, setBossTaunt] = useState("YOU'RE TOAST.");
  const [victorySpeech, setVictorySpeech] = useState("");
  const [briefing, setBriefing] = useState("");
  const [selectedStage, setSelectedStage] = useState<string | null>(null);
  const [defeatedStages, setDefeatedStages] = useState<string[]>([]);

  useEffect(() => {
    const fetchBriefing = async () => {
      const b = await getMissionBriefing();
      setBriefing(b);
    };
    fetchBriefing();
  }, []);

  const handleStart = useCallback(() => {
    if (status === GameStatus.START || status === GameStatus.VICTORY) {
      setDefeatedStages([]);
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.GAME_OVER) {
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.BOSS_INTRO) {
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_VICTORY_SPEECH) {
      // Check if all bosses are defeated
      if (defeatedStages.length >= 4) {
        setStatus(GameStatus.VICTORY);
      } else {
        setStatus(GameStatus.STAGE_SELECT);
        setSelectedStage(null);
      }
    }
  }, [status, defeatedStages]);

  const handleSelectStage = useCallback((stage: string) => {
    if (defeatedStages.includes(stage)) return;
    setSelectedStage(stage);
    setHealth(INITIAL_PLAYER_HEALTH);
    setScore(0);
    setChargeCooldown(0);
    setStatus(GameStatus.PLAYING);
  }, [defeatedStages]);

  const handleBossEncounter = useCallback(async () => {
    setStatus(GameStatus.BOSS_INTRO);
    const taunt = await getBossTaunt(selectedStage || "The Boss");
    setBossTaunt(taunt);
  }, [selectedStage]);

  const handleBossDefeated = useCallback(async (stageId: string) => {
    setDefeatedStages(prev => [...prev, stageId]);
    const speech = await getMeatheadVictorySpeech(stageId);
    setVictorySpeech(speech);
    setStatus(GameStatus.BOSS_VICTORY_SPEECH);
  }, []);

  const handleGameOver = useCallback((victory: boolean) => {
    if (!victory) setStatus(GameStatus.GAME_OVER);
  }, []);

  const handlePlayerUpdate = useCallback((h: number, cc: number, s: number) => {
    setHealth(h);
    setChargeCooldown(cc);
    setScore(s);
  }, []);

  return (
    <div className="relative w-screen h-screen flex items-center justify-center bg-black overflow-hidden">
      <div className="relative shadow-2xl border-4 border-gray-800 bg-[#121212]" style={{ width: 800, height: 600 }}>
        {(status === GameStatus.PLAYING || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) && (
          <HUD 
            health={health} 
            maxHealth={INITIAL_PLAYER_HEALTH} 
            chargeCooldown={chargeCooldown} 
            maxChargeCooldown={CHARGE_COOLDOWN}
            score={score}
          />
        )}

        <Overlay 
          status={status} 
          onStart={handleStart} 
          onSelectStage={handleSelectStage}
          bossTaunt={bossTaunt}
          victorySpeech={victorySpeech}
          briefing={briefing}
          score={score}
          defeatedStages={defeatedStages}
        />

        <GameCanvas 
          status={status}
          stageId={selectedStage}
          onPlayerUpdate={handlePlayerUpdate}
          onBossEncounter={handleBossEncounter}
          onBossDefeated={handleBossDefeated}
          onGameOver={handleGameOver}
        />
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { GameStatus } from '../types';

interface OverlayProps {
  status: GameStatus;
  onStart: () => void;
  onSelectStage?: (stage: string) => void;
  bossTaunt?: string;
  victorySpeech?: string;
  briefing?: string;
  score?: number;
  defeatedStages?: string[];
}

const STAGES = [
  { id: 'Artie Avalanche', color: 'bg-blue-600' },
  { id: 'Victor Volcano', color: 'bg-orange-600' },
  { id: 'Ernie Earthquake', color: 'bg-amber-800' },
  { id: 'Hector Hurricane', color: 'bg-cyan-600' }
];

const Overlay: React.FC<OverlayProps> = ({ status, onStart, onSelectStage, bossTaunt, victorySpeech, briefing, score, defeatedStages = [] }) => {
  if (status === GameStatus.PLAYING) return null;

  return (
    <div className="absolute inset-0 bg-black/85 flex flex-col items-center justify-center z-50 p-10 text-center">
      {status === GameStatus.START && (
        <div className="animate-pulse">
          <h1 className="text-6xl text-red-600 mb-4 font-bold tracking-tighter shadow-red-500 shadow-sm">MEATHEAD</h1>
          <p className="text-white text-sm mb-10 max-w-lg leading-relaxed border-y border-red-900 py-4 px-2">
            {briefing}
          </p>
          <button 
            onClick={onStart}
            className="px-10 py-5 bg-red-700 hover:bg-red-500 text-white text-xl border-b-8 border-red-900 active:border-b-0 transition-all font-bold"
          >
            START MISSION
          </button>
        </div>
      )}

      {status === GameStatus.STAGE_SELECT && (
        <div className="w-full h-full flex flex-col items-center justify-center">
          <h2 className="text-3xl text-white mb-8 font-black tracking-widest">SELECT TARGET</h2>
          <div className="grid grid-cols-2 gap-6">
            {STAGES.map((stage) => {
              const isDefeated = defeatedStages.includes(stage.id);
              return (
                <button
                  key={stage.id}
                  disabled={isDefeated}
                  onClick={() => onSelectStage?.(stage.id)}
                  className={`w-64 h-32 ${isDefeated ? 'bg-gray-800 opacity-50 grayscale' : stage.color} border-4 border-white hover:scale-105 transition-transform flex flex-col items-center justify-center p-4 relative overflow-hidden`}
                >
                  <div className="bg-black/40 w-full h-full flex items-center justify-center border-2 border-black">
                     <span className="text-white text-xs font-bold leading-tight">{stage.id.toUpperCase()}</span>
                  </div>
                  {isDefeated && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/60">
                      <span className="text-red-500 text-lg font-black rotate-12 border-4 border-red-500 p-2">TERMINATED</span>
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {status === GameStatus.BOSS_INTRO && (
        <div className="bg-red-950 border-4 border-red-600 p-8 max-w-xl">
          <h2 className="text-3xl text-red-500 mb-4 font-bold tracking-tighter">TARGET ACQUIRED</h2>
          <p className="text-white italic text-lg mb-8">"{bossTaunt}"</p>
          <button 
            onClick={onStart}
            className="px-8 py-4 bg-red-600 text-white text-sm hover:bg-red-400 font-bold border-b-4 border-red-900"
          >
            ENGAGE
          </button>
        </div>
      )}

      {status === GameStatus.BOSS_VICTORY_SPEECH && (
        <div className="bg-blue-950/90 border-4 border-blue-400 p-8 max-w-2xl animate-in fade-in zoom-in duration-300">
          <h2 className="text-2xl text-yellow-400 mb-6 font-bold uppercase tracking-widest">Meathead's Reflection</h2>
          <p className="text-white text-lg leading-relaxed mb-10 font-medium">"{victorySpeech}"</p>
          <button 
            onClick={onStart}
            className="px-10 py-5 bg-yellow-600 hover:bg-yellow-400 text-white font-bold border-b-4 border-yellow-800"
          >
            CONTINUE MISSION
          </button>
        </div>
      )}

      {status === GameStatus.GAME_OVER && (
        <div>
          <h2 className="text-6xl text-red-700 mb-4 font-black">WASTED.</h2>
          <button onClick={onStart} className="px-10 py-5 bg-red-700 hover:bg-red-500 text-white font-bold border-b-8 border-red-900">
            RETRY
          </button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="animate-bounce">
          <h2 className="text-5xl text-yellow-400 mb-4 font-black">ALL TARGETS NEUTRALIZED</h2>
          <p className="text-white text-lg mb-8">THE WORLD IS SAFE... AND BUFF.</p>
          <button onClick={onStart} className="px-10 py-5 bg-yellow-600 hover:bg-yellow-400 text-white font-bold border-b-8 border-yellow-900">
            RETURN TO MENU
          </button>
        </div>
      )}
    </div>
  );
};

export default Overlay;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES 
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED",
  "SUCK ON THIS", "BITE ME", "HELL NO", "BULLSHIT", "DUMBASS"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "SON OF A WHORE", 
  "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL", "FUCKING HELL"
];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const isSpeakingRef = useRef(false);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (isSpeakingRef.current || (window.speechSynthesis && window.speechSynthesis.speaking)) return;
    let pool = KILL_VULGARITIES;
    if (category === 'hurt') pool = HURT_VULGARITIES;
    if (category === 'death') pool = DEATH_VULGARITIES;
    const text = pool[Math.floor(Math.random() * pool.length)];
    gameStateRef.current.lastVulgarity = text;
    gameStateRef.current.vulgarityTimer = 60;
    if ('speechSynthesis' in window) {
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.2; utterance.rate = 1.1; utterance.volume = 1.0;
      utterance.onstart = () => { isSpeakingRef.current = true; };
      utterance.onend = () => { isSpeakingRef.current = false; };
      window.speechSynthesis.speak(utterance);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 3000, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: 3000, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: 3000, h: 50, type: 'ground' },
      { x: 2200, y: 400, w: 40, h: 150, type: 'door' }, // Boss Door
    ];

    if (stageId === 'Artie Avalanche') {
      state.blocks.push({ x: 400, y: 450, w: 200, h: 20, type: 'platform' }, { x: 700, y: 350, w: 200, h: 20, type: 'platform' }, { x: 1000, y: 250, w: 200, h: 20, type: 'platform' });
    } else if (stageId === 'Victor Volcano') {
      state.blocks.push({ x: 300, y: 480, w: 100, h: 70, type: 'block' }, { x: 900, y: 480, w: 100, h: 70, type: 'block' });
    }

    state.enemies = [
      { id: 'e1', pos: { x: 500, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 500, shootTimer: 0 },
      { id: 'e2', pos: { x: 1200, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 1200, shootTimer: 0 },
      { id: 'boss', pos: { x: 2700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 600, maxHealth: 600, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 2700, shootTimer: 0 },
    ];
  }, [stageId]);

  const spawnParticles = (pos: Vector2, color: string, count: number = 10) => {
    for (let i = 0; i < count; i++) {
      gameStateRef.current.particles.push({
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * 10, y: (Math.random() - 0.5) * 10 },
        life: 30 + Math.random() * 20, color, size: 2 + Math.random() * 4
      });
    }
  };

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    // Arena Logic
    if (player.pos.x > 2180 && !state.arenaLocked) {
      state.arenaLocked = true;
      state.doorOpenAmount = 1;
      player.vel.x = 0;
    }
    if (state.arenaLocked && state.doorOpenAmount > 0 && state.doorOpenAmount < 150) {
        state.doorOpenAmount += 5;
    }

    // Ducking logic
    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) {
        player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE;
        player.isGrounded = false;
        if (player.isCharging) spawnParticles(player.pos, COLORS.MEATHEAD_GLOW, 25);
      }
    } else if (player.landTimer > 0) {
      player.landTimer--;
      player.vel.x *= 0.5;
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else {
          player.vel.x *= FRICTION;
        }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--;
        player.vel.x = player.facing * CHARGE_SPEED;
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * (PLAYER_SPEED + 6); }
      }

      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN;
        player.vel.x = player.facing * CHARGE_SPEED;
      }

      if (shootRequested && player.shootCooldown <= 0) {
        const shootY = player.isDucking ? player.pos.y + 45 : player.pos.y + 25;
        projectiles.push({
          id: `p-${Date.now()}`,
          pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: shootY },
          vel: { x: player.facing * 16, y: 0 },
          width: 14, height: 4, health: 1, maxHealth: 1, type: 'projectile', damage: 15, owner: 'player'
        });
        player.shootCooldown = 10;
      }
    }

    if (player.chargeCooldown > 0) player.chargeCooldown--;
    if (player.shootCooldown > 0) player.shootCooldown--;
    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    // Collisions
    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorOpenAmount > 0) return;
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) {
          player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w;
          player.vel.x = 0;
        } else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) {
            player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0;
          } else {
            player.pos.y = block.y + block.h; player.vel.y = 0;
          }
        }
      }
    });

    // Enemies
    state.enemies = enemies.filter(enemy => {
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot') {
        enemy.shootTimer++;
        if (enemy.shootTimer > 70) {
          projectiles.push({
            id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 },
            width: 12, height: 12, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy'
          });
          enemy.shootTimer = 0;
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && player.pos.x > 2300) {
        state.bossSpawned = true;
        onBossEncounter();
      }

      const isHit = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHit) {
        if (player.isCharging) { enemy.health -= 100; spawnParticles(enemy.pos, '#fff', 15); }
        else if (state.frame % 40 === 0) { player.health -= 15; speakVulgarity('hurt'); }
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 10000 : 250;
        spawnParticles(enemy.pos, '#fff', 30);
        speakVulgarity('kill');
        if (enemy.type === 'boss' && stageId) onBossDefeated(stageId);
        return false;
      }
      return true;
    });

    // Projectiles
    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 100 || p.pos.x > state.camera.x + CANVAS_WIDTH + 100) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            enemy.health -= p.damage; spawnParticles(p.pos, COLORS.PROJECTILE_PLAYER, 5); return false;
          }
        }
      } else {
        if (!player.isCharging && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; spawnParticles(p.pos, COLORS.PROJECTILE_ENEMY, 5); speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });

    // Camera Locking
    if (!state.arenaLocked) {
        state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);
    } else {
        state.camera.x = 2200;
    }

    if (player.health <= 0 || player.pos.y > 1000) {
      if (player.health > 0) player.health = 0; 
      speakVulgarity('death');
      player.vel.x = 0; player.vel.y = 0;
      setTimeout(() => onGameOver(false), 1500);
    }

    onPlayerUpdate(player.health, player.chargeCooldown, state.score);

  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    ctx.save();
    let drawX = p.pos.x;
    let drawY = p.pos.y;
    let drawW = p.width;
    let drawH = p.height;

    if (p.isDucking) {
      drawY += 24; drawH -= 24;
    } else if (p.jumpPrepTimer > 0 || p.landTimer > 0) {
      drawY += 12; drawH -= 12; drawX -= 4; drawW += 8;
    }

    if (p.isCharging) {
      drawW += 20; drawX -= p.facing === 1 ? 5 : 15;
      ctx.translate(drawX + drawW/2, drawY + drawH/2);
      ctx.rotate(p.facing * 0.1);
      ctx.translate(-(drawX + drawW/2), -(drawY + drawH/2));
    }

    ctx.fillStyle = COLORS.MEATHEAD_SKIN;
    ctx.fillRect(drawX, drawY, drawW, drawH * 0.65);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS;
    ctx.fillRect(drawX, drawY + drawH * 0.65, drawW, drawH * 0.35);

    const eyeX = p.facing === 1 ? drawX + drawW - 14 : drawX + 4;
    const eyeY = p.isDucking ? drawY + 6 : drawY + 12;
    ctx.fillStyle = '#000';
    ctx.fillRect(eyeX, eyeY - 2, 12, 3);
    ctx.fillStyle = '#fff';
    ctx.fillRect(eyeX + 2, eyeY + 1, 3, 2);
    ctx.fillRect(eyeX + 7, eyeY + 1, 3, 2);

    ctx.fillStyle = '#222';
    const gunX = p.facing === 1 ? drawX + drawW - 8 : drawX - 12;
    const gunY = p.isDucking ? drawY + drawH * 0.3 : drawY + drawH * 0.45;
    ctx.fillRect(gunX, gunY, 22, 9);
    ctx.fillRect(p.facing === 1 ? gunX + 2 : gunX + 15, gunY + 5, 5, 12);

    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"';
      ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
      ctx.fillRect(drawX - 10, drawY - 35, ctx.measureText(txt).width + 20, 20);
      ctx.fillStyle = 'white';
      ctx.fillText(txt, drawX, drawY - 20);
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    ctx.fillStyle = COLORS.BG_DARK;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') {
        ctx.fillStyle = '#444';
        ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h);
      } else {
        ctx.fillStyle = COLORS.GROUND;
        ctx.fillRect(b.x, b.y, b.w, b.h);
      }
    });

    enemies.forEach(e => {
      ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
      ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      ctx.fillStyle = '#440000'; ctx.fillRect(e.pos.x, e.pos.y - 12, e.width, 4);
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 12, (e.health / e.maxHealth) * e.width, 4);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => {
      ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
      ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
    });
    particles.forEach(p => {
      ctx.globalAlpha = p.life / 50; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
    });
    ctx.globalAlpha = 1;
    ctx.restore();
  }, [stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) {
          gameStateRef.current.frame = 0;
      }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-2 border-gray-700" />;
};

export default GameCanvas;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getBossTaunt(bossName: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a short, menacing one-line taunt from a robotic boss named "${bossName}" directed at a beefy shirtless man named "Meathead". Meathead is a hyper-masculine hero. Keep it under 15 words.`,
      config: {
        temperature: 0.9,
      }
    });
    return response.text || "PREPARE FOR TERMINATION, MUSCLE-BRAIN.";
  } catch (error) {
    return "MEATHEAD... YOUR GAINS END HERE.";
  }
}

export async function getMissionBriefing() {
  return "Your mission is to kill everything in sight.";
}

export async function getMeatheadVictorySpeech(bossName: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a long, verbose, and extremely macho monologue delivered by "Meathead" (a beefy shirtless hero) standing over the wreckage of "${bossName}". He should sound like a mix of a philosophy professor and a bodybuilder. He must mention how his pure testosterone and muscle density overcame the "great mechanical evil" of ${bossName}. Make it 5-6 sentences, very dramatic, and use high-level vocabulary.`,
      config: {
        temperature: 1.0,
      }
    });
    return response.text || "Thy metallic shell could not withstand the sheer pressure of my pectorals. Thou art but scrap metal now, a trivial obstacle in the path of my glorious pump.";
  } catch (error) {
    return "Your circuitry was no match for my biological superiority. I have crushed the gears of tyranny with the fist of destiny.";
  }
}

import React, { useCallback } from 'react';
import { GameStatus } from '../types';

interface OverlayProps {
  status: GameStatus;
  onStart: () => void;
  onSelectStage?: (stage: string) => void;
  bossTaunt?: string;
  victorySpeech?: string;
  briefing?: string;
  score?: number;
  defeatedStages?: string[];
}

const STAGES = [
  { id: 'Artie Avalanche', color: 'bg-blue-600' },
  { id: 'Victor Volcano', color: 'bg-orange-600' },
  { id: 'Ernie Earthquake', color: 'bg-amber-800' },
  { id: 'Hector Hurricane', color: 'bg-cyan-600' }
];

const REBUKES = [
  "I ALREADY KILLED HIM, YOU DUMB FUCK.",
  "THAT SHIT-STAIN IS ALREADY GONE. FOCUS, COWARD.",
  "HE'S SCRAP METAL. QUIT WASTING MY PRECIOUS GAINS.",
  "I ALREADY OBLITERATED THAT TRASH. PICK SOMEONE ELSE."
];

const Overlay: React.FC<OverlayProps> = ({ status, onStart, onSelectStage, bossTaunt, victorySpeech, briefing, score, defeatedStages = [] }) => {
  const speakRebuke = useCallback(() => {
    if ('speechSynthesis' in window) {
      const text = REBUKES[Math.floor(Math.random() * REBUKES.length)];
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1;
      utterance.rate = 1.2;
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  if (status === GameStatus.PLAYING) return null;

  return (
    <div className="absolute inset-0 bg-black/90 flex flex-col items-center justify-center z-50 p-6 md:p-10 text-center">
      {status === GameStatus.START && (
        <div className="animate-pulse">
          <h1 className="text-4xl md:text-6xl text-red-600 mb-4 font-bold tracking-tighter shadow-red-500 shadow-sm">MEATHEAD</h1>
          <p className="text-white text-xs md:text-sm mb-10 max-w-lg leading-relaxed border-y border-red-900 py-4 px-2">
            {briefing}
          </p>
          <button 
            onClick={onStart}
            className="px-10 py-5 bg-red-700 hover:bg-red-500 text-white text-xl border-b-8 border-red-900 active:border-b-0 transition-all font-bold"
          >
            START MISSION
          </button>
        </div>
      )}

      {status === GameStatus.STAGE_SELECT && (
        <div className="w-full h-full flex flex-col items-center justify-center overflow-y-auto">
          <h2 className="text-2xl md:text-3xl text-white mb-8 font-black tracking-widest">SELECT TARGET</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
            {STAGES.map((stage) => {
              const isDefeated = defeatedStages.includes(stage.id);
              return (
                <button
                  key={stage.id}
                  onClick={() => isDefeated ? speakRebuke() : onSelectStage?.(stage.id)}
                  className={`w-56 md:w-64 h-24 md:h-32 ${isDefeated ? 'bg-gray-800 opacity-60 grayscale' : stage.color} border-4 border-white hover:scale-105 transition-transform flex flex-col items-center justify-center p-4 relative overflow-hidden`}
                >
                  <div className="bg-black/40 w-full h-full flex items-center justify-center border-2 border-black">
                     <span className="text-white text-[10px] md:text-xs font-bold leading-tight uppercase">{stage.id}</span>
                  </div>
                  {isDefeated && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/60 pointer-events-none">
                      <span className="text-red-500 text-sm md:text-lg font-black rotate-12 border-2 md:border-4 border-red-500 p-1 md:p-2 uppercase">Terminated</span>
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {status === GameStatus.BOSS_INTRO && (
        <div className="bg-red-950 border-4 border-red-600 p-8 max-w-xl animate-in fade-in slide-in-from-top-4 duration-500">
          <h2 className="text-2xl md:text-3xl text-red-500 mb-4 font-bold tracking-tighter">TARGET ACQUIRED</h2>
          <div className="max-h-32 overflow-y-auto mb-8 px-2 scrollbar-hide">
            <p className="text-white italic text-lg leading-tight">"{bossTaunt}"</p>
          </div>
          <button 
            onClick={onStart}
            className="px-8 py-4 bg-red-600 text-white text-sm hover:bg-red-400 font-bold border-b-4 border-red-900"
          >
            ENGAGE
          </button>
        </div>
      )}

      {status === GameStatus.BOSS_VICTORY_SPEECH && (
        <div className="bg-blue-950/95 border-4 border-blue-400 p-6 md:p-8 max-w-2xl max-h-[80%] flex flex-col animate-in fade-in zoom-in duration-300">
          <h2 className="text-xl md:text-2xl text-yellow-400 mb-4 font-bold uppercase tracking-widest shrink-0">MEATHEAD'S GLORIOUS REFLECTION</h2>
          <div className="overflow-y-auto mb-6 pr-4 text-left custom-scrollbar bg-black/20 p-4 rounded">
            <p className="text-white text-sm md:text-base leading-relaxed font-medium italic">"{victorySpeech}"</p>
          </div>
          <button 
            onClick={onStart}
            className="px-8 py-4 bg-yellow-600 hover:bg-yellow-400 text-white font-bold border-b-4 border-yellow-800 shrink-0"
          >
            I'M NOT DONE YET
          </button>
        </div>
      )}

      {status === GameStatus.GAME_OVER && (
        <div>
          <h2 className="text-5xl md:text-6xl text-red-700 mb-6 font-black">WASTED.</h2>
          <button onClick={onStart} className="px-10 py-5 bg-red-700 hover:bg-red-500 text-white font-bold border-b-8 border-red-900 uppercase">
            Try again, pussy
          </button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="animate-bounce">
          <h2 className="text-4xl md:text-5xl text-yellow-400 mb-4 font-black">ALL TARGETS NEUTRALIZED</h2>
          <p className="text-white text-lg mb-8 uppercase tracking-tighter">The world is safe... and shredded.</p>
          <button onClick={onStart} className="px-10 py-5 bg-yellow-600 hover:bg-yellow-400 text-white font-bold border-b-8 border-yellow-900">
            MAIN MENU
          </button>
        </div>
      )}
    </div>
  );
};

export default Overlay;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES 
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED",
  "SUCK ON THIS", "BITE ME", "HELL NO", "BULLSHIT", "DUMBASS"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "SON OF A WHORE", 
  "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL", "FUCKING HELL"
];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const isSpeakingRef = useRef(false);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (isSpeakingRef.current || (window.speechSynthesis && window.speechSynthesis.speaking)) return;
    let pool = KILL_VULGARITIES;
    if (category === 'hurt') pool = HURT_VULGARITIES;
    if (category === 'death') pool = DEATH_VULGARITIES;
    const text = pool[Math.floor(Math.random() * pool.length)];
    gameStateRef.current.lastVulgarity = text;
    gameStateRef.current.vulgarityTimer = 60;
    if ('speechSynthesis' in window) {
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.2; utterance.rate = 1.1; utterance.volume = 1.0;
      utterance.onstart = () => { isSpeakingRef.current = true; };
      utterance.onend = () => { isSpeakingRef.current = false; };
      window.speechSynthesis.speak(utterance);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 3000, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: 3000, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: 3000, h: 50, type: 'ground' },
      { x: 2200, y: 400, w: 40, h: 150, type: 'door' }, // Interactive Boss Door
    ];

    if (stageId === 'Artie Avalanche') {
      state.blocks.push({ x: 400, y: 450, w: 200, h: 20, type: 'platform' }, { x: 700, y: 350, w: 200, h: 20, type: 'platform' }, { x: 1000, y: 250, w: 200, h: 20, type: 'platform' });
    } else if (stageId === 'Victor Volcano') {
      state.blocks.push({ x: 300, y: 480, w: 100, h: 70, type: 'block' }, { x: 900, y: 480, w: 100, h: 70, type: 'block' });
    }

    state.enemies = [
      { id: 'e1', pos: { x: 500, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 500, shootTimer: 0 },
      { id: 'e2', pos: { x: 1200, y: 490 }, vel: { x: 2, y: 0 }, width: 40, height: 40, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'drone', behavior: 'patrol', patrolRange: 200, initialX: 1200, shootTimer: 0 },
      { id: 'boss', pos: { x: 2700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 600, maxHealth: 600, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 2700, shootTimer: 0 },
    ];
  }, [stageId]);

  const spawnParticles = (pos: Vector2, color: string, count: number = 10) => {
    for (let i = 0; i < count; i++) {
      gameStateRef.current.particles.push({
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * 10, y: (Math.random() - 0.5) * 10 },
        life: 30 + Math.random() * 20, color, size: 2 + Math.random() * 4
      });
    }
  };

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    // Door Animation Sequencing
    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5;
      if (state.doorOpenAmount >= 150) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 2250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5;
      if (state.doorOpenAmount <= 0) {
        state.doorOpenAmount = 0;
        state.doorState = 'done';
        state.arenaLocked = true;
      }
    }

    // Ducking logic
    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) {
        player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE;
        player.isGrounded = false;
        if (player.isCharging) spawnParticles(player.pos, COLORS.MEATHEAD_GLOW, 25);
      }
    } else if (player.landTimer > 0) {
      player.landTimer--;
      player.vel.x *= 0.5;
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else {
          player.vel.x *= FRICTION;
        }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--;
        player.vel.x = player.facing * CHARGE_SPEED;
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * (PLAYER_SPEED + 6); }
      }

      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN;
        player.vel.x = player.facing * CHARGE_SPEED;
      }

      if (shootRequested && player.shootCooldown <= 0) {
        const shootY = player.isDucking ? player.pos.y + 45 : player.pos.y + 25;
        projectiles.push({
          id: `p-${Date.now()}`,
          pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: shootY },
          vel: { x: player.facing * 16, y: 0 },
          width: 14, height: 4, health: 1, maxHealth: 1, type: 'projectile', damage: 15, owner: 'player'
        });
        player.shootCooldown = 10;
      }
    }

    if (player.chargeCooldown > 0) player.chargeCooldown--;
    if (player.shootCooldown > 0) player.shootCooldown--;
    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    // Collisions
    player.isGrounded = false;
    blocks.forEach(block => {
      // Ignore collision if door is open or opening/closing
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;

      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);

        if (block.type === 'door' && state.doorState === 'closed') {
           state.doorState = 'opening';
           return;
        }

        if (overlapX < overlapY) {
          player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w;
          player.vel.x = 0;
        } else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) {
            player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0;
          } else {
            player.pos.y = block.y + block.h; player.vel.y = 0;
          }
        }
      }
    });

    // Enemies
    state.enemies = enemies.filter(enemy => {
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.shootTimer > 70) {
          projectiles.push({
            id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 },
            width: 12, height: 12, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy'
          });
          enemy.shootTimer = 0;
        }
      }

      // Boss encounter trigger ONLY after door is shut
      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') {
        state.bossSpawned = true;
        onBossEncounter();
      }

      const isHit = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHit) {
        if (player.isCharging) { enemy.health -= 100; spawnParticles(enemy.pos, '#fff', 15); }
        else if (state.frame % 40 === 0) { player.health -= 15; speakVulgarity('hurt'); }
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 10000 : 250;
        spawnParticles(enemy.pos, '#fff', 30);
        speakVulgarity('kill');
        if (enemy.type === 'boss' && stageId) onBossDefeated(stageId);
        return false;
      }
      return true;
    });

    // Projectiles
    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 100 || p.pos.x > state.camera.x + CANVAS_WIDTH + 100) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            enemy.health -= p.damage; spawnParticles(p.pos, COLORS.PROJECTILE_PLAYER, 5); return false;
          }
        }
      } else {
        if (!player.isCharging && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; spawnParticles(p.pos, COLORS.PROJECTILE_ENEMY, 5); speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });

    // Camera Locking
    if (!state.arenaLocked) {
        state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);
    } else {
        state.camera.x = 2200;
    }

    if (player.health <= 0 || player.pos.y > 1000) {
      if (player.health > 0) player.health = 0; 
      speakVulgarity('death');
      player.vel.x = 0; player.vel.y = 0;
      setTimeout(() => onGameOver(false), 1500);
    }

    onPlayerUpdate(player.health, player.chargeCooldown, state.score);

  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    ctx.save();
    let drawX = p.pos.x;
    let drawY = p.pos.y;
    let drawW = p.width;
    let drawH = p.height;

    if (p.isDucking) {
      drawY += 24; drawH -= 24;
    } else if (p.jumpPrepTimer > 0 || p.landTimer > 0) {
      drawY += 12; drawH -= 12; drawX -= 4; drawW += 8;
    }

    if (p.isCharging) {
      drawW += 20; drawX -= p.facing === 1 ? 5 : 15;
      ctx.translate(drawX + drawW/2, drawY + drawH/2);
      ctx.rotate(p.facing * 0.1);
      ctx.translate(-(drawX + drawW/2), -(drawY + drawH/2));
    }

    ctx.fillStyle = COLORS.MEATHEAD_SKIN;
    ctx.fillRect(drawX, drawY, drawW, drawH * 0.65);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS;
    ctx.fillRect(drawX, drawY + drawH * 0.65, drawW, drawH * 0.35);

    const eyeX = p.facing === 1 ? drawX + drawW - 14 : drawX + 4;
    const eyeY = p.isDucking ? drawY + 6 : drawY + 12;
    ctx.fillStyle = '#000';
    ctx.fillRect(eyeX, eyeY - 2, 12, 3);
    ctx.fillStyle = '#fff';
    ctx.fillRect(eyeX + 2, eyeY + 1, 3, 2);
    ctx.fillRect(eyeX + 7, eyeY + 1, 3, 2);

    ctx.fillStyle = '#222';
    const gunX = p.facing === 1 ? drawX + drawW - 8 : drawX - 12;
    const gunY = p.isDucking ? drawY + drawH * 0.3 : drawY + drawH * 0.45;
    ctx.fillRect(gunX, gunY, 22, 9);
    ctx.fillRect(p.facing === 1 ? gunX + 2 : gunX + 15, gunY + 5, 5, 12);

    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"';
      ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
      ctx.fillRect(drawX - 10, drawY - 35, ctx.measureText(txt).width + 20, 20);
      ctx.fillStyle = 'white';
      ctx.fillText(txt, drawX, drawY - 20);
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    ctx.fillStyle = COLORS.BG_DARK;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') {
        ctx.fillStyle = '#444';
        ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h);
        ctx.fillStyle = '#222';
        ctx.fillRect(b.x + 10, b.y - state.doorOpenAmount + 10, b.w - 20, b.h - 20);
      } else {
        ctx.fillStyle = COLORS.GROUND;
        ctx.fillRect(b.x, b.y, b.w, b.h);
      }
    });

    enemies.forEach(e => {
      ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
      ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      ctx.fillStyle = '#440000'; ctx.fillRect(e.pos.x, e.pos.y - 12, e.width, 4);
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 12, (e.health / e.maxHealth) * e.width, 4);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => {
      ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
      ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
    });
    particles.forEach(p => {
      ctx.globalAlpha = p.life / 50; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
    });
    ctx.globalAlpha = 1;
    ctx.restore();
  }, [stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0;
        gameStateRef.current.doorState = 'closed';
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) {
          gameStateRef.current.frame = 0;
      }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-2 border-gray-700" />;
};

export default GameCanvas;

