const Overlay: React.FC<OverlayProps> = ({ status, onStart, onSelectStage, bossTaunt, victorySpeech, briefing, score, defeatedStages = [] }) => {
  const speakVoice = useCallback((text: string) => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1;
      utterance.rate = 1.1;
      utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  const handleSelect = (id: string) => {
    if (defeatedStages.includes(id)) {
      speakVoice(REBUKES[Math.floor(Math.random() * REBUKES.length)]);
    } else if (onSelectStage) {
      onSelectStage(id);
    }
  };

  if (status === GameStatus.PLAYING) return null;

  return (
    <div className="absolute inset-0 bg-black/95 flex flex-col items-center justify-center z-50 p-6 md:p-10 text-center overflow-hidden">
      {status === GameStatus.START && (
        <div className="animate-in fade-in zoom-in duration-700">
          <MeatheadCaricature />
          <h1 className="text-6xl md:text-8xl text-red-600 mb-4 font-black tracking-tighter drop-shadow-[8px_8px_0px_white]">MEATHEAD</h1>
          <p className="text-white text-xs md:text-sm mb-10 max-w-xl leading-relaxed border-y border-red-900 py-4 px-4 italic uppercase tracking-widest">
            {briefing}
          </p>
          <button 
            onClick={onStart}
            className="px-16 py-6 bg-red-700 hover:bg-red-500 text-white text-3xl border-b-[12px] border-red-900 active:translate-y-2 active:border-b-0 transition-all font-black uppercase tracking-tighter"
          >
            START PUMP
          </button>
        </div>
      )}

      {status === GameStatus.STAGE_SELECT && (
        <div className="w-full h-full flex flex-col items-center justify-center animate-in slide-in-from-bottom-12 duration-500">
          <h2 className="text-3xl md:text-5xl text-white mb-12 font-black tracking-widest border-b-8 border-red-600 pb-4">TERMINATION LIST</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-12">
            {STAGES.map((stage) => {
              const isDefeated = defeatedStages.includes(stage.id);
              return (
                <button
                  key={stage.id}
                  onClick={() => handleSelect(stage.id)}
                  className={`w-64 md:w-80 h-28 md:h-36 ${isDefeated ? 'bg-gray-900 opacity-40 grayscale' : stage.color} border-4 md:border-8 border-white hover:scale-105 transition-transform flex flex-col items-center justify-center p-4 relative group shadow-[10px_10px_0px_0px_rgba(255,255,255,0.1)]`}
                >
                  <div className="bg-black/50 w-full h-full flex items-center justify-center border-4 border-white/20">
                     <span className="text-white text-xs md:text-sm font-black uppercase tracking-tighter">{stage.id}</span>
                  </div>
                  {isDefeated && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/80">
                      <span className="text-red-500 text-xl md:text-3xl font-black rotate-12 border-4 md:border-8 border-red-500 p-2 md:p-4 uppercase">CRUSHED</span>
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {status === GameStatus.BOSS_INTRO && (
        <div className="bg-red-950/90 border-8 border-red-600 p-10 max-w-2xl animate-in fade-in slide-in-from-top-6 duration-500 shadow-[0_0_80px_rgba(255,0,0,0.5)]">
          <h2 className="text-3xl md:text-4xl text-red-500 mb-8 font-black tracking-tighter italic uppercase underline decoration-4">Mechanical Trash Talking:</h2>
          <div className="max-h-40 overflow-y-auto mb-10 px-6 text-left border-l-8 border-red-500 bg-black/40 py-6 scrollbar-hide">
            <p className="text-white italic text-xl md:text-2xl leading-snug uppercase tracking-tight">"{bossTaunt}"</p>
          </div>
          <button 
            onClick={onStart}
            className="px-14 py-6 bg-red-600 text-white text-2xl hover:bg-red-500 font-black border-b-[10px] border-red-900 active:translate-y-2 active:border-b-0"
          >
            SQUASH THIS BUG
          </button>
        </div>
      )}

      {status === GameStatus.BOSS_VICTORY_SPEECH && (
        <div className="bg-blue-900/95 border-[12px] border-blue-400 p-8 md:p-12 max-w-4xl max-h-[90%] flex flex-col animate-in fade-in zoom-in duration-500 shadow-[0_0_150px_rgba(0,0,255,0.5)]">
          <h2 className="text-3xl md:text-5xl text-yellow-400 mb-8 font-black uppercase tracking-widest italic shrink-0 underline decoration-8 underline-offset-8">Meathead's Epitaph</h2>
          <div className="overflow-y-auto mb-10 pr-6 text-left bg-black/50 p-8 rounded-2xl border-4 border-white/20 custom-scrollbar">
            <p className="text-white text-lg md:text-2xl leading-relaxed font-black italic tracking-tight">"{victorySpeech}"</p>
          </div>
          <button 
            onClick={onStart}
            className="px-16 py-7 bg-yellow-500 hover:bg-yellow-400 text-black text-2xl font-black border-b-[12px] border-yellow-800 active:translate-y-2 active:border-b-0 transition-all uppercase tracking-tighter"
          >
            ONTO THE NEXT PUMP
          </button>
        </div>
      )}

      {status === GameStatus.GAME_OVER && (
        <div className="animate-in zoom-in duration-300">
          <h2 className="text-8xl md:text-[10rem] text-red-800 mb-12 font-black tracking-tighter drop-shadow-[12px_12px_0px_black]">WASTED.</h2>
          <button onClick={onStart} className="px-20 py-10 bg-red-800 hover:bg-red-600 text-white font-black border-b-[15px] border-red-950 uppercase text-4xl tracking-tighter shadow-2xl">
            RE-LOAD MUSCLE
          </button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="animate-in fade-in duration-1000">
          <h2 className="text-7xl md:text-9xl text-yellow-400 mb-10 font-black tracking-tighter">PLANET SAVED</h2>
          <p className="text-white text-3xl mb-16 uppercase font-black tracking-widest italic drop-shadow-[4px_4px_0px_red]">Metal is scrap. Meat is King.</p>
          <button onClick={onStart} className="px-20 py-10 bg-yellow-600 hover:bg-yellow-400 text-white font-black border-b-[15px] border-yellow-900 text-4xl shadow-2xl">
            MAIN MENU
          </button>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 12px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: rgba(0, 0, 0, 0.4);
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #3b82f6;
          border-radius: 10px;
          border: 3px solid rgba(0,0,0,0.5);
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #60a5fa;
        }
      `}</style>
    </div>
  );
};

export default Overlay;

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  isDucking: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
  invincibilityTimer: number;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret';
  behavior: 'patrol' | 'shoot' | 'hover';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES 
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0 // Cooldown in frames to prevent voice spam
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    // Only speak if cooldown is finished
    if (gameStateRef.current.voiceLineCooldown > 0) return;

    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 

      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];

      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      // Set a cooldown so we don't spam. ~1.5 seconds
      gameStateRef.current.voiceLineCooldown = 90;

      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; 
      utterance.rate = 1.2; 
      utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);

      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + 0.1);
    } catch (e) {
      console.warn("Audio failed", e);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 7000; 
    const doorX = 6200;

    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
    ];

    // Platforms - Toned down density
    for (let i = 400; i < doorX - 400; i += 600) {
      const height = 380 - (Math.random() * 140);
      const width = 180 + (Math.random() * 120);
      state.blocks.push({ x: i, y: height, w: width, h: 25, type: 'platform' });
      if (Math.random() > 0.7) {
        state.blocks.push({ x: i + 150, y: height - 130, w: 140, h: 25, type: 'platform' });
      }
    }

    // Enemies - Toned down density
    state.enemies = [];
    for (let i = 1000; i < doorX - 300; i += 800) {
      const isTank = Math.random() > 0.7;
      state.enemies.push({
        id: `e-${i}`,
        pos: { x: i, y: 490 },
        vel: { x: isTank ? 0 : 2, y: 0 },
        width: isTank ? 60 : 40,
        height: isTank ? 60 : 40,
        health: isTank ? 200 : 50,
        maxHealth: isTank ? 200 : 50,
        type: 'enemy',
        enemyType: isTank ? 'tank' : 'drone',
        behavior: isTank ? 'shoot' : 'patrol',
        patrolRange: 250,
        initialX: i,
        shootTimer: Math.random() * 60
      });
    }

    // The Boss
    state.enemies.push({ 
      id: 'boss', pos: { x: 6700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 6700, shootTimer: 0 
    });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    // Decrease cooldowns
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    // Door sequence logic
    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5;
      if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 6250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5;
      if (state.doorOpenAmount <= 0) {
        state.doorOpenAmount = 0;
        state.doorState = 'done';
        state.arenaLocked = true;
      }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) {
        player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE;
        player.isGrounded = false;
      }
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else {
          player.vel.x *= FRICTION;
        }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--;
        player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      }

      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN;
        player.vel.x = player.facing * CHARGE_SPEED;
      }

      // Shooting Logic
      if (shootRequested && player.shootCooldown <= 0) {
        const bulletX = player.pos.x + (player.facing === 1 ? player.width : -10);
        const bulletY = player.isDucking ? player.pos.y + 45 : player.pos.y + 25;
        projectiles.push({
          id: `p-${Date.now()}`,
          pos: { x: bulletX, y: bulletY },
          vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; 
        playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && (state.doorState === 'opening' || state.doorState === 'open' || state.doorState === 'closing')) return;
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') {
           state.doorState = 'opening';
           return;
        }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) {
          player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w;
          player.vel.x = 0;
        } else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) {
            player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0;
          } else {
            player.pos.y = block.y + block.h; player.vel.y = 0;
          }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.shootTimer > 60) {
          projectiles.push({
            id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 },
            width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy'
          });
          enemy.shootTimer = 0;
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') {
        state.bossSpawned = true;
        onBossEncounter();
      }

      const isHit = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHit) {
        if (player.isCharging) { 
          enemy.health -= 150; 
          for(let i=0; i<5; i++) state.particles.push({ pos: {...enemy.pos}, vel: {x:(Math.random()-0.5)*10, y:(Math.random()-0.5)*10}, life: 20, color: '#fff', size: 3 });
        }
        else if (player.invincibilityTimer <= 0) { 
          player.health -= 15; 
          player.invincibilityTimer = 60; // 1 second i-frames
          speakVulgarity('hurt'); 
        }
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        speakVulgarity('kill');
        if (enemy.type === 'boss' && stageId) {
          setTimeout(() => onBossDefeated(stageId), 2000);
        }
        return false;
      }
      return true;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; 
          player.invincibilityTimer = 60; 
          speakVulgarity('hurt'); 
          return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });

    if (!state.arenaLocked) {
        state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);
    } else {
        state.camera.x = 6200;
    }

    if (player.health <= 0 || player.pos.y > 1000) {
      if (player.health > 0) player.health = 0; 
      speakVulgarity('death');
      setTimeout(() => onGameOver(false), 2000);
    }

    onPlayerUpdate(player.health, player.chargeCooldown, state.score);

  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    // Flicker during invincibility
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;

    ctx.save();
    let drawX = p.pos.x;
    let drawY = p.pos.y;
    let drawW = p.width;
    let drawH = p.height;

    if (p.isDucking) {
      drawY += 28; drawH -= 28;
    } else if (p.jumpPrepTimer > 0) {
      drawY += 15; drawH -= 15;
    }

    if (p.isCharging) {
      drawW += 20; 
      ctx.fillStyle = COLORS.MEATHEAD_GLOW;
      ctx.globalAlpha = 0.3;
      ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10);
      ctx.globalAlpha = 1.0;
    }

    ctx.fillStyle = COLORS.MEATHEAD_SKIN;
    ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS;
    ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);

    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);

    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 12px "Press Start 2P"';
      ctx.fillStyle = 'white';
      ctx.shadowColor = 'black';
      ctx.shadowBlur = 4;
      ctx.fillText(txt, drawX - 20, drawY - 20);
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    ctx.fillStyle = COLORS.BG_DARK;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') {
        ctx.fillStyle = '#555';
        ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h);
      } else {
        ctx.fillStyle = COLORS.GROUND;
        ctx.fillRect(b.x, b.y, b.w, b.h);
      }
    });

    enemies.forEach(e => {
      ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
      ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      ctx.fillStyle = '#00FF00'; 
      ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => {
      ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
      ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
    });
    particles.forEach(p => {
      ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
    });
    ctx.globalAlpha = 1;
    ctx.restore();
  }, [stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0 };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0;
        gameStateRef.current.doorState = 'closed';
        gameStateRef.current.voiceLineCooldown = 0;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) {
          gameStateRef.current.frame = 0;
      }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  isDucking: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
  invincibilityTimer: number;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret' | 'flyer' | 'shield';
  behavior: 'patrol' | 'shoot' | 'hover' | 'fly';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
  isShieldActive?: boolean;
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

export const CANVAS_WIDTH = 800;
export const CANVAS_HEIGHT = 600;

export const GRAVITY = 0.5;
export const FRICTION = 0.85;

export const PLAYER_SPEED = 5;
export const PLAYER_JUMP_FORCE = -12;
export const CHARGE_SPEED = 18;
export const CHARGE_DURATION = 25; 
export const CHARGE_COOLDOWN = 50; 
export const JUMP_PREP_FRAMES = 6;
