      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: ""
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120; // 2 sec cooldown
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;

    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
    ];

    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }

    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({
        id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true
      });
      state.enemies.push({
        id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0
      });
      state.enemies.push({
        id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0
      });
    }

    state.enemies.push({ 
      id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 
    });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.victoryAnimFrame++;
      if (state.victoryAnimFrame > 120) {
          onBossDefeated(stageId || "");
          state.victoryString = "";
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--; player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      }
      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN; player.vel.x = player.facing * CHARGE_SPEED;
      }
      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;

      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      const isHit = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHit) {
        if (player.isCharging && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) { 
            const chargeDamage = 50; // Two shots worth
            enemy.health -= chargeDamage; 
            enemy.hitCooldown = 15; // Prevent multi-hit every frame
            if (enemy.health > 0) {
                // Knockback
                enemy.pos.x += player.facing * 50;
                for(let i=0; i<8; i++) state.particles.push({ pos: {...enemy.pos}, vel: {x:(Math.random()-0.5)*12, y:(Math.random()-0.5)*12}, life: 15, color: '#fff', size: 3 });
            }
        }
        else if (!player.isCharging && player.invincibilityTimer <= 0) { player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt'); }
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 300);
        }
        return false;
      }
      return true;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) { state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2); }
    else { state.camera.x = 7200; }
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };

    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });

    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();

    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 60px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 8;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0 };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: ""
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * 15, 
          y: (Math.random() - 0.5) * 15 
        },
        life: 30 + Math.random() * 20,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;

    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
    ];

    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }

    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({
        id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true
      });
      state.enemies.push({
        id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0
      });
      state.enemies.push({
        id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0
      });
    }

    state.enemies.push({ 
      id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 
    });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.victoryAnimFrame++;
      if (state.victoryAnimFrame > 150) {
          onBossDefeated(stageId || "");
          state.victoryString = "";
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--; player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      }
      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN; player.vel.x = player.facing * CHARGE_SPEED;
      }
      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;

      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      const isHit = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHit) {
        if (player.isCharging && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) { 
            const chargeDamage = 50; 
            enemy.health -= chargeDamage; 
            enemy.hitCooldown = 20; 

            if (enemy.health > 0) {
                // Survivors sent flying fast several meters (pixels)
                enemy.vel.x = player.facing * 30; 
                spawnExplosion(enemy.pos, '#fff', 15, player.facing * 10);
            } else {
                // Dead enemies sent flying fast AND then they explode (simulated by high velocity particles)
                const flyVelX = player.facing * 40;
                spawnExplosion(enemy.pos, '#FF4500', 40, flyVelX);
                spawnExplosion(enemy.pos, '#FFFF00', 20, flyVelX);
                spawnExplosion(enemy.pos, '#8B0000', 30, flyVelX); // "Meat" bits
            }
        }
        else if (!player.isCharging && player.invincibilityTimer <= 0) { 
            player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt'); 
        }
      }

      // Add air friction to knockback for smooth "flying" effect
      if (Math.abs(enemy.vel.x) > 2) {
          enemy.vel.x *= 0.95;
      } else if (enemy.behavior === 'tank') {
          enemy.vel.x = 0;
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 400);
        }
        return false;
      }
      return true;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) { state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2); }
    else { state.camera.x = 7200; }
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };

    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });

    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();

    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0 };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: ""
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * 15, 
          y: (Math.random() - 0.5) * 15 
        },
        life: 30 + Math.random() * 20,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;

    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
    ];

    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }

    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({
        id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true
      });
      state.enemies.push({
        id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0
      });
      state.enemies.push({
        id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0
      });
    }

    state.enemies.push({ 
      id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 
    });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.victoryAnimFrame++;
      if (state.victoryAnimFrame > 150) {
          onBossDefeated(stageId || "");
          state.victoryString = "";
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--; player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      }
      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN; player.vel.x = player.facing * CHARGE_SPEED;
      }
      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;

      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      const isHit = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHit) {
        if (player.isCharging && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) { 
            const chargeDamage = 50; 
            enemy.health -= chargeDamage; 
            enemy.hitCooldown = 20; 

            if (enemy.health > 0) {
                // Survivors sent flying fast several meters (pixels)
                enemy.vel.x = player.facing * 30; 
                spawnExplosion(enemy.pos, '#fff', 15, player.facing * 10);
            } else {
                // Dead enemies sent flying fast AND then they explode (simulated by high velocity particles)
                const flyVelX = player.facing * 40;
                spawnExplosion(enemy.pos, '#FF4500', 40, flyVelX);
                spawnExplosion(enemy.pos, '#FFFF00', 20, flyVelX);
                spawnExplosion(enemy.pos, '#8B0000', 30, flyVelX); // "Meat" bits
            }
        }
        else if (!player.isCharging && player.invincibilityTimer <= 0) { 
            player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt'); 
        }
      }

      // Add air friction to knockback for smooth "flying" effect
      if (Math.abs(enemy.vel.x) > 2) {
          enemy.vel.x *= 0.95;
      // Fixed type error by checking enemyType instead of behavior for 'tank'
      } else if (enemy.enemyType === 'tank') {
          enemy.vel.x = 0;
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 400);
        }
        return false;
      }
      return true;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) { state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2); }
    else { state.camera.x = 7200; }
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };

    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });

    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();

    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0 };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: ""
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: 20 + Math.random() * 30,
        color: color,
        size: 2 + Math.random() * 5
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0) => {
    // Shred of scrap metal
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, 10, facing * 15, 20));
    // Shred of gore
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, 12, facing * 18, 25));
    // Fire/Smoke
    spawnExplosion(pos, '#FF4500', 20, facing * 10, 30);
    spawnExplosion(pos, '#FFFF00', 10, facing * 5, 20);
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;

    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
    ];

    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }

    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({
        id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true
      });
      state.enemies.push({
        id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0
      });
      state.enemies.push({
        id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0
      });
    }

    state.enemies.push({ 
      id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 
    });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.victoryAnimFrame++;
      if (state.victoryAnimFrame > 150) {
          onBossDefeated(stageId || "");
          state.victoryString = "";
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--; player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      }
      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN; player.vel.x = player.facing * CHARGE_SPEED;
      }
      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;

      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      const isHit = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHit) {
        if (player.isCharging && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) { 
            const chargeDamage = 50; 
            enemy.health -= chargeDamage; 
            enemy.hitCooldown = 15; 

            // Mass-based fly speed (Distance ≈ speed * 20 with 0.95 friction)
            // 800px (Full Screen) = 40 flySpeed
            // 200px (Quarter Screen) = 10 flySpeed
            let flySpeed = 0;
            switch(enemy.enemyType) {
              case 'flyer':
              case 'drone': flySpeed = 45; break; // Full screen
              case 'shield': flySpeed = 25; break; // Half screen
              case 'tank':   flySpeed = 12; break; // Quarter screen
              default:       flySpeed = 8; break;  // Boss
            }

            if (enemy.health > 0) {
                // Survivors sent flying several meters
                enemy.vel.x = player.facing * flySpeed; 
                spawnExplosion(enemy.pos, '#fff', 15, player.facing * 10);
            } else {
                // Dead enemies sent flying AND explode in scrap/gore
                enemy.vel.x = player.facing * flySpeed * 1.5; // Fly even faster when dead
                spawnDeathShower(enemy.pos, player.facing);
            }
        }
        else if (!player.isCharging && player.invincibilityTimer <= 0) { 
            player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt'); 
        }
      }

      // Air friction
      if (Math.abs(enemy.vel.x) > 1) {
          enemy.vel.x *= 0.95;
      } else if (enemy.enemyType === 'tank' || enemy.type === 'boss') {
          enemy.vel.x = 0;
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        spawnDeathShower(enemy.pos, 0); // Explosion on bullet kill too
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 400);
        }
        return false;
      }
      return true;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) { state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2); }
    else { state.camera.x = 7200; }
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, camera } = state;

    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };

    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });

    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();

    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0 };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: ""
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  // Explicitly clear memory when on select screens
  useEffect(() => {
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
      const state = gameStateRef.current;
      state.blocks = [];
      state.enemies = [];
      state.projectiles = [];
      state.particles = [];
      state.frame = 0;
      state.camera = { x: 0, y: 0 };
      state.bossSpawned = false;
      state.arenaLocked = false;
      state.doorState = 'closed';
      state.victoryString = "";
    }
  }, [status]);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: 20 + Math.random() * 40,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0) => {
    // Increased particle counts for intense "shower" effect
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, 15, facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, 20, facing * 22, 30));
    spawnExplosion(pos, '#FF4500', 30, facing * 12, 35);
    spawnExplosion(pos, '#FFFF00', 15, facing * 8, 25);
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;

    // Clear potential stale blocks before rebuild
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
    ];

    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }

    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({
        id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true
      });
      state.enemies.push({
        id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0
      });
      state.enemies.push({
        id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0
      });
    }

    state.enemies.push({ 
      id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 
    });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.victoryAnimFrame++;
      if (state.victoryAnimFrame > 150) {
          onBossDefeated(stageId || "");
          state.victoryString = "";
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--; player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      }
      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN; player.vel.x = player.facing * CHARGE_SPEED;
      }
      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;

      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      const isHitByPlayer = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHitByPlayer) {
        if (player.isCharging && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) { 
            const chargeDamage = 50; 
            enemy.health -= chargeDamage; 
            enemy.hitCooldown = 15; 

            // Mass-based knockback: bigger ones get pushed less
            let flySpeed = 0;
            if (enemy.type === 'boss') {
               flySpeed = 10; // Bosses are huge, pushed least
            } else {
              switch(enemy.enemyType) {
                case 'flyer':
                case 'drone': flySpeed = 48; break; // Tiny, fly far (full screen)
                case 'shield': flySpeed = 28; break; // Medium, fly half-screen
                case 'tank':   flySpeed = 15; break; // Large, fly quarter-screen
                default:       flySpeed = 20; break; 
              }
            }

            if (enemy.health > 0) {
                enemy.vel.x = player.facing * flySpeed; 
                spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12);
            } else {
                enemy.vel.x = player.facing * flySpeed * 1.5; 
                spawnDeathShower(enemy.pos, player.facing);
            }
        }
        else if (!player.isCharging && player.invincibilityTimer <= 0) { 
            player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt'); 
        }
      }

      // Air friction for knockback
      if (Math.abs(enemy.vel.x) > 1) {
          enemy.vel.x *= 0.94; // slightly higher friction for better feel
      } else if (enemy.enemyType === 'tank' || enemy.type === 'boss') {
          enemy.vel.x = 0;
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        spawnDeathShower(enemy.pos, 0); 
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 400);
        }
        return false;
      }
      return true;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) { state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2); }
    else { state.camera.x = 7200; }
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;

    // If not playing and frame is 0, clear to black
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
        return;
    }

    const { player, enemies, projectiles, particles, blocks, camera } = state;
    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };

    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });

    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();

    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [status, stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0 };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  isDucking: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
  invincibilityTimer: number;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret' | 'flyer' | 'shield';
  behavior: 'patrol' | 'shoot' | 'hover' | 'fly';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
  isShieldActive?: boolean;
  hitCooldown?: number; // To prevent multiple hits from one charge in one frame
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Pickup {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  type: 'small' | 'large';
  life: number;
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getBossTaunt(bossName: string) {
  const taunts: Record<string, string> = {
    'Artie Avalanche': 'Prepare for Freezer Burn, Meatface!',
    'Victor Volcano': "Well done, Meathead. That's how you'll be cooked.",
    'Hector Hurricane': 'Time to drown your sorrows....with DEATH!',
    'Ernie Earthquake': 'Are you ready to rumble?'
  };

  return taunts[bossName] || "PREPARE FOR TERMINATION, MUSCLE-BRAIN.";
}

export async function getMissionBriefing() {
  return "Your mission is to kill everything in sight for no particular reason.";
}

export async function getMeatheadVictorySpeech(bossName: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Meathead has just defeated "${bossName}". 
      Write a macho, philosophical monologue (60-80 words) where Meathead explains why his organic muscles beat ${bossName}'s specific elemental power. 
      He sounds like a bodybuilder who read Nietzsche.`,
      config: {
        temperature: 1.0,
      }
    });
    return response.text || "Your silicon spirit could not withstand the density of my pectorals. Evolution favors the pump.";
  } catch (error) {
    return "Your circuitry was no match for my biological superiority. I have crushed the gears of tyranny with the fist of destiny.";
  }
}

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: "",
    postVictoryTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  // Explicitly clear memory when on select screens
  useEffect(() => {
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
      const state = gameStateRef.current;
      state.blocks = [];
      state.enemies = [];
      state.projectiles = [];
      state.pickups = [];
      state.particles = [];
      state.frame = 0;
      state.camera = { x: 0, y: 0 };
      state.bossSpawned = false;
      state.arenaLocked = false;
      state.doorState = 'closed';
      state.victoryString = "";
      state.postVictoryTimer = 0;
    }
  }, [status]);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: 20 + Math.random() * 40,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0) => {
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, 15, facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, 20, facing * 22, 30));
    spawnExplosion(pos, '#FF4500', 30, facing * 12, 35);
    spawnExplosion(pos, '#FFFF00', 15, facing * 8, 25);
  };

  const spawnPickup = (pos: Vector2) => {
    const chance = Math.random();
    if (chance > 0.4) return; // 40% chance of drop

    const type = Math.random() > 0.8 ? 'large' : 'small';
    gameStateRef.current.pickups.push({
      id: `pickup-${Date.now()}-${Math.random()}`,
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -5 },
      width: type === 'large' ? 32 : 16,
      height: type === 'large' ? 32 : 16,
      type: type,
      life: 600 // 10 seconds
    });
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;

    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
      // Wall over the door to prevent jumping over
      { x: doorX, y: -1000, w: 40, h: 1400, type: 'wall' } 
    ];

    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }

    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({
        id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true
      });
      state.enemies.push({
        id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0
      });
      state.enemies.push({
        id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0
      });
    }

    state.enemies.push({ 
      id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 
    });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    // Victory Timing Logic: exactly 2 seconds after 'Y' shows up
    if (state.victoryString === "VICTORY") {
      state.postVictoryTimer++;
      if (state.postVictoryTimer > 120) { // 120 frames = 2 seconds at 60fps
          onBossDefeated(stageId || "");
          state.victoryString = "";
          state.postVictoryTimer = 0;
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--; player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      }
      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN; player.vel.x = player.facing * CHARGE_SPEED;
      }
      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;

      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      const isHitByPlayer = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHitByPlayer) {
        if (player.isCharging && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) { 
            const chargeDamage = 50; 
            enemy.health -= chargeDamage; 
            enemy.hitCooldown = 15; 

            let flySpeed = 0;
            if (enemy.type === 'boss') {
               flySpeed = 10;
            } else {
              switch(enemy.enemyType) {
                case 'flyer':
                case 'drone': flySpeed = 48; break; 
                case 'shield': flySpeed = 28; break; 
                case 'tank':   flySpeed = 15; break; 
                default:       flySpeed = 20; break; 
              }
            }

            if (enemy.health > 0) {
                enemy.vel.x = player.facing * flySpeed; 
                spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12);
            } else {
                enemy.vel.x = player.facing * flySpeed * 1.5; 
                spawnDeathShower(enemy.pos, player.facing);
                spawnPickup(enemy.pos);
            }
        }
        else if (!player.isCharging && player.invincibilityTimer <= 0) { 
            player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt'); 
        }
      }

      if (Math.abs(enemy.vel.x) > 1) {
          enemy.vel.x *= 0.94; 
      } else if (enemy.enemyType === 'tank' || enemy.type === 'boss') {
          enemy.vel.x = 0;
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        spawnDeathShower(enemy.pos, 0); 
        spawnPickup(enemy.pos);
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else {
                  clearInterval(interval);
                  // Trigger postVictoryTimer logic in update loop
                }
            }, 300);
        }
        return false;
      }
      return true;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY;
      p.pos.x += p.vel.x;
      p.pos.y += p.vel.y;
      p.vel.x *= 0.9;
      p.life--;

      blocks.forEach(block => {
        if (block.type === 'pit') return;
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          p.pos.y = block.y - p.height; p.vel.y = 0;
        }
      });

      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
        const healAmt = p.type === 'large' ? 50 : 20;
        player.health = Math.min(player.maxHealth, player.health + healAmt);
        return false;
      }
      return p.life > 0;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) { state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2); }
    else { state.camera.x = 7200; }
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;

    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
        return;
    }

    const { player, enemies, projectiles, particles, blocks, camera, pickups } = state;
    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };

    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });

    pickups.forEach(p => {
      ctx.fillStyle = 'red';
      const thick = p.type === 'large' ? 10 : 5;
      ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height);
      ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick);
    });

    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();

    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [status, stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0 };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
        gameStateRef.current.postVictoryTimer = 0;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  isDucking: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
  invincibilityTimer: number;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret' | 'flyer' | 'shield';
  behavior: 'patrol' | 'shoot' | 'hover' | 'fly';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
  isShieldActive?: boolean;
  hitCooldown?: number; // To prevent multiple hits from one charge in one frame
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Pickup {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  type: 'small' | 'large';
  life: number;
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: "",
    postVictoryTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  // Explicitly clear memory when on select screens
  useEffect(() => {
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
      const state = gameStateRef.current;
      state.blocks = [];
      state.enemies = [];
      state.projectiles = [];
      state.pickups = [];
      state.particles = [];
      state.frame = 0;
      state.camera = { x: 0, y: 0 };
      state.bossSpawned = false;
      state.arenaLocked = false;
      state.doorState = 'closed';
      state.victoryString = "";
      state.postVictoryTimer = 0;
    }
  }, [status]);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: 20 + Math.random() * 40,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0) => {
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, 15, facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, 20, facing * 22, 30));
    spawnExplosion(pos, '#FF4500', 30, facing * 12, 35);
    spawnExplosion(pos, '#FFFF00', 15, facing * 8, 25);
  };

  const spawnPickup = (pos: Vector2) => {
    const chance = Math.random();
    if (chance > 0.4) return; // 40% chance of drop

    const type = Math.random() > 0.8 ? 'large' : 'small';
    gameStateRef.current.pickups.push({
      id: `pickup-${Date.now()}-${Math.random()}`,
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -5 },
      width: type === 'large' ? 32 : 16,
      height: type === 'large' ? 32 : 16,
      type: type,
      life: 600 // 10 seconds
    });
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;

    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
      // Wall over the door to prevent jumping over
      { x: doorX, y: -1000, w: 40, h: 1400, type: 'wall' } 
    ];

    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }

    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({
        id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true
      });
      state.enemies.push({
        id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0
      });
      state.enemies.push({
        id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0
      });
    }

    state.enemies.push({ 
      id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 
    });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }

    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    // Victory Timing Logic: exactly 2 seconds after 'Y' shows up
    if (state.victoryString === "VICTORY") {
      state.postVictoryTimer++;
      if (state.postVictoryTimer > 120) { // 120 frames = 2 seconds at 60fps
          onBossDefeated(stageId || "");
          state.victoryString = "";
          state.postVictoryTimer = 0;
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else {
        player.chargeDuration--; player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      }
      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isDucking) {
        player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.chargeCooldown = CHARGE_COOLDOWN; player.vel.x = player.facing * CHARGE_SPEED;
      }
      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;

      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }

      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      const isHitByPlayer = player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHitByPlayer) {
        if (player.isCharging && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) { 
            const chargeDamage = 50; 
            enemy.health -= chargeDamage; 
            enemy.hitCooldown = 15; 

            let flySpeed = 0;
            if (enemy.type === 'boss') {
               flySpeed = 10;
            } else {
              switch(enemy.enemyType) {
                case 'flyer':
                case 'drone': flySpeed = 48; break; 
                case 'shield': flySpeed = 28; break; 
                case 'tank':   flySpeed = 15; break; 
                default:       flySpeed = 20; break; 
              }
            }

            if (enemy.health > 0) {
                enemy.vel.x = player.facing * flySpeed; 
                spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12);
            } else {
                enemy.vel.x = player.facing * flySpeed * 1.5; 
                spawnDeathShower(enemy.pos, player.facing);
                spawnPickup(enemy.pos);
            }
        }
        else if (!player.isCharging && player.invincibilityTimer <= 0) { 
            player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt'); 
        }
      }

      if (Math.abs(enemy.vel.x) > 1) {
          enemy.vel.x *= 0.94; 
      } else if (enemy.enemyType === 'tank' || enemy.type === 'boss') {
          enemy.vel.x = 0;
      }

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        spawnDeathShower(enemy.pos, 0); 
        spawnPickup(enemy.pos);
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else {
                  clearInterval(interval);
                  // Trigger postVictoryTimer logic in update loop
                }
            }, 300);
        }
        return false;
      }
      return true;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY;
      p.pos.x += p.vel.x;
      p.pos.y += p.vel.y;
      p.vel.x *= 0.9;
      p.life--;

      blocks.forEach(block => {
        if (block.type === 'pit') return;
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          p.pos.y = block.y - p.height; p.vel.y = 0;
        }
      });

      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
        const healAmt = p.type === 'large' ? 50 : 20;
        player.health = Math.min(player.maxHealth, player.health + healAmt);
        return false;
      }
      return p.life > 0;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) { state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2); }
    else { state.camera.x = 7200; }
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;

    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
        return;
    }

    const { player, enemies, projectiles, particles, blocks, camera, pickups } = state;
    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };

    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });

    pickups.forEach(p => {
      ctx.fillStyle = 'red';
      const thick = p.type === 'large' ? 10 : 5;
      ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height);
      ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick);
    });

    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });

    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();

    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [status, stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0 };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
        gameStateRef.current.postVictoryTimer = 0;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export const CANVAS_WIDTH = 800;
export const CANVAS_HEIGHT = 600;

export const GRAVITY = 0.5;
export const FRICTION = 0.85;

export const PLAYER_SPEED = 5;
export const PLAYER_JUMP_FORCE = -12;
export const CHARGE_SPEED = 18;
export const UPPERCUT_FORCE = -15;
export const CHARGE_DURATION = 25; 
export const CHARGE_COOLDOWN = 50; 
export const JUMP_PREP_FRAMES = 6;
export const LAND_FRAMES = 8;

export const STAGE_COLORS: Record<string, { ground: string, bg: string, accent: string }> = {
  'Artie Avalanche': { ground: '#AED6F1', bg: '#1B2631', accent: '#D6EAF8' },
  'Victor Volcano': { ground: '#BA4A00', bg: '#1A0602', accent: '#E67E22' },
  'Ernie Earthquake': { ground: '#6E2C00', bg: '#1C1C1C', accent: '#A04000' },
  'Hector Hurricane': { ground: '#16A085', bg: '#0E2F44', accent: '#1ABC9C' }
};

export const COLORS = {
  MEATHEAD_SKIN: '#E67E22',
  MEATHEAD_PANTS: '#273746',
  MEATHEAD_GLOW: '#FFC300',
  GUN: '#5D6D7E',
  GROUND: '#1C2833',
  ENEMY_DRONE: '#8E44AD',
  ENEMY_TANK: '#C0392B',
  ENEMY_FLYER: '#3498DB',
  ENEMY_SHIELD: '#7F8C8D',
  PROJECTILE_PLAYER: '#F1C40F',
  PROJECTILE_ENEMY: '#E74C3C',
  BG_DARK: '#0B0B0B',
  BG_LIGHT: '#1B2631',
};

export const INITIAL_PLAYER_HEALTH = 100;
export const CHARGE_DAMAGE = 75; // 3 shots worth (25 * 3)

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  isUppercutting: boolean;
  isDucking: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
  invincibilityTimer: number;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret' | 'flyer' | 'shield';
  behavior: 'patrol' | 'shoot' | 'hover' | 'fly';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
  isShieldActive?: boolean;
  hitCooldown?: number; // To prevent multiple hits from one charge in one frame
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Pickup {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  type: 'small' | 'large';
  life: number;
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS, UPPERCUT_FORCE, CHARGE_DAMAGE
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: "",
    postVictoryTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => {
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
      const state = gameStateRef.current;
      state.blocks = [];
      state.enemies = [];
      state.projectiles = [];
      state.pickups = [];
      state.particles = [];
      state.frame = 0;
      state.camera = { x: 0, y: 0 };
      state.bossSpawned = false;
      state.arenaLocked = false;
      state.doorState = 'closed';
      state.victoryString = "";
      state.postVictoryTimer = 0;
    }
  }, [status]);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: 20 + Math.random() * 40,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0) => {
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, 15, facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, 20, facing * 22, 30));
    spawnExplosion(pos, '#FF4500', 30, facing * 12, 35);
    spawnExplosion(pos, '#FFFF00', 15, facing * 8, 25);
  };

  const spawnPickup = (pos: Vector2) => {
    const chance = Math.random();
    if (chance > 0.4) return;
    const type = Math.random() > 0.8 ? 'large' : 'small';
    gameStateRef.current.pickups.push({
      id: `pickup-${Date.now()}-${Math.random()}`,
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -5 },
      width: type === 'large' ? 32 : 16,
      height: type === 'large' ? 32 : 16,
      type: type,
      life: 600
    });
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: 40, h: 1400, type: 'wall' } 
    ];
    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }
    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true });
      state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
      state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
    }
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.postVictoryTimer++;
      if (state.postVictoryTimer > 45) { // Reduced from 120 to ~0.75s for "sooner" request
          onBossDefeated(stageId || "");
          state.victoryString = "";
          state.postVictoryTimer = 0;
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const moveUp = keys.current['w'] || keys.current['arrowup'];
    const jumpRequested = keys.current['w'] || keys.current['arrowup'] || keys.current[' '];
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging && !player.isUppercutting) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else if (player.isCharging) {
        player.chargeDuration--; 
        player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      } else if (player.isUppercutting) {
        player.chargeDuration--;
        if (player.chargeDuration <= 0) { player.isUppercutting = false; }
      }

      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isUppercutting && !player.isDucking) {
        player.chargeCooldown = CHARGE_COOLDOWN;
        player.chargeDuration = CHARGE_DURATION;
        if (moveUp) {
            player.isUppercutting = true;
            player.vel.y = UPPERCUT_FORCE;
            player.isGrounded = false;
        } else {
            player.isCharging = true;
            player.vel.x = player.facing * CHARGE_SPEED;
        }
      }

      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { 
            player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; 
            player.vel.x = 0; 
            if (player.isCharging) { player.isCharging = false; }
        }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }
      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      const isHitByCharge = (player.isCharging || player.isUppercutting) &&
                   player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHitByCharge && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
        enemy.health -= CHARGE_DAMAGE;
        enemy.hitCooldown = 15;

        let flySpeed = 0;
        if (enemy.type === 'boss') flySpeed = 10;
        else {
          switch(enemy.enemyType) {
            case 'flyer':
            case 'drone': flySpeed = 48; break; 
            case 'shield': flySpeed = 28; break; 
            case 'tank':   flySpeed = 15; break; 
            default:       flySpeed = 20; break; 
          }
        }

        if (enemy.health > 0) {
            enemy.vel.x = player.facing * flySpeed;
            if (player.isUppercutting) enemy.vel.y = UPPERCUT_FORCE;
            spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12);
            // Player bounce backwards on non-kill
            player.vel.x = -player.facing * 10;
            player.vel.y = -5;
            player.isCharging = false;
            player.isUppercutting = false;
        } else {
            enemy.vel.x = player.facing * flySpeed * 1.5; 
            spawnDeathShower(enemy.pos, player.facing);
            spawnPickup(enemy.pos);
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && 
                 player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                 player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
          player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt');
      }

      if (Math.abs(enemy.vel.x) > 1) enemy.vel.x *= 0.94;
      else if (enemy.enemyType === 'tank' || enemy.type === 'boss') enemy.vel.x = 0;

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        spawnDeathShower(enemy.pos, 0); 
        spawnPickup(enemy.pos);
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 100); // Faster letter reveal
        }
        return false;
      }
      return true;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY;
      p.pos.x += p.vel.x;
      p.pos.y += p.vel.y;
      p.vel.x *= 0.9;
      p.life--;
      blocks.forEach(block => {
        if (block.type === 'pit') return;
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          p.pos.y = block.y - p.height; p.vel.y = 0;
        }
      });
      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
        const healAmt = p.type === 'large' ? 50 : 20;
        player.health = Math.min(player.maxHealth, player.health + healAmt);
        return false;
      }
      return p.life > 0;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);
    else state.camera.x = 7200;
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging || p.isUppercutting) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
        return;
    }
    const { player, enemies, projectiles, particles, blocks, camera, pickups } = state;
    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save();
    ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });
    pickups.forEach(p => {
      ctx.fillStyle = 'red';
      const thick = p.type === 'large' ? 10 : 5;
      ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height);
      ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick);
    });
    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });
    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();
    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [status, stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0, isUppercutting: false, isCharging: false };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
        gameStateRef.current.postVictoryTimer = 0;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS, UPPERCUT_FORCE, CHARGE_DAMAGE
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: "",
    postVictoryTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => {
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
      const state = gameStateRef.current;
      state.blocks = [];
      state.enemies = [];
      state.projectiles = [];
      state.pickups = [];
      state.particles = [];
      state.frame = 0;
      state.camera = { x: 0, y: 0 };
      state.bossSpawned = false;
      state.arenaLocked = false;
      state.doorState = 'closed';
      state.victoryString = "";
      state.postVictoryTimer = 0;
    }
  }, [status]);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: 20 + Math.random() * 40,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0) => {
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, 15, facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, 20, facing * 22, 30));
    spawnExplosion(pos, '#FF4500', 30, facing * 12, 35);
    spawnExplosion(pos, '#FFFF00', 15, facing * 8, 25);
  };

  const spawnPickup = (pos: Vector2) => {
    const chance = Math.random();
    if (chance > 0.4) return;
    const type = Math.random() > 0.8 ? 'large' : 'small';
    gameStateRef.current.pickups.push({
      id: `pickup-${Date.now()}-${Math.random()}`,
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -5 },
      width: type === 'large' ? 32 : 16,
      height: type === 'large' ? 32 : 16,
      type: type,
      life: 600
    });
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: 40, h: 1400, type: 'wall' } 
    ];
    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }
    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true });
      state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
      state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
    }
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.postVictoryTimer++;
      if (state.postVictoryTimer > 30) { // Reduced further to ~0.5s for faster speech box reveal
          onBossDefeated(stageId || "");
          state.victoryString = "";
          state.postVictoryTimer = 0;
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const moveUp = keys.current['w'] || keys.current['arrowup'];
    const jumpRequested = keys.current[' ']; // Now SPACEBAR ONLY
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging && !player.isUppercutting) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else if (player.isCharging) {
        player.chargeDuration--; 
        player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      } else if (player.isUppercutting) {
        player.chargeDuration--;
        if (player.chargeDuration <= 0) { player.isUppercutting = false; }
      }

      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isUppercutting && !player.isDucking) {
        player.chargeCooldown = CHARGE_COOLDOWN;
        player.chargeDuration = CHARGE_DURATION;
        if (moveUp) {
            player.isUppercutting = true;
            player.vel.y = UPPERCUT_FORCE;
            player.isGrounded = false;
        } else {
            player.isCharging = true;
            player.vel.x = player.facing * CHARGE_SPEED;
        }
      }

      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { 
            player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; 
            player.vel.x = 0; 
            if (player.isCharging) { player.isCharging = false; }
        }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }
      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      const isHitByCharge = (player.isCharging || player.isUppercutting) &&
                   player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                   player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y;

      if (isHitByCharge && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
        enemy.health -= CHARGE_DAMAGE;
        enemy.hitCooldown = 15;

        let flySpeed = 0;
        if (enemy.type === 'boss') flySpeed = 10;
        else {
          switch(enemy.enemyType) {
            case 'flyer':
            case 'drone': flySpeed = 48; break; 
            case 'shield': flySpeed = 28; break; 
            case 'tank':   flySpeed = 15; break; 
            default:       flySpeed = 20; break; 
          }
        }

        if (enemy.health > 0) {
            enemy.vel.x = player.facing * flySpeed;
            if (player.isUppercutting) enemy.vel.y = UPPERCUT_FORCE;
            spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12);
            // Player bounce backwards on non-kill
            player.vel.x = -player.facing * 10;
            player.vel.y = -5;
            player.isCharging = false;
            player.isUppercutting = false;
        } else {
            enemy.vel.x = player.facing * flySpeed * 1.5; 
            spawnDeathShower(enemy.pos, player.facing);
            spawnPickup(enemy.pos);
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && 
                 player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                 player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
          player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt');
      }

      if (Math.abs(enemy.vel.x) > 1) enemy.vel.x *= 0.94;
      else if (enemy.enemyType === 'tank' || enemy.type === 'boss') enemy.vel.x = 0;

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        spawnDeathShower(enemy.pos, 0); 
        spawnPickup(enemy.pos);
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 80); // Letter reveal speed
        }
        return false;
      }
      return true;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY;
      p.pos.x += p.vel.x;
      p.pos.y += p.vel.y;
      p.vel.x *= 0.9;
      p.life--;
      blocks.forEach(block => {
        if (block.type === 'pit') return;
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          p.pos.y = block.y - p.height; p.vel.y = 0;
        }
      });
      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
        const healAmt = p.type === 'large' ? 50 : 20;
        player.health = Math.min(player.maxHealth, player.health + healAmt);
        return false;
      }
      return p.life > 0;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);
    else state.camera.x = 7200;
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging || p.isUppercutting) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
        return;
    }
    const { player, enemies, projectiles, particles, blocks, camera, pickups } = state;
    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save();
    ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });
    pickups.forEach(p => {
      ctx.fillStyle = 'red';
      const thick = p.type === 'large' ? 10 : 5;
      ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height);
      ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick);
    });
    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });
    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();
    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [status, stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0, isUppercutting: false, isCharging: false };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
        gameStateRef.current.postVictoryTimer = 0;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export const CANVAS_WIDTH = 800;
export const CANVAS_HEIGHT = 600;

export const GRAVITY = 0.5;
export const FRICTION = 0.85;

export const PLAYER_SPEED = 5;
export const PLAYER_JUMP_FORCE = -12;
export const CHARGE_SPEED = 22; // Increased target speed
export const CHARGE_ACCEL = 2.5; // Acceleration for forward charge
export const UPPERCUT_FORCE = -22; // Significantly higher vertical thrust
export const UPPERCUT_ACCEL = -1.2; // Extra "boost" during the move
export const CHARGE_DURATION = 25; 
export const CHARGE_COOLDOWN = 50; 
export const JUMP_PREP_FRAMES = 6;
export const LAND_FRAMES = 8;

export const STAGE_COLORS: Record<string, { ground: string, bg: string, accent: string }> = {
  'Artie Avalanche': { ground: '#AED6F1', bg: '#1B2631', accent: '#D6EAF8' },
  'Victor Volcano': { ground: '#BA4A00', bg: '#1A0602', accent: '#E67E22' },
  'Ernie Earthquake': { ground: '#6E2C00', bg: '#1C1C1C', accent: '#A04000' },
  'Hector Hurricane': { ground: '#16A085', bg: '#0E2F44', accent: '#1ABC9C' }
};

export const COLORS = {
  MEATHEAD_SKIN: '#E67E22',
  MEATHEAD_PANTS: '#273746',
  MEATHEAD_GLOW: '#FFC300',
  GUN: '#5D6D7E',
  GROUND: '#1C2833',
  ENEMY_DRONE: '#8E44AD',
  ENEMY_TANK: '#C0392B',
  ENEMY_FLYER: '#3498DB',
  ENEMY_SHIELD: '#7F8C8D',
  PROJECTILE_PLAYER: '#F1C40F',
  PROJECTILE_ENEMY: '#E74C3C',
  BG_DARK: '#0B0B0B',
  BG_LIGHT: '#1B2631',
};

export const INITIAL_PLAYER_HEALTH = 100;
export const CHARGE_DAMAGE = 75; // 3 shots worth (25 * 3)

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_ACCEL, UPPERCUT_ACCEL, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS, UPPERCUT_FORCE, CHARGE_DAMAGE
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: "",
    postVictoryTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => {
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
      const state = gameStateRef.current;
      state.blocks = [];
      state.enemies = [];
      state.projectiles = [];
      state.pickups = [];
      state.particles = [];
      state.frame = 0;
      state.camera = { x: 0, y: 0 };
      state.bossSpawned = false;
      state.arenaLocked = false;
      state.doorState = 'closed';
      state.victoryString = "";
      state.postVictoryTimer = 0;
    }
  }, [status]);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: 20 + Math.random() * 40,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0) => {
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, 15, facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, 20, facing * 22, 30));
    spawnExplosion(pos, '#FF4500', 30, facing * 12, 35);
    spawnExplosion(pos, '#FFFF00', 15, facing * 8, 25);
  };

  const spawnPickup = (pos: Vector2) => {
    const chance = Math.random();
    if (chance > 0.4) return;
    const type = Math.random() > 0.8 ? 'large' : 'small';
    gameStateRef.current.pickups.push({
      id: `pickup-${Date.now()}-${Math.random()}`,
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -5 },
      width: type === 'large' ? 32 : 16,
      height: type === 'large' ? 32 : 16,
      type: type,
      life: 600
    });
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: 40, h: 1400, type: 'wall' } 
    ];
    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }
    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true });
      state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
      state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
    }
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.postVictoryTimer++;
      if (state.postVictoryTimer > 30) {
          onBossDefeated(stageId || "");
          state.victoryString = "";
          state.postVictoryTimer = 0;
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const moveUp = keys.current['w'] || keys.current['arrowup'];
    const jumpRequested = keys.current[' ']; 
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging && !player.isUppercutting) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else if (player.isCharging) {
        player.chargeDuration--; 
        // Accelerated Forward Charge
        player.vel.x += player.facing * CHARGE_ACCEL;
        if (Math.abs(player.vel.x) > CHARGE_SPEED) player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      } else if (player.isUppercutting) {
        player.chargeDuration--;
        // Accelerated Uppercut Thrust
        player.vel.y += UPPERCUT_ACCEL;
        if (player.chargeDuration <= 0) { player.isUppercutting = false; }
      }

      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isUppercutting && !player.isDucking) {
        player.chargeCooldown = CHARGE_COOLDOWN;
        player.chargeDuration = CHARGE_DURATION;
        if (moveUp) {
            player.isUppercutting = true;
            player.vel.y = UPPERCUT_FORCE;
            player.isGrounded = false;
        } else {
            player.isCharging = true;
            player.vel.x = player.facing * 5; // Start with some initial boost
        }
      }

      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { 
            player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; 
            player.vel.x = 0; 
            if (player.isCharging) { player.isCharging = false; }
        }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }
      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      // Custom Hurtboxes based on Move
      let hitBoxW = player.width;
      let hitBoxH = player.height;
      let hitBoxX = player.pos.x;
      let hitBoxY = player.pos.y;

      if (player.isCharging) {
          // Horizontal focus
          hitBoxW = player.width + 10;
          hitBoxH = player.height - 10;
      } else if (player.isUppercutting) {
          // Vertical focus
          hitBoxW = player.width - 15; // Thinner
          hitBoxH = player.height + 40; // Taller
          hitBoxY = player.pos.y - 30; // Shift up to hit above
          hitBoxX = player.pos.x + 7.5; // Center thin box
      }

      const isHitByCharge = (player.isCharging || player.isUppercutting) &&
                   hitBoxX < enemy.pos.x + enemy.width && hitBoxX + hitBoxW > enemy.pos.x &&
                   hitBoxY < enemy.pos.y + enemy.height && hitBoxY + hitBoxH > enemy.pos.y;

      if (isHitByCharge && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
        enemy.health -= CHARGE_DAMAGE;
        enemy.hitCooldown = 15;

        let flySpeed = 0;
        if (enemy.type === 'boss') flySpeed = 10;
        else {
          switch(enemy.enemyType) {
            case 'flyer':
            case 'drone': flySpeed = 48; break; 
            case 'shield': flySpeed = 28; break; 
            case 'tank':   flySpeed = 15; break; 
            default:       flySpeed = 20; break; 
          }
        }

        if (enemy.health > 0) {
            enemy.vel.x = player.facing * flySpeed;
            if (player.isUppercutting) enemy.vel.y = UPPERCUT_FORCE;
            spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12);

            // STRONG BOUNCE BACK PHYSICS: Push back several meters (high velocity)
            player.vel.x = -player.facing * 35; // Drastic pushback
            player.vel.y = -12; // High vertical pop
            player.isCharging = false;
            player.isUppercutting = false;
            player.invincibilityTimer = 30; // Brief safety after bounce
        } else {
            enemy.vel.x = player.facing * flySpeed * 1.5; 
            spawnDeathShower(enemy.pos, player.facing);
            spawnPickup(enemy.pos);
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && 
                 player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                 player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
          player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt');
      }

      if (Math.abs(enemy.vel.x) > 1) enemy.vel.x *= 0.94;
      else if (enemy.enemyType === 'tank' || enemy.type === 'boss') enemy.vel.x = 0;

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        spawnDeathShower(enemy.pos, 0); 
        spawnPickup(enemy.pos);
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 80);
        }
        return false;
      }
      return true;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY;
      p.pos.x += p.vel.x;
      p.pos.y += p.vel.y;
      p.vel.x *= 0.9;
      p.life--;
      blocks.forEach(block => {
        if (block.type === 'pit') return;
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          p.pos.y = block.y - p.height; p.vel.y = 0;
        }
      });
      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
        const healAmt = p.type === 'large' ? 50 : 20;
        player.health = Math.min(player.maxHealth, player.health + healAmt);
        return false;
      }
      return p.life > 0;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);
    else state.camera.x = 7200;
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging || p.isUppercutting) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
        return;
    }
    const { player, enemies, projectiles, particles, blocks, camera, pickups } = state;
    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save();
    ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });
    pickups.forEach(p => {
      ctx.fillStyle = 'red';
      const thick = p.type === 'large' ? 10 : 5;
      ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height);
      ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick);
    });
    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });
    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();
    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [status, stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0, isUppercutting: false, isCharging: false };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
        gameStateRef.current.postVictoryTimer = 0;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  isUppercutting: boolean;
  isDucking: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
  invincibilityTimer: number;
  hasUsedAirMove: boolean;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret' | 'flyer' | 'shield';
  behavior: 'patrol' | 'shoot' | 'hover' | 'fly';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
  isShieldActive?: boolean;
  hitCooldown?: number; // To prevent multiple hits from one charge in one frame
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Pickup {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  type: 'small' | 'large';
  life: number;
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_ACCEL, UPPERCUT_ACCEL, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS, UPPERCUT_FORCE, CHARGE_DAMAGE
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0,
      hasUsedAirMove: false
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: "",
    postVictoryTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => {
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
      const state = gameStateRef.current;
      state.blocks = [];
      state.enemies = [];
      state.projectiles = [];
      state.pickups = [];
      state.particles = [];
      state.frame = 0;
      state.camera = { x: 0, y: 0 };
      state.bossSpawned = false;
      state.arenaLocked = false;
      state.doorState = 'closed';
      state.victoryString = "";
      state.postVictoryTimer = 0;
    }
  }, [status]);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: 20 + Math.random() * 40,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0) => {
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, 15, facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, 20, facing * 22, 30));
    spawnExplosion(pos, '#FF4500', 30, facing * 12, 35);
    spawnExplosion(pos, '#FFFF00', 15, facing * 8, 25);
  };

  const spawnPickup = (pos: Vector2) => {
    const chance = Math.random();
    if (chance > 0.4) return;
    const type = Math.random() > 0.8 ? 'large' : 'small';
    gameStateRef.current.pickups.push({
      id: `pickup-${Date.now()}-${Math.random()}`,
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -5 },
      width: type === 'large' ? 32 : 16,
      height: type === 'large' ? 32 : 16,
      type: type,
      life: 600
    });
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: 40, h: 1400, type: 'wall' } 
    ];
    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }
    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true });
      state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
      state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
    }
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.postVictoryTimer++;
      if (state.postVictoryTimer > 30) {
          onBossDefeated(stageId || "");
          state.victoryString = "";
          state.postVictoryTimer = 0;
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const moveUp = keys.current['w'] || keys.current['arrowup'];
    const jumpRequested = keys.current[' ']; 
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging && !player.isUppercutting) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else if (player.isCharging) {
        player.chargeDuration--; 
        player.vel.x += player.facing * CHARGE_ACCEL;
        if (Math.abs(player.vel.x) > CHARGE_SPEED) player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      } else if (player.isUppercutting) {
        player.chargeDuration--;
        player.vel.y += UPPERCUT_ACCEL;
        if (player.chargeDuration <= 0) { player.isUppercutting = false; }
      }

      // Check for Charge/Uppercut availability (Air move logic)
      const canUseSpecialMove = player.isGrounded || !player.hasUsedAirMove;

      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isUppercutting && !player.isDucking && canUseSpecialMove) {
        player.chargeCooldown = CHARGE_COOLDOWN;
        player.chargeDuration = CHARGE_DURATION;
        if (!player.isGrounded) player.hasUsedAirMove = true; // Use air charge token

        if (moveUp) {
            player.isUppercutting = true;
            player.vel.y = UPPERCUT_FORCE;
            player.isGrounded = false;
        } else {
            player.isCharging = true;
            player.vel.x = player.facing * 5; 
        }
      }

      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { 
            player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; 
            player.vel.x = 0; 
            if (player.isCharging) { player.isCharging = false; }
        }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { 
              player.pos.y = block.y - player.height; 
              player.isGrounded = true; 
              player.hasUsedAirMove = false; // Reset air move token on landing
              player.vel.y = 0; 
          }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }
      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      let hitBoxW = player.width;
      let hitBoxH = player.height;
      let hitBoxX = player.pos.x;
      let hitBoxY = player.pos.y;

      if (player.isCharging) {
          hitBoxW = player.width + 10;
          hitBoxH = player.height - 10;
      } else if (player.isUppercutting) {
          hitBoxW = player.width - 15; 
          hitBoxH = player.height + 40; 
          hitBoxY = player.pos.y - 30; 
          hitBoxX = player.pos.x + 7.5; 
      }

      const isHitByCharge = (player.isCharging || player.isUppercutting) &&
                   hitBoxX < enemy.pos.x + enemy.width && hitBoxX + hitBoxW > enemy.pos.x &&
                   hitBoxY < enemy.pos.y + enemy.height && hitBoxY + hitBoxH > enemy.pos.y;

      if (isHitByCharge && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
        enemy.health -= CHARGE_DAMAGE;
        enemy.hitCooldown = 15;

        let flySpeed = 0;
        if (enemy.type === 'boss') flySpeed = 10;
        else {
          switch(enemy.enemyType) {
            case 'flyer':
            case 'drone': flySpeed = 48; break; 
            case 'shield': flySpeed = 28; break; 
            case 'tank':   flySpeed = 15; break; 
            default:       flySpeed = 20; break; 
          }
        }

        if (enemy.health > 0) {
            enemy.vel.x = player.facing * flySpeed;
            if (player.isUppercutting) enemy.vel.y = UPPERCUT_FORCE;
            spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12);

            // BOUNCE BACK PHYSICS: Specifically horizontal as requested
            player.vel.x = -player.facing * 40; // High lateral momentum
            player.vel.y = -3; // Minimal vertical pop for 'horizontal' feel
            player.isCharging = false;
            player.isUppercutting = false;
            player.invincibilityTimer = 30; 
        } else {
            enemy.vel.x = player.facing * flySpeed * 1.5; 
            spawnDeathShower(enemy.pos, player.facing);
            spawnPickup(enemy.pos);
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && 
                 player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                 player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
          player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt');
      }

      if (Math.abs(enemy.vel.x) > 1) enemy.vel.x *= 0.94;
      else if (enemy.enemyType === 'tank' || enemy.type === 'boss') enemy.vel.x = 0;

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        spawnDeathShower(enemy.pos, 0); 
        spawnPickup(enemy.pos);
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 80);
        }
        return false;
      }
      return true;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY;
      p.pos.x += p.vel.x;
      p.pos.y += p.vel.y;
      p.vel.x *= 0.9;
      p.life--;
      blocks.forEach(block => {
        if (block.type === 'pit') return;
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          p.pos.y = block.y - p.height; p.vel.y = 0;
        }
      });
      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
        const healAmt = p.type === 'large' ? 50 : 20;
        player.health = Math.min(player.maxHealth, player.health + healAmt);
        return false;
      }
      return p.life > 0;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);
    else state.camera.x = 7200;
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging || p.isUppercutting) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
        return;
    }
    const { player, enemies, projectiles, particles, blocks, camera, pickups } = state;
    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save();
    ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });
    pickups.forEach(p => {
      ctx.fillStyle = 'red';
      const thick = p.type === 'large' ? 10 : 5;
      ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height);
      ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick);
    });
    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });
    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();
    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [status, stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0, isUppercutting: false, isCharging: false, hasUsedAirMove: false };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
        gameStateRef.current.postVictoryTimer = 0;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export const CANVAS_WIDTH = 800;
export const CANVAS_HEIGHT = 600;

export const GRAVITY = 0.5;
export const FRICTION = 0.85;

export const PLAYER_SPEED = 5;
export const PLAYER_JUMP_FORCE = -12;
export const CHARGE_SPEED = 22; 
export const CHARGE_ACCEL = 2.5; 
export const UPPERCUT_FORCE = -15; // Moderate vertical gain over jump (-12)
export const UPPERCUT_ACCEL = 0; // Removed high acceleration for better balance
export const CHARGE_DURATION = 25; 
export const CHARGE_COOLDOWN = 50; 
export const JUMP_PREP_FRAMES = 6;
export const LAND_FRAMES = 8;

export const STAGE_COLORS: Record<string, { ground: string, bg: string, accent: string }> = {
  'Artie Avalanche': { ground: '#AED6F1', bg: '#1B2631', accent: '#D6EAF8' },
  'Victor Volcano': { ground: '#BA4A00', bg: '#1A0602', accent: '#E67E22' },
  'Ernie Earthquake': { ground: '#6E2C00', bg: '#1C1C1C', accent: '#A04000' },
  'Hector Hurricane': { ground: '#16A085', bg: '#0E2F44', accent: '#1ABC9C' }
};

export const COLORS = {
  MEATHEAD_SKIN: '#E67E22',
  MEATHEAD_PANTS: '#273746',
  MEATHEAD_GLOW: '#FFC300',
  GUN: '#5D6D7E',
  GROUND: '#1C2833',
  ENEMY_DRONE: '#8E44AD',
  ENEMY_TANK: '#C0392B',
  ENEMY_FLYER: '#3498DB',
  ENEMY_SHIELD: '#7F8C8D',
  PROJECTILE_PLAYER: '#F1C40F',
  PROJECTILE_ENEMY: '#E74C3C',
  BG_DARK: '#0B0B0B',
  BG_LIGHT: '#1B2631',
};

export const INITIAL_PLAYER_HEALTH = 100;
export const CHARGE_DAMAGE = 75; // 3 shots worth (25 * 3)

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, FRICTION, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_ACCEL, UPPERCUT_ACCEL, CHARGE_DURATION, 
  CHARGE_COOLDOWN, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES, LAND_FRAMES,
  STAGE_COLORS, UPPERCUT_FORCE, CHARGE_DAMAGE
} from '../constants';

const KILL_VULGARITIES = [
  "FUCK YOU", "EAT SHIT", "DIE PIG", "GET REKT", "WORTHLESS SCRAP", 
  "PISS OFF", "MOTHERFUCKER", "GARBAGE", "WASTE OF MEAT", "SHUT UP", 
  "KNEEL", "WEAKLING", "PATHETIC", "PIECE OF TRASH", "SMASHED"
];

const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, chargeCooldown: number, score: number) => void;
  onBossEncounter: () => void;
  onBossDefeated: (stageId: string) => void;
  onGameOver: (victory: boolean) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      chargeCooldown: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0,
      hasUsedAirMove: false
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    score: 0,
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryAnimFrame: 0,
    victoryString: "",
    postVictoryTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => {
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
      const state = gameStateRef.current;
      state.blocks = [];
      state.enemies = [];
      state.projectiles = [];
      state.pickups = [];
      state.particles = [];
      state.frame = 0;
      state.camera = { x: 0, y: 0 };
      state.bossSpawned = false;
      state.arenaLocked = false;
      state.doorState = 'closed';
      state.victoryString = "";
      state.postVictoryTimer = 0;
    }
  }, [status]);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: 20 + Math.random() * 40,
        color: color,
        size: 2 + Math.random() * 6
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0) => {
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, 15, facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, 20, facing * 22, 30));
    spawnExplosion(pos, '#FF4500', 30, facing * 12, 35);
    spawnExplosion(pos, '#FFFF00', 15, facing * 8, 25);
  };

  const spawnPickup = (pos: Vector2) => {
    const chance = Math.random();
    if (chance > 0.4) return;
    const type = Math.random() > 0.8 ? 'large' : 'small';
    gameStateRef.current.pickups.push({
      id: `pickup-${Date.now()}-${Math.random()}`,
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -5 },
      width: type === 'large' ? 32 : 16,
      height: type === 'large' ? 32 : 16,
      type: type,
      life: 600
    });
  };

  const speakVulgarity = (category: 'kill' | 'hurt' | 'death') => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 120;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) mouse.current.down = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; 
    const doorX = 7200;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: 40, h: 1400, type: 'wall' } 
    ];
    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) {
            state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); 
        }
    } else {
        for (let i = 600; i < doorX; i += 600) {
            state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' });
        }
    }
    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true });
      state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
      state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
    }
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 });
  }, [stageId]);

  const update = useCallback(() => {
    if (status !== GameStatus.PLAYING) return;
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups } = state;

    state.frame++;
    if (state.vulgarityTimer > 0) {
      state.vulgarityTimer--;
      if (state.vulgarityTimer <= 0) state.lastVulgarity = "";
    }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (state.victoryString === "VICTORY") {
      state.postVictoryTimer++;
      if (state.postVictoryTimer > 30) {
          onBossDefeated(stageId || "");
          state.victoryString = "";
          state.postVictoryTimer = 0;
      }
      return; 
    }

    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const moveDown = keys.current['s'] || keys.current['arrowdown'];
    const moveUp = keys.current['w'] || keys.current['arrowup'];
    const jumpRequested = keys.current[' ']; 
    const chargeRequested = keys.current['shift'];
    const shootRequested = mouse.current.down;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging && !player.isUppercutting) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded) player.jumpPrepTimer = JUMP_PREP_FRAMES;
      } else if (player.isCharging) {
        player.chargeDuration--; 
        player.vel.x += player.facing * CHARGE_ACCEL;
        if (Math.abs(player.vel.x) > CHARGE_SPEED) player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      } else if (player.isUppercutting) {
        player.chargeDuration--;
        player.vel.y += UPPERCUT_ACCEL;
        if (player.chargeDuration <= 0) { player.isUppercutting = false; }
      }

      // Air special move limitation: Only one per jump/air-time
      const canUseSpecialMove = player.isGrounded || !player.hasUsedAirMove;

      if (chargeRequested && player.chargeCooldown === 0 && !player.isCharging && !player.isUppercutting && !player.isDucking && canUseSpecialMove) {
        player.chargeCooldown = CHARGE_COOLDOWN;
        player.chargeDuration = CHARGE_DURATION;
        if (!player.isGrounded) player.hasUsedAirMove = true; 

        if (moveUp) {
            player.isUppercutting = true;
            player.vel.y = UPPERCUT_FORCE; // Standard jump gain (-12) vs Uppercut (-15)
            player.isGrounded = false;
        } else {
            player.isCharging = true;
            player.vel.x = player.facing * 5; 
        }
      }

      if (shootRequested && player.shootCooldown <= 0) {
        projectiles.push({
          id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 },
          width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: 25, owner: 'player'
        });
        player.shootCooldown = 12; playGunSound();
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.chargeCooldown > 0) player.chargeCooldown--;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { 
            player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; 
            player.vel.x = 0; 
            if (player.isCharging) { player.isCharging = false; }
        }
        else {
          if (player.pos.y + player.height / 2 < block.y + block.h / 2) { 
              player.pos.y = block.y - player.height; 
              player.isGrounded = true; 
              player.hasUsedAirMove = false; 
              player.vel.y = 0; 
          }
          else { player.pos.y = block.y + block.h; player.vel.y = 0; }
        }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
      if (enemy.behavior === 'patrol') {
        enemy.pos.x += enemy.vel.x;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'fly') {
        enemy.pos.x += enemy.vel.x;
        enemy.pos.y += Math.sin(state.frame / 20) * 2;
        if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1;
      } else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) {
               projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
               enemy.shootTimer = 0;
            }
        } else {
            if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' });
              enemy.shootTimer = 0;
            }
        }
      }
      if (enemy.type === 'boss' && !state.bossSpawned && state.doorState === 'done') { state.bossSpawned = true; onBossEncounter(); }

      let hitBoxW = player.width;
      let hitBoxH = player.height;
      let hitBoxX = player.pos.x;
      let hitBoxY = player.pos.y;

      if (player.isCharging) {
          hitBoxW = player.width + 10;
          hitBoxH = player.height - 10;
      } else if (player.isUppercutting) {
          hitBoxW = player.width - 15; 
          hitBoxH = player.height + 40; 
          hitBoxY = player.pos.y - 30; 
          hitBoxX = player.pos.x + 7.5; 
      }

      const isHitByCharge = (player.isCharging || player.isUppercutting) &&
                   hitBoxX < enemy.pos.x + enemy.width && hitBoxX + hitBoxW > enemy.pos.x &&
                   hitBoxY < enemy.pos.y + enemy.height && hitBoxY + hitBoxH > enemy.pos.y;

      if (isHitByCharge && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
        enemy.health -= CHARGE_DAMAGE;
        enemy.hitCooldown = 15;

        let flySpeed = 0;
        if (enemy.type === 'boss') flySpeed = 10;
        else {
          switch(enemy.enemyType) {
            case 'flyer':
            case 'drone': flySpeed = 48; break; 
            case 'shield': flySpeed = 28; break; 
            case 'tank':   flySpeed = 15; break; 
            default:       flySpeed = 20; break; 
          }
        }

        if (enemy.health > 0) {
            enemy.vel.x = player.facing * flySpeed;
            if (player.isUppercutting) enemy.vel.y = UPPERCUT_FORCE;
            spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12);

            // BOUNCE BACK PHYSICS: Horizontal backwards push
            player.vel.x = -player.facing * 30; // Strong lateral push (~1.5 meters per frame initially)
            player.vel.y = -2; // Minimal vertical pop
            player.isCharging = false;
            player.isUppercutting = false;
            player.invincibilityTimer = 30; 
        } else {
            enemy.vel.x = player.facing * flySpeed * 1.5; 
            spawnDeathShower(enemy.pos, player.facing);
            spawnPickup(enemy.pos);
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && 
                 player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x &&
                 player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
          player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt');
      }

      if (Math.abs(enemy.vel.x) > 1) enemy.vel.x *= 0.94;
      else if (enemy.enemyType === 'tank' || enemy.type === 'boss') enemy.vel.x = 0;

      if (enemy.health <= 0) {
        state.score += enemy.type === 'boss' ? 20000 : 300;
        spawnDeathShower(enemy.pos, 0); 
        spawnPickup(enemy.pos);
        speakVulgarity('kill');
        if (enemy.type === 'boss') {
            state.victoryString = "";
            state.victoryAnimFrame = 0;
            const fullStr = "VICTORY";
            let idx = 0;
            const interval = setInterval(() => {
                if (idx < fullStr.length) state.victoryString += fullStr[idx++];
                else clearInterval(interval);
            }, 80);
        }
        return false;
      }
      return true;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY;
      p.pos.x += p.vel.x;
      p.pos.y += p.vel.y;
      p.vel.x *= 0.9;
      p.life--;
      blocks.forEach(block => {
        if (block.type === 'pit') return;
        if (p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) {
          p.pos.y = block.y - p.height; p.vel.y = 0;
        }
      });
      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
        const healAmt = p.type === 'large' ? 50 : 20;
        player.health = Math.min(player.maxHealth, player.health + healAmt);
        return false;
      }
      return p.life > 0;
    });

    state.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x;
      if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; return false;
          }
        }
      } else {
        if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
        }
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    if (!state.arenaLocked) state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2);
    else state.camera.x = 7200;
    if (player.health <= 0 || player.pos.y > 1000) { if (player.health > 0) player.health = 0; speakVulgarity('death'); setTimeout(() => onGameOver(false), 2000); }
    onPlayerUpdate(player.health, player.chargeCooldown, state.score);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onGameOver]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save();
    let drawX = p.pos.x; let drawY = p.pos.y; let drawW = p.width; let drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isCharging || p.isUppercutting) {
      drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0;
    }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    ctx.fillStyle = '#333';
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14;
    const gunY = p.isDucking ? drawY + 10 : drawY + 25;
    ctx.fillRect(gunX, gunY, 24, 10);
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) {
      const txt = gameStateRef.current.lastVulgarity;
      ctx.font = 'bold 10px "Press Start 2P"'; 
      ctx.fillStyle = 'white'; 
      ctx.shadowColor = 'black'; 
      ctx.shadowBlur = 4;
      ctx.textAlign = 'center';
      ctx.fillText(txt, drawX + drawW/2, drawY - 20); 
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
        return;
    }
    const { player, enemies, projectiles, particles, blocks, camera, pickups } = state;
    const currentColors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = currentColors.bg;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save();
    ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => {
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); }
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; }
      else { ctx.fillStyle = currentColors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = currentColors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    });
    pickups.forEach(p => {
      ctx.fillStyle = 'red';
      const thick = p.type === 'large' ? 10 : 5;
      ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height);
      ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick);
    });
    enemies.forEach(e => {
      if (e.enemyType === 'shield') {
          ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); }
      } else if (e.enemyType === 'flyer') {
          ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8);
      } else {
          ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK);
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });
    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.globalAlpha = p.life / 20; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();
    if (state.victoryString) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P"';
        ctx.fillStyle = 'yellow';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 6;
        ctx.textAlign = 'center';
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }
  }, [status, stageId]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => { update(); draw(); animationFrameId = window.requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) {
      if (gameStateRef.current.frame === 0) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, invincibilityTimer: 0, isUppercutting: false, isCharging: false, hasUsedAirMove: false };
        gameStateRef.current.score = 0; gameStateRef.current.bossSpawned = false; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.voiceLineCooldown = 0;
        gameStateRef.current.victoryString = "";
        gameStateRef.current.postVictoryTimer = 0;
      }
      animationFrameId = window.requestAnimationFrame(loop);
    } else {
      draw();
      if (status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_VICTORY_SPEECH) { gameStateRef.current.frame = 0; }
    }
    return () => window.cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  PLAYING = 'PLAYING',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY',
  PAUSED = 'PAUSED'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export interface Player extends Entity {
  isCharging: boolean;
  isUppercutting: boolean;
  isDucking: boolean;
  chargeCooldown: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
  invincibilityTimer: number;
  hasUsedAirMove: boolean;
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret' | 'flyer' | 'shield';
  behavior: 'patrol' | 'shoot' | 'hover' | 'fly';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
  isShieldActive?: boolean;
  hitCooldown?: number; // To prevent multiple hits from one charge in one frame
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
}

export interface Pickup {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  type: 'small' | 'large';
  life: number;
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
}

import React, { useState, useEffect, useCallback } from 'react';
import HUD from './components/HUD';
import Overlay from './components/Overlay';
import GameCanvas from './components/GameCanvas';
import { GameStatus } from './types';
import { INITIAL_PLAYER_HEALTH, CHARGE_COOLDOWN } from './constants';
import { getBossTaunt, getMissionBriefing, getMeatheadVictorySpeech } from './services/geminiService';

const App: React.FC = () => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.START);
  const [health, setHealth] = useState(INITIAL_PLAYER_HEALTH);
  const [chargeCooldown, setChargeCooldown] = useState(0);
  const [score, setScore] = useState(0);
  const [bossTaunt, setBossTaunt] = useState("YOU'RE TOAST.");
  const [victorySpeech, setVictorySpeech] = useState("");
  const [briefing, setBriefing] = useState("");
  const [selectedStage, setSelectedStage] = useState<string | null>(null);
  const [defeatedStages, setDefeatedStages] = useState<string[]>([]);

  useEffect(() => {
    const fetchBriefing = async () => {
      const b = await getMissionBriefing();
      setBriefing(b);
    };
    fetchBriefing();
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (status === GameStatus.PLAYING) {
          setStatus(GameStatus.PAUSED);
        } else if (status === GameStatus.PAUSED) {
          setStatus(GameStatus.PLAYING);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [status]);

  const handleStart = useCallback(() => {
    if (status === GameStatus.START || status === GameStatus.VICTORY) {
      setDefeatedStages([]);
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.GAME_OVER) {
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.BOSS_INTRO) {
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_VICTORY_SPEECH) {
      if (defeatedStages.length >= 4) {
        setStatus(GameStatus.VICTORY);
      } else {
        setStatus(GameStatus.STAGE_SELECT);
        setSelectedStage(null);
      }
    }
  }, [status, defeatedStages]);

  const handleResume = useCallback(() => {
    setStatus(GameStatus.PLAYING);
  }, []);

  const handleBossSelect = useCallback(() => {
    setSelectedStage(null);
    setStatus(GameStatus.STAGE_SELECT);
  }, []);

  const handleSelectStage = useCallback((stage: string) => {
    if (defeatedStages.includes(stage)) return;
    setSelectedStage(stage);
    setHealth(INITIAL_PLAYER_HEALTH);
    setScore(0);
    setChargeCooldown(0);
    setStatus(GameStatus.PLAYING);
  }, [defeatedStages]);

  const handleBossEncounter = useCallback(async () => {
    setStatus(GameStatus.BOSS_INTRO);
    const taunt = await getBossTaunt(selectedStage || "The Boss");
    setBossTaunt(taunt);
  }, [selectedStage]);

  const handleBossDefeated = useCallback(async (stageId: string) => {
    setDefeatedStages(prev => [...prev, stageId]);
    const speech = await getMeatheadVictorySpeech(stageId);
    setVictorySpeech(speech);
    setStatus(GameStatus.BOSS_VICTORY_SPEECH);
  }, []);

  const handleGameOver = useCallback((victory: boolean) => {
    // Redundant now since GameCanvas handles internal reset, 
    // but kept for compatibility.
    if (!victory) setStatus(GameStatus.GAME_OVER);
  }, []);

  const handlePlayerUpdate = useCallback((h: number, cc: number, s: number) => {
    setHealth(h);
    setChargeCooldown(cc);
    setScore(s);
  }, []);

  return (
    <div className="relative w-screen h-screen flex items-center justify-center bg-black overflow-hidden">
      <div className="relative shadow-2xl border-4 border-gray-800 bg-[#121212]" style={{ width: 800, height: 600 }}>
        {(status === GameStatus.PLAYING || status === GameStatus.PAUSED || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) && (
          <HUD 
            health={health} 
            maxHealth={INITIAL_PLAYER_HEALTH} 
            chargeCooldown={chargeCooldown} 
            maxChargeCooldown={CHARGE_COOLDOWN}
            score={score}
          />
        )}

        <Overlay 
          status={status} 
          onStart={handleStart} 
          onResume={handleResume}
          onBossSelect={handleBossSelect}
          onSelectStage={handleSelectStage}
          bossTaunt={bossTaunt}
          victorySpeech={victorySpeech}
          briefing={briefing}
          score={score}
          defeatedStages={defeatedStages}
        />

        <GameCanvas 
          status={status}
          stageId={selectedStage}
          onPlayerUpdate={handlePlayerUpdate}
          onBossEncounter={handleBossEncounter}
          onBossDefeated={handleBossDefeated}
          onGameOver={handleGameOver}
        />
      </div>
    </div>
  );
};

export default App;

import React, { useCallback } from 'react';
import { GameStatus } from '../types';

interface OverlayProps {
  status: GameStatus;
  onStart: () => void;
  onResume?: () => void;
  onBossSelect?: () => void;
  onSelectStage?: (stage: string) => void;
  bossTaunt?: string;
  victorySpeech?: string;
  briefing?: string;
  score?: number;
  defeatedStages?: string[];
}

const STAGES = [
  { id: 'Artie Avalanche', color: 'bg-blue-600' },
  { id: 'Victor Volcano', color: 'bg-orange-600' },
  { id: 'Ernie Earthquake', color: 'bg-amber-800' },
  { id: 'Hector Hurricane', color: 'bg-cyan-600' }
];

