      <div className="absolute -left-12 top-4 w-24 h-20 bg-[#f1c27d] border-[6px] border-black rounded-full rotate-45">
        <div className="absolute top-6 left-4 w-12 h-1.5 bg-red-900/30 rounded-full" />
      </div>
      <div className="absolute -right-12 top-4 w-24 h-20 bg-[#f1c27d] border-[6px] border-black rounded-full -rotate-45">
        <div className="absolute top-6 right-4 w-12 h-1.5 bg-red-900/30 rounded-full" />
      </div>
