const HURT_VULGARITIES = [
  "OW FUCK", "GOD DAMNIT", "SON OF A BITCH", "YOU PIECE OF SHIT", "THAT HURTS MOTHERFUCKER",
  "YOU TRYING TO RUIN MY PUMP?", "I'LL WEAVE YOUR SPINE INTO A ROPE"
];

const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL"
];

const INTRO_QUOTES: Record<string, string> = {
  'Victor Volcano': "HELL HATH NO FURY LIKE A BUFF DUDE SCORNED.",
  'Artie Avalanche': "WHAT KILLED THE DINOSAURS? THE ICE AGE!",
  'Hector Hurricane': "KATRINA'S GOT NOTHING ON MY WRATH.",
  'Ernie Earthquake': "I'D BE QUAKING IN MY BOOTS IF I WERE YOU."
};

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const SCRAP_COLORS = ['#808080', '#C0C0C0', '#2F4F4F', '#464646'];
const GLASS_COLORS = ['#ADD8E6', '#F0F8FF', '#FFFFFF', '#B0C4DE'];
const FIRE_COLORS = ['#FF4500', '#FF8C00', '#FFA500', '#FFD700', '#FF0000'];

type VulgarityType = 'kill' | 'hurt' | 'death' | 'charge_kill' | 'uppercut_kill';

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, specialCharges: number, specialChargeTimer: number) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onTogglePause, currentWeapon }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      specialCharges: MAX_SPECIAL_CHARGES,
      specialChargeTimer: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0,
      hasUsedAirMove: false,
      jumpInputReleased: true,
      chargeInputReleased: true,
      currentWeapon: 'GUN',
      availableWeapons: ['GUN', 'BOULDER']
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryString: "",
    postVictoryTimer: 0,
    introTimer: 0,
    bossExplosionTimer: 0,
    bossExplosionPos: { x: 0, y: 0 }
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => {
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) {
      const state = gameStateRef.current;
      state.blocks = [];
      state.enemies = [];
      state.projectiles = [];
      state.pickups = [];
      state.particles = []; 
      state.frame = 0;
      state.camera = { x: 0, y: 0 };
      state.bossSpawned = false;
      state.arenaLocked = false;
      state.doorState = 'closed';
      state.victoryString = "";
      state.postVictoryTimer = 0;
      state.introTimer = 0;
      state.bossExplosionTimer = 0;
    }
  }, [status]);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15, isGlass: boolean = false) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: isGlass ? 150 + Math.random() * 200 : 20 + Math.random() * 80,
        color: color,
        size: isGlass ? 1 + Math.random() * 4 : 2 + Math.random() * 12,
        isGlass
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0, multiplier: number = 1) => {
    // Toned down base counts for regular enemies. Bosses use high multipliers to stay "ridiculous".
    SCRAP_COLORS.forEach(c => spawnExplosion(pos, c, Math.ceil(8 * multiplier), facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, Math.ceil(12 * multiplier), facing * 22, 35));
    spawnExplosion(pos, '#FF4500', Math.ceil(10 * multiplier), facing * 12, 40);
    spawnExplosion(pos, '#FFFF00', Math.ceil(5 * multiplier), facing * 8, 30);
  };

  const triggerBossDeath = (boss: Enemy, playerFacing: number) => {
    const state = gameStateRef.current;
    if (state.bossExplosionTimer > 0) return;
    state.bossExplosionTimer = 220; 
    state.bossExplosionPos = { x: boss.pos.x + boss.width / 2, y: boss.pos.y + boss.height / 2 };
    // RIDICULOUS amount for bosses
    spawnDeathShower(state.bossExplosionPos, playerFacing, 150); 
    speakVulgarity('kill');
  };

  const speakVulgarity = (category: VulgarityType) => {
    if (gameStateRef.current.voiceLineCooldown > 0) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      if (category === 'charge_kill') pool = CHARGE_KILL_VULGARITIES;
      if (category === 'uppercut_kill') pool = UPPERCUT_KILL_VULGARITIES;

      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 60;
      gameStateRef.current.voiceLineCooldown = 90;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGlassShatterSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      for(let i=0; i<12; i++) {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.type = i % 2 === 0 ? 'sine' : 'sawtooth';
        osc.frequency.setValueAtTime(1200 + Math.random() * 5000, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
        gain.gain.setValueAtTime(0.1, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
        osc.connect(gain); gain.connect(ctx.destination);
        osc.start(); osc.stop(ctx.currentTime + 0.3);
      }
    } catch (e) {}
  };

  const playGunSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator(); const gain = ctx.createGain();
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  const speakIntroLine = (id: string | null) => {
    if (!id || !INTRO_QUOTES[id]) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(INTRO_QUOTES[id]);
      utterance.pitch = 0.1; utterance.rate = 1.1; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
      gameStateRef.current.lastVulgarity = INTRO_QUOTES[id];
      gameStateRef.current.vulgarityTimer = 120;
    }
  };

  const spawnGlassShatter = (pos: Vector2) => {
    GLASS_COLORS.forEach(c => spawnExplosion(pos, c, 50, 15, 25, true));
  };

  const spawnPickup = (pos: Vector2) => {
    if (Math.random() < 0.4) {
      const type = Math.random() > 0.8 ? 'large' : 'small';
      gameStateRef.current.pickups.push({
        id: `pickup-${Date.now()}-${Math.random()}`,
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * 4, y: -5 },
        width: 20,
        height: 20,
        type,
        life: 600
      });
    }
  };

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; const doorX = 7200;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: 40, h: 1400, type: 'wall' } 
    ];
    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) { state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); }
    } else {
        for (let i = 600; i < doorX; i += 600) { state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' }); }
    }
    state.enemies = [];
    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true });
      state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
      state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
    }
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 1500, maxHealth: 1500, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 });
  }, [stageId]);

  const update = useCallback(() => {
    const state = gameStateRef.current;

    if (state.bossExplosionTimer > 0) {
      state.bossExplosionTimer--;
      if (state.frame % 3 === 0) {
        const offset = { x: (Math.random() - 0.5) * 200, y: (Math.random() - 0.5) * 200 };
        const pos = { x: state.bossExplosionPos.x + offset.x, y: state.bossExplosionPos.y + offset.y };
        // More explosion particles for boss sequence
        spawnDeathShower(pos, (Math.random() - 0.5) * 6, 15);
        spawnExplosion(pos, '#FFD700', 15, (Math.random() - 0.5) * 25, 30);
      }
      state.particles = state.particles.filter(p => { 
          p.pos.x += p.vel.x; p.pos.y += p.vel.y; 
          if (p.isGlass || (p.color && FIRE_COLORS.includes(p.color))) p.vel.y += 0.25;
          p.life--; return p.life > 0; 
      });
      if (state.bossExplosionTimer === 0) {
        onBossDeath(); state.victoryString = "V"; state.postVictoryTimer = 0;
      }
      return;
    }

    if (status === GameStatus.PAUSED) return;

    if (status === GameStatus.LEVEL_INTRO) {
        state.introTimer++; state.camera.x = 0; state.player.facing = 1; 
        if (state.introTimer === 30) speakIntroLine(stageId); 

        if (state.introTimer < 80) {
            state.player.pos.x = -150; 
        } else {
            if (state.introTimer === 80) { 
                playGlassShatterSound(); 
                spawnGlassShatter({ x: 0, y: 450 }); 
            }

            const jumpDuration = 60;
            const t = Math.min(1.0, (state.introTimer - 80) / jumpDuration);
            state.player.pos.x = -100 + (t * 250);
            const peakHeight = 250;
            const groundY = 486;
            const startY = 400;
            state.player.pos.y = startY + (groundY - startY) * t - Math.sin(t * Math.PI) * peakHeight;

            if (state.introTimer >= 80 + jumpDuration) { 
              state.player.pos.y = groundY; 
              state.player.pos.x = 150;
              state.player.vel = { x: 0, y: 0 }; 
              state.player.isCharging = false;
              state.player.isUppercutting = false;
              state.player.jumpPrepTimer = 0;
              onIntroComplete(); 
            }
        }

        state.particles = state.particles.filter(p => { 
            p.pos.x += p.vel.x; p.pos.y += p.vel.y; 
            if (p.isGlass) { 
                p.vel.y += 0.25; 
                if (p.pos.y > 548) { p.pos.y = 548; p.vel.y = -p.vel.y * 0.2; p.vel.x *= 0.7; } 
            }
            p.life--; return p.life > 0; 
        });
        return;
    }

    if (status === GameStatus.BOSS_TRANSITION) {
        state.projectiles = []; 
        const targetCameraX = 7200; const targetPlayerX = 7300;
        state.camera.x += (targetCameraX - state.camera.x) * 0.05;
        state.player.pos.x += (targetPlayerX - state.player.pos.x) * 0.05;
        state.player.pos.y += (486 - state.player.pos.y) * 0.05; state.player.vel = { x: 0, y: 0 };
        if (Math.abs(state.camera.x - targetCameraX) < 1) { state.camera.x = targetCameraX; onBossEncounter(); }
        return;
    }

    if (status !== GameStatus.PLAYING) return;

    if (state.victoryString) {
      state.frame++;
      state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
      if (state.victoryString.length < 7) {
        state.postVictoryTimer++;
        if (state.postVictoryTimer >= 30) {
            const fullStr = "VICTORY"; state.victoryString += fullStr[state.victoryString.length]; state.postVictoryTimer = 0;
            if (state.victoryString.length === 7) { setTimeout(() => { onBossDefeated(stageId || ""); }, 2000); }
        }
      }
      return; 
    }

    // INPUT POLLING
    const gamepads = navigator.getGamepads();
    let padMoveX = 0, padMoveY = 0, padJump = false, padSpecial = false, padShoot = false;
    if (gamepads[0]) {
      const gp = gamepads[0];
      const DEADZONE = 0.2;
      if (Math.abs(gp.axes[0]) > DEADZONE) padMoveX = gp.axes[0];
      if (Math.abs(gp.axes[1]) > DEADZONE) padMoveY = gp.axes[1];
      if (gp.buttons[14]?.pressed) padMoveX = -1;
      if (gp.buttons[15]?.pressed) padMoveX = 1;
      if (gp.buttons[12]?.pressed) padMoveY = -1;
      if (gp.buttons[13]?.pressed) padMoveY = 1;
      padJump = gp.buttons[0]?.pressed; 
      padShoot = gp.buttons[2]?.pressed || gp.buttons[3]?.pressed; 
      padSpecial = gp.buttons[7]?.pressed; 
    }

    const km = keys.current;
    const moveLeft = km['a'] || km['arrowleft'] || km['keya'] || padMoveX < -0.3;
    const moveRight = km['d'] || km['arrowright'] || km['keyd'] || padMoveX > 0.3;
    const moveDown = km['s'] || km['arrowdown'] || km['keys'] || padMoveY > 0.3;
    const moveUp = km['w'] || km['arrowup'] || km['keyw'] || padMoveY < -0.3;
    const jumpRequested = km[' '] || km['space'] || km['z'] || km['keyz'] || km['j'] || km['keyj'] || padJump;
    const chargeRequested = km['shift'] || km['shiftleft'] || km['shiftright'] || km['c'] || km['keyc'] || padSpecial;
    const shootRequested = km['x'] || km['keyx'] || km['k'] || km['keyk'] || mouse.current.down || padShoot;

    const { player, enemies, projectiles, particles, blocks, pickups } = state;
    state.frame++;
    if (state.vulgarityTimer > 0) { state.vulgarityTimer--; if (state.vulgarityTimer <= 0) state.lastVulgarity = ""; }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;

    if (player.specialCharges < MAX_SPECIAL_CHARGES) {
      player.specialChargeTimer++;
      if (player.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) { player.specialCharges++; player.specialChargeTimer = 0; }
    } else { player.specialChargeTimer = 0; }

    if (!jumpRequested) player.jumpInputReleased = true;
    if (!chargeRequested) player.chargeInputReleased = true;

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5;
      if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; onBossTransition(); }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging && !player.isUppercutting) {
        if (!player.isDucking) {
          if (moveLeft) { player.vel.x = -PLAYER_SPEED; player.facing = -1; }
          else if (moveRight) { player.vel.x = PLAYER_SPEED; player.facing = 1; }
          else { player.vel.x *= FRICTION; }
        } else { player.vel.x *= FRICTION; }
        if (jumpRequested && player.isGrounded && player.jumpInputReleased) { player.jumpPrepTimer = JUMP_PREP_FRAMES; player.jumpInputReleased = false; }
      } else if (player.isCharging) {
        player.chargeDuration--; player.vel.x += player.facing * CHARGE_ACCEL;
        if (Math.abs(player.vel.x) > CHARGE_SPEED) player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      } else if (player.isUppercutting) {
        player.chargeDuration--; player.vel.y += UPPERCUT_ACCEL;
        if (player.chargeDuration <= 0) { player.isUppercutting = false; }
      }

      // Charge Logic simplified: as long as charges exist, button press activates special move.
      if (chargeRequested && player.chargeInputReleased && !player.isCharging && !player.isUppercutting && !player.isDucking && player.specialCharges > 0) {
        player.chargeInputReleased = false; 
        if (moveUp) { 
          player.specialCharges--; 
          player.chargeDuration = CHARGE_DURATION; 
          player.isUppercutting = true; 
          player.vel.y = UPPERCUT_FORCE; 
          player.isGrounded = false; 
        } else { 
          player.specialCharges--; 
          player.chargeDuration = CHARGE_DURATION; 
          player.isCharging = true; 
          player.vel.x = player.facing * 5; 
        }
      }

      if (shootRequested && player.shootCooldown <= 0) {
        if (currentWeapon === 'GUN') {
          projectiles.push({ id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 }, width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' });
          player.shootCooldown = 12; playGunSound();
        } else if (currentWeapon === 'BOULDER') {
          if (!projectiles.some(p => p.owner === 'player' && p.isBoulder)) {
            projectiles.push({ id: `b-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -40), y: player.pos.y + 20 }, vel: { x: player.facing * BOULDER_SPEED, y: 0 }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true });
            player.shootCooldown = 40;
          }
        }
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    player.vel.y += GRAVITY;
    if (!jumpRequested && player.vel.y < 0 && !player.isGrounded && !player.isCharging && !player.isUppercutting) player.vel.y *= 0.5;
    player.pos.x += player.vel.x; player.pos.y += player.vel.y;
    if (player.pos.x < 50) player.pos.x = 50;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorState !== 'closed' && state.doorState !== 'done') return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; if (player.isCharging) player.isCharging = false; }
        else { if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.hasUsedAirMove = false; player.vel.y = 0; } else { player.pos.y = block.y + block.h; player.vel.y = 0; } }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.health <= 0) return false; 
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
      const onScreen = enemy.pos.x + enemy.width > state.camera.x && enemy.pos.x < state.camera.x + CANVAS_WIDTH;
      if (enemy.behavior === 'patrol') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; }
      else if (enemy.behavior === 'fly') { enemy.pos.x += enemy.vel.x; enemy.pos.y += Math.sin(state.frame / 20) * 2; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; }
      else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        if (onScreen) {
          enemy.shootTimer++;
          if (enemy.enemyType === 'shield') {
              enemy.isShieldActive = enemy.shootTimer < 80;
              if (enemy.shootTimer > 120) { projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' }); enemy.shootTimer = 0; }
          } else if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 20, owner: 'enemy' }); enemy.shootTimer = 0;
          }
        }
      }

      let hbW = player.width, hbH = player.height, hbX = player.pos.x, hbY = player.pos.y;
      if (player.isCharging) { hbW = player.width + 10; hbH = player.height - 10; }
      else if (player.isUppercutting) { hbW = player.width - 15; hbH = player.height + 40; hbY = player.pos.y - 30; hbX = player.pos.x + 7.5; }
      const chargeHit = (player.isCharging || player.isUppercutting) && hbX < enemy.pos.x + enemy.width && hbX + hbW > enemy.pos.x && hbY < enemy.pos.y + enemy.height && hbY + hbH > enemy.pos.y;

      if (chargeHit && onScreen && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
        enemy.health -= CHARGE_DAMAGE; enemy.hitCooldown = 15;
        if (enemy.health > 0) { enemy.vel.x = player.facing * 20; if (player.isUppercutting) enemy.vel.y = UPPERCUT_FORCE; spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12); player.vel.x = -player.facing * 30; player.vel.y = -2; player.isCharging = false; player.isUppercutting = false; player.invincibilityTimer = 30; }
        else {
            if (enemy.type === 'boss') triggerBossDeath(enemy, player.facing);
            else { 
              // Toned down death effect for regular enemies
              spawnDeathShower(enemy.pos, player.facing); 
              spawnPickup(enemy.pos); 
              speakVulgarity(player.isUppercutting ? 'uppercut_kill' : 'charge_kill'); 
            }
            return false;
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x && player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
          player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt');
      }
      if (Math.abs(enemy.vel.x) > 1) enemy.vel.x *= 0.94; else if (enemy.enemyType === 'tank' || enemy.type === 'boss') enemy.vel.x = 0;
      return true;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY; p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.vel.x *= 0.9; p.life--;
      blocks.forEach(block => { if (block.type !== 'pit' && p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) { p.pos.y = block.y - p.height; p.vel.y = 0; } });
      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) { player.health = Math.min(player.maxHealth, player.health + (p.type === 'large' ? 50 : 20)); return false; }
      return p.life > 0;
    });

    state.projectiles = projectiles.filter(p => {
      if (p.isBoulder) {
        p.vel.y += GRAVITY; p.pos.y += p.vel.y;
        blocks.forEach(b => { if (b.type !== 'pit' && p.pos.x < b.x + b.w && p.pos.x + p.width > b.x && p.pos.y < b.y + b.h && p.pos.y + p.height > b.y) { if (p.vel.y > 1.5) { p.vel.y = -p.vel.y * BOULDER_BOUNCE_DAMPING; spawnExplosion({x: p.pos.x + p.width/2, y: b.y}, '#8B4513', 5, 0, 10); } else { p.vel.y = 0; } p.pos.y = b.y - p.height; } });
        p.pos.x += p.vel.x;
        if (state.frame % 1 === 0) state.particles.push({ pos: { x: p.pos.x + (Math.random() * p.width), y: p.pos.y + p.height - 10 }, vel: { x: (Math.random() - 0.5) * 1.5 - p.vel.x * 0.2, y: -Math.random() * 4 }, life: 25 + Math.random() * 30, color: FIRE_COLORS[Math.floor(Math.random() * FIRE_COLORS.length)], size: 6 + Math.random() * 8 });
      } else { p.pos.x += p.vel.x; }
      if (p.pos.x < state.camera.x - 400 || p.pos.x > state.camera.x + CANVAS_WIDTH + 400) return false;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (enemy.health > 0 && p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
            if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
            enemy.health -= p.damage; 
            if (enemy.health <= 0) {
              if (enemy.type === 'boss') triggerBossDeath(enemy, p.vel.x > 0 ? 1 : -1);
              else { spawnDeathShower(enemy.pos, 0, 1.2); spawnPickup(enemy.pos); speakVulgarity('kill'); }
            }
            if (p.isBoulder) { spawnExplosion(p.pos, '#FF4500', 60, 0, 40); FIRE_COLORS.forEach(c => spawnExplosion(p.pos, c, 10, 0, 50)); return false; }
            return false;
          }
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          player.health -= p.damage; player.invincibilityTimer = 60; speakVulgarity('hurt'); return false;
      }
      return true;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; if (p.isGlass || FIRE_COLORS.includes(p.color)) { p.vel.y += 0.25; if (p.pos.y > 548) { p.pos.y = 548; p.vel.y = -p.vel.y * 0.3; p.vel.x *= 0.8; } } p.life--; return p.life > 0; });
    if (!state.arenaLocked) state.camera.x = Math.max(0, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2); else state.camera.x = 7200;
    if (player.health <= 0 || player.pos.y > 1000) { speakVulgarity('death'); state.player.health = INITIAL_PLAYER_HEALTH; state.player.pos = { x: 150, y: 100 }; state.player.vel = { x: 0, y: 0 }; state.player.invincibilityTimer = 60; state.player.facing = 1; state.frame = 0; createLevel(); }
    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer);
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onBossDeath, onGameOver, createLevel, onIntroComplete, onBossTransition, onTogglePause, currentWeapon]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0) return;
    ctx.save(); let drawX = p.pos.x, drawY = p.pos.y, drawW = p.width, drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; } else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }
    if (p.isUppercutting) { drawH += 30; drawW -= 10; drawY -= 30; drawX += 5; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 5, drawY - 5, drawW + 10, drawH + 10); ctx.globalAlpha = 1.0; }
    else if (p.isCharging) { drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0; }
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14, gunY = p.isDucking ? drawY + 10 : drawY + 25;
    if (currentWeapon === 'GUN') { ctx.fillStyle = '#333'; ctx.fillRect(gunX, gunY, 24, 10); } 
    else if (currentWeapon === 'BOULDER') { ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(gunX + 12, gunY + 5, 12, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); }
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) { ctx.font = 'bold 10px "Press Start 2P"'; ctx.fillStyle = 'white'; ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.textAlign = 'center'; ctx.fillText(gameStateRef.current.lastVulgarity, drawX + drawW/2, drawY - 20); ctx.shadowBlur = 0; }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return; const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) { ctx.fillStyle = 'black'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); return; }
    const { player, enemies, projectiles, particles, blocks, camera, pickups } = state;
    const colors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = colors.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); ctx.translate(-camera.x, -camera.y);

    if (status === GameStatus.LEVEL_INTRO) {
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 4;
        if (state.introTimer < 80) {
            ctx.strokeRect(-5, 300, 10, 250);
            ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
            ctx.fillRect(-5, 300, 10, 250);
        } else {
            ctx.beginPath();
            ctx.moveTo(-5, 300); ctx.lineTo(5, 330); ctx.lineTo(-5, 370);
            ctx.lineTo(5, 410); ctx.lineTo(-5, 450); ctx.lineTo(5, 500);
            ctx.lineTo(-5, 550);
            ctx.stroke();
        }
    }

    blocks.forEach(b => { 
        if (b.type === 'door') { 
            ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); 
        } else if (b.type === 'pit') { 
            ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; 
        } else { 
            ctx.fillStyle = colors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = colors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); 
        } 
    });
    pickups.forEach(p => { ctx.fillStyle = 'red'; const thick = p.type === 'large' ? 10 : 5; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); });
    enemies.forEach(e => {
      if (e.health <= 0) return;
      if (e.enemyType === 'shield') { ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); } }
      else if (e.enemyType === 'flyer') { ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); ctx.fillStyle = '#fff'; ctx.fillRect(e.pos.x - 5, e.pos.y + 10, 5, 8); ctx.fillRect(e.pos.x + e.width, e.pos.y + 10, 5, 8); }
      else { ctx.fillStyle = e.type === 'boss' ? '#FFD700' : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); }
      ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5);
    });

    if (status !== GameStatus.LEVEL_INTRO || gameStateRef.current.introTimer >= 80) {
        drawPlayer(ctx, player);
    }

    projectiles.forEach(p => { if (p.isBoulder) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 4; ctx.stroke(); ctx.restore(); } else { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); } });
    particles.forEach(p => { ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();
    if (state.victoryString) { ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.strokeStyle = 'black'; ctx.lineWidth = 6; ctx.textAlign = 'center'; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); }
  }, [status, stageId, currentWeapon]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        createLevel();
        gameStateRef.current.player = { 
          ...gameStateRef.current.player, 
          pos: { x: -150, y: 400 }, 
          vel: { x: 0, y: 0 }, 
          health: INITIAL_PLAYER_HEALTH, 
          specialCharges: MAX_SPECIAL_CHARGES, 
          specialChargeTimer: 0, 
          facing: 1,
          isCharging: false,
          isUppercutting: false,
          isDucking: false,
          jumpPrepTimer: 0,
          invincibilityTimer: 0,
          hasUsedAirMove: false,
          jumpInputReleased: true,
          chargeInputReleased: true,
        };
        gameStateRef.current.doorOpenAmount = 0; 
        gameStateRef.current.doorState = 'closed'; 
        gameStateRef.current.victoryString = ""; 
        gameStateRef.current.introTimer = 0; 
        gameStateRef.current.bossExplosionTimer = 0;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { draw(); gameStateRef.current.frame = 0; }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  LEVEL_INTRO = 'LEVEL_INTRO',
  PLAYING = 'PLAYING',
  BOSS_TRANSITION = 'BOSS_TRANSITION',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY',
  PAUSED = 'PAUSED'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
  type: 'player' | 'enemy' | 'projectile' | 'boss';
}

export type WeaponType = 'GUN' | 'BOULDER' | 'SHOTGUN_ICE';

export interface Player extends Entity {
  isCharging: boolean;
  isUppercutting: boolean;
  isDucking: boolean;
  specialCharges: number;
  specialChargeTimer: number;
  chargeDuration: number;
  isJumping: boolean;
  isGrounded: boolean;
  facing: 1 | -1;
  shootCooldown: number;
  jumpPrepTimer: number;
  landTimer: number;
  invincibilityTimer: number;
  hasUsedAirMove: boolean;
  jumpInputReleased: boolean;
  chargeInputReleased: boolean;
  currentWeapon: WeaponType;
  availableWeapons: WeaponType[];
}

export interface Enemy extends Entity {
  enemyType: 'drone' | 'tank' | 'turret' | 'flyer' | 'shield';
  behavior: 'patrol' | 'shoot' | 'hover' | 'fly';
  patrolRange: number;
  initialX: number;
  shootTimer: number;
  isShieldActive?: boolean;
  hitCooldown?: number;
  frozenTimer?: number;
}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
  isBoulder?: boolean;
  isIce?: boolean;
  life?: number;
}

export interface Pickup {
  id: string;
  pos: Vector2;
  vel: Vector2;
  width: number;
  height: number;
  type: 'small' | 'large';
  life: number;
}

export interface Particle {
  pos: Vector2;
  vel: Vector2;
  life: number;
  color: string;
  size: number;
  isGlass?: boolean;
}

export const CANVAS_WIDTH = 800;
export const CANVAS_HEIGHT = 600;

export const GRAVITY = 0.5;
export const FRICTION = 0.85;

export const PLAYER_SPEED = 5;
export const PLAYER_JUMP_FORCE = -12;
export const CHARGE_SPEED = 22; 
export const CHARGE_ACCEL = 2.5; 
export const UPPERCUT_FORCE = -15; 
export const UPPERCUT_ACCEL = 0; 
export const CHARGE_DURATION = 25; 
export const SPECIAL_CHARGE_REGEN_FRAMES = 90; // 1.5 seconds at 60fps
export const MAX_SPECIAL_CHARGES = 2;
export const JUMP_PREP_FRAMES = 6;
export const LAND_FRAMES = 8;

export const STAGE_COLORS: Record<string, { ground: string, bg: string, accent: string }> = {
