    projectiles.forEach(p => { 
      if (p.isBoulder) { 
        ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = '#5D4037'; ctx.lineWidth = 4; ctx.stroke(); ctx.restore(); 
      } else { 
        ctx.fillStyle = p.isIce ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); 
        ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); 
      } 
    });

    // Draw Tsunami Wave
    if (state.tsunamiActive) {
        ctx.fillStyle = 'rgba(30, 144, 255, 0.4)';
        ctx.fillRect(state.tsunamiX - 100, 0, 150, CANVAS_HEIGHT);
        ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
        ctx.fillRect(state.tsunamiX + 40, 0, 10, CANVAS_HEIGHT); // Wave crest
    }

    particles.forEach(p => { ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();
    if (state.victoryString) { ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.strokeStyle = 'black'; ctx.lineWidth = 6; ctx.textAlign = 'center'; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); }
  }, [status, stageId, currentWeapon]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        createLevel();
        gameStateRef.current.player = { 
          ...gameStateRef.current.player, 
          pos: { x: -150, y: 400 }, 
          vel: { x: 0, y: 0 }, 
          health: INITIAL_PLAYER_HEALTH, 
          specialCharges: MAX_SPECIAL_CHARGES, 
          specialChargeTimer: 0, 
          facing: 1,
          isCharging: false,
          isUppercutting: false,
          isDucking: false,
          jumpPrepTimer: 0,
          invincibilityTimer: 0,
          hasUsedAirMove: false,
          jumpInputReleased: true,
          chargeInputReleased: true,
        };
        gameStateRef.current.doorOpenAmount = 0; 
        gameStateRef.current.doorState = 'closed'; 
        gameStateRef.current.victoryString = ""; 
        gameStateRef.current.introTimer = 0; 
        gameStateRef.current.bossExplosionTimer = 0;
        gameStateRef.current.tsunamiActive = false;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { draw(); gameStateRef.current.frame = 0; }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

