            {isInputLocked ? 'INFUSING GAINS...' : 'fuck yeah'}
          </button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="animate-in fade-in duration-1000 max-w-2xl">
          <h2 className="text-5xl md:text-7xl text-yellow-400 mb-6 font-black tracking-tighter">PLANET SAVED</h2>
          <p className="text-white text-lg mb-10 uppercase font-black tracking-widest italic drop-shadow-[2px_2px_0px_red]">Biology beats Silicon. THE PUMP IS ETERNAL.</p>
          <button 
            disabled={isInputLocked}
            onClick={onStart} 
            className={`px-14 py-8 text-white font-black border-b-[10px] text-2xl shadow-xl transition-all ${isInputLocked ? 'bg-gray-700 border-gray-900 opacity-50' : 'bg-yellow-600 hover:bg-yellow-400 border-yellow-900'}`}
          >
            {isInputLocked ? 'CONCLUDING...' : 'MAIN MENU'}
          </button>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 8px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: rgba(0, 0, 0, 0.4);
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #3b82f6;
          border-radius: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #60a5fa;
        }
      `}</style>
    </div>
  );
};

