              >
                RESUME
              </button>
              <button 
                onClick={onBossSelect}
                className={`px-10 py-4 bg-red-700 hover:bg-red-600 text-white text-xl font-black border-b-[8px] border-red-900 transition-all uppercase ${selectedIndex === 1 ? 'ring-4 ring-white scale-110' : ''}`}
