    // Flash effect during invincibility (but we'll still draw eyes separately for clarity)
    const isFlashing = p.invincibilityTimer > 0 && Math.floor(gameStateRef.current.frame / 5) % 2 === 0;

    // Skin and Pants
    if (!isFlashing) {
        ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6);
        ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4);
    }

