    ctx.save();
    const eyeY = drawY + (p.isDucking ? 5 : 10);
    const eyeSpacing = 12;
    const eyeSize = 6;
    const centerX = drawX + drawW / 2;
    const leftEyeX = centerX - (p.facing === 1 ? eyeSpacing / 2 : eyeSpacing / 2 + 5);
    const rightEyeX = centerX + (p.facing === 1 ? eyeSpacing / 2 + 5 : eyeSpacing / 2);

    // PRIORITY: SURPRISED LOOK during bounce-back
    if (p.pushbackTimer > 0) {
