      ctx.fillStyle = 'white';
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 5, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 5, 0, Math.PI * 2); ctx.fill();

      // Tiny shocked pinprick pupils (No bloodshot)
