      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 1.5, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 1.5, 0, Math.PI * 2); ctx.fill();

