    projectiles.forEach(p => { if (p.isBoulder) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.restore(); } else { ctx.fillStyle = p.isIce ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); } });
    if (state.tsunamiActive) {
        const dist = Math.abs(state.tsunamiX - state.tsunamiStartX); const progress = Math.min(1.0, dist / CANVAS_WIDTH); const currentTopY = progress * (CANVAS_HEIGHT * 0.67); const alphaFactor = 0.5 * (1.0 - (progress * 0.8));
        ctx.save(); ctx.fillStyle = `rgba(30, 144, 255, ${alphaFactor})`; const waveWidth = 200; const waveX = state.tsunamiDir === 1 ? state.tsunamiX - waveWidth : state.tsunamiX;
        ctx.beginPath(); if (state.tsunamiDir === 1) { ctx.moveTo(waveX, CANVAS_HEIGHT); ctx.lineTo(waveX, currentTopY + 20); ctx.quadraticCurveTo(state.tsunamiX, currentTopY, state.tsunamiX, currentTopY + 40); ctx.lineTo(state.tsunamiX, CANVAS_HEIGHT); } else { ctx.moveTo(state.tsunamiX + waveWidth, CANVAS_HEIGHT); ctx.lineTo(state.tsunamiX + waveWidth, currentTopY + 20); ctx.quadraticCurveTo(state.tsunamiX, currentTopY, state.tsunamiX, currentTopY + 40); ctx.lineTo(state.tsunamiX, CANVAS_HEIGHT); }
        ctx.closePath(); ctx.fill(); ctx.fillStyle = `rgba(255, 255, 255, ${alphaFactor * 1.5})`; ctx.fillRect(state.tsunamiX - (state.tsunamiDir === 1 ? 5 : 0), currentTopY, 5, 20); ctx.restore();
