    for (let i = 1200; i < doorX - 300; i += 1000) {
      state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: -1, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 100, initialX: i, shootTimer: 0, isShieldActive: true });
      state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
      state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
    }
    // BOSS HP
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 666, maxHealth: 666, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0 });
  }, [stageId]);

  const update = useCallback(() => {
    const state = gameStateRef.current;

    if (state.bossExplosionTimer > 0) {
      state.bossExplosionTimer--;
      if (state.frame % 3 === 0) {
        const offset = { x: (Math.random() - 0.5) * 200, y: (Math.random() - 0.5) * 200 };
        const pos = { x: state.bossExplosionPos.x + offset.x, y: state.bossExplosionPos.y + offset.y };
        spawnDeathShower(pos, (Math.random() - 0.5) * 6, 15);
        spawnExplosion(pos, '#FFD700', 15, (Math.random() - 0.5) * 25, 30);
      }
      state.particles = state.particles.filter(p => { 
          p.pos.x += p.vel.x; p.pos.y += p.vel.y; 
          if (p.isGlass || (p.color && FIRE_COLORS.includes(p.color))) p.vel.y += 0.25;
          p.life--; return p.life > 0; 
      });
      if (state.bossExplosionTimer === 0) {
        onBossDeath(); state.victoryString = "V"; state.postVictoryTimer = 0;
      }
      return;
    }

    if (status === GameStatus.PAUSED) return;

    if (status === GameStatus.LEVEL_INTRO) {
        state.introTimer++; state.camera.x = 0; state.player.facing = 1; 
        if (state.introTimer === 30) speakIntroLine(stageId); 

        if (state.introTimer < 80) {
            state.player.pos.x = -150; 
        } else {
            if (state.introTimer === 80) { 
                playGlassShatterSound(); 
                spawnGlassShatter({ x: 0, y: 450 }); 
            }

            const jumpDuration = 60;
            const t = Math.min(1.0, (state.introTimer - 80) / jumpDuration);
            state.player.pos.x = -100 + (t * 250);
            const peakHeight = 250;
            const groundY = 486;
            const startY = 400;
            state.player.pos.y = startY + (groundY - startY) * t - Math.sin(t * Math.PI) * peakHeight;

            if (state.introTimer >= 80 + jumpDuration) { 
              state.player.pos.y = groundY; 
              state.player.pos.x = 150;
              state.player.vel = { x: 0, y: 0 }; 
              state.player.isCharging = false;
              state.player.isUppercutting = false;
              state.player.jumpPrepTimer = 0;
              onIntroComplete(); 
            }
        }

        state.particles = state.particles.filter(p => { 
            p.pos.x += p.vel.x; p.pos.y += p.vel.y; 
            if (p.isGlass) { 
                p.vel.y += 0.25; 
                if (p.pos.y > 548) { p.pos.y = 548; p.vel.y = -p.vel.y * 0.2; p.vel.x *= 0.7; } 
            }
            p.life--; return p.life > 0; 
        });
        return;
    }

    if (status === GameStatus.BOSS_TRANSITION) {
        state.projectiles = []; 
        const targetCameraX = 7200; const targetPlayerX = 7300;
        state.camera.x += (targetCameraX - state.camera.x) * 0.05;
        state.player.pos.x += (targetPlayerX - state.player.pos.x) * 0.05;
        state.player.pos.y += (486 - state.player.pos.y) * 0.05; state.player.vel = { x: 0, y: 0 };
        if (Math.abs(state.camera.x - targetCameraX) < 1) { state.camera.x = targetCameraX; onBossEncounter(); }
        return;
    }

    if (status !== GameStatus.PLAYING) return;

    if (state.victoryString) {
      state.frame++;
      state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
      if (state.victoryString.length < 7) {
        state.postVictoryTimer++;
        if (state.postVictoryTimer >= 30) {
            const fullStr = "VICTORY"; state.victoryString += fullStr[state.victoryString.length]; state.postVictoryTimer = 0;
            if (state.victoryString.length === 7) { setTimeout(() => { onBossDefeated(stageId || ""); }, 2000); }
        }
      }
      return; 
    }

    // INPUT POLLING
    const gamepads = navigator.getGamepads();
    let padMoveX = 0, padMoveY = 0, padJump = false, padSpecial = false, padShoot = false;
    if (gamepads[0]) {
      const gp = gamepads[0];
      const DEADZONE = 0.2;
      if (Math.abs(gp.axes[0]) > DEADZONE) padMoveX = gp.axes[0];
      if (Math.abs(gp.axes[1]) > DEADZONE) padMoveY = gp.axes[1];
      if (gp.buttons[14]?.pressed) padMoveX = -1;
      if (gp.buttons[15]?.pressed) padMoveX = 1;
      if (gp.buttons[12]?.pressed) padMoveY = -1;
      if (gp.buttons[13]?.pressed) padMoveY = 1;
      padJump = gp.buttons[0]?.pressed; 
      padShoot = gp.buttons[2]?.pressed || gp.buttons[3]?.pressed; 
      padSpecial = gp.buttons[7]?.pressed; 
    }

    const km = keys.current;
    const { player, enemies, projectiles, particles, blocks, pickups } = state;

    const moveLeft = player.pushbackTimer <= 0 && (km['a'] || km['arrowleft'] || km['keya'] || padMoveX < -0.3);
    const moveRight = player.pushbackTimer <= 0 && (km['d'] || km['arrowright'] || km['keyd'] || padMoveX > 0.3);
    const moveDown = player.pushbackTimer <= 0 && (km['s'] || km['arrowdown'] || km['keys'] || padMoveY > 0.3);
    const moveUp = player.pushbackTimer <= 0 && (km['w'] || km['arrowup'] || km['keyw'] || padMoveY < -0.3);
    const jumpRequested = player.pushbackTimer <= 0 && (km[' '] || km['space'] || km['z'] || km['keyz'] || km['j'] || km['keyj'] || padJump);
    const chargeRequested = player.pushbackTimer <= 0 && (km['shift'] || km['shiftleft'] || km['shiftright'] || km['c'] || km['keyc'] || padSpecial);
    const shootRequested = player.pushbackTimer <= 0 && (mouse.current.down || padShoot); 

    state.frame++;
    if (state.vulgarityTimer > 0) { state.vulgarityTimer--; if (state.vulgarityTimer <= 0) state.lastVulgarity = ""; }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;
    if (player.killSatisfactionTimer > 0) player.killSatisfactionTimer--;
    if (player.pushbackTimer > 0) {
        player.pushbackTimer--;
        player.vel.x *= 0.9;
    }

    if (player.specialCharges < MAX_SPECIAL_CHARGES) {
      player.specialChargeTimer++;
      if (player.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) { player.specialCharges++; player.specialChargeTimer = 0; }
    } else { player.specialChargeTimer = 0; }

    if (!jumpRequested) player.jumpInputReleased = true;
    if (!chargeRequested) player.chargeInputReleased = true;

    const isFiringFlamethrower = shootRequested && currentWeapon === 'FLAMETHROWER';

    const checkIsWeakness = (p?: Projectile) => {
        if (stageId === 'Hector Hurricane' && p?.isBoulder) return true;
        if (stageId === 'Victor Volcano' && (p?.isTsunami || state.tsunamiActive)) return true;
        if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
        if (stageId === 'Ernie Earthquake' && p?.isIce) return true;
        return false;
    };

    const getBossDamage = (boss: Enemy, p?: Projectile) => {
        if (checkIsWeakness(p)) return WEAKNESS_DAMAGE;
        return BULLET_DAMAGE;
    };

    if (state.tsunamiActive) {
        state.tsunamiX += TSUNAMI_WAVE_SPEED * state.tsunamiDir;
        const dist = Math.abs(state.tsunamiX - state.tsunamiStartX);
        const maxDist = CANVAS_WIDTH;
        const progress = Math.min(1.0, dist / maxDist);
        const currentTopY = progress * (CANVAS_HEIGHT * 0.67);
        const currentHeight = CANVAS_HEIGHT - currentTopY;

        const fadeFactor = 1.0 - (progress * 0.8);
        const particleCount = Math.floor(15 * fadeFactor);
        for (let i = 0; i < particleCount; i++) {
            state.particles.push({
                pos: { x: state.tsunamiX + (Math.random() - 0.5) * 60, y: currentTopY + Math.random() * currentHeight },
                vel: { x: (TSUNAMI_WAVE_SPEED * state.tsunamiDir) * (0.8 + Math.random() * 0.4), y: (Math.random() - 0.5) * 5 },
                life: (30 + Math.random() * 20) * fadeFactor,
                color: WATER_COLORS[Math.floor(Math.random() * WATER_COLORS.length)],
                size: (5 + Math.random() * 25) * fadeFactor
            });
        }

        if (progress >= 1.0) { state.tsunamiActive = false; }

        if (currentHeight > 10) { 
            state.enemies.forEach(enemy => {
                if (enemy.health > 0 && !enemy.isBlownAway) {
                    const waveWidth = 200;
                    const isWithinWaveHorizontal = state.tsunamiDir === 1 
                        ? (enemy.pos.x + enemy.width > state.tsunamiX - waveWidth && enemy.pos.x < state.tsunamiX)
                        : (enemy.pos.x < state.tsunamiX + waveWidth && enemy.pos.x + enemy.width > state.tsunamiX);

                    if (isWithinWaveHorizontal && enemy.pos.y + enemy.height > currentTopY) {
                        if (enemy.type === 'boss') {
                            if (!enemy.hitCooldown || enemy.hitCooldown <= 0) {
                                const isWeakness = checkIsWeakness({ id: 'tsunami_proxy', isTsunami: true } as any);
                                enemy.health -= getBossDamage(enemy, { id: 'tsunami_proxy', isTsunami: true } as any); 
                                enemy.hitCooldown = 60; 
                                spawnExplosion(enemy.pos, '#fff', 20, 0, 15);
                                if (enemy.health <= 0) triggerBossDeath(enemy, player.facing, isWeakness);
                            }
                        } else {
                            enemy.health = 0;
                            enemy.isBlownAway = true;
                            enemy.vel.x = (25 + Math.random() * 10) * state.tsunamiDir;
                            enemy.vel.y = -15 - Math.random() * 10;
                            enemy.rotation = 0;
                            player.killSatisfactionTimer = 60; // Smug look
                        }
                        speakVulgarity('kill');
                    }
                }
            });
        }
    }

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; if (state.doorOpenAmount >= 160) state.doorState = 'open';
    } else if (state.doorState === 'open') {
      if (player.pos.x > 7250) state.doorState = 'closing';
    } else if (state.doorState === 'closing') {
      state.doorOpenAmount -= 5;
      if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; state.arenaLocked = true; onBossTransition(); }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting && !isFiringFlamethrower;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging && !player.isUppercutting && player.pushbackTimer <= 0) {
        if (!player.isDucking) {
          const speed = isFiringFlamethrower ? PLAYER_SPEED * FLAMETHROWER_SPEED_MULT : PLAYER_SPEED;
          if (isFiringFlamethrower) {
            if (moveLeft) player.vel.x = -speed;
            else if (moveRight) player.vel.x = speed;
            else player.vel.x *= FRICTION;
          } else {
            if (moveLeft) { player.vel.x = -speed; player.facing = -1; }
            else if (moveRight) { player.vel.x = speed; player.facing = 1; }
            else { player.vel.x *= FRICTION; }
          }
        } else { player.vel.x *= FRICTION; }

        if (jumpRequested && player.isGrounded && player.jumpInputReleased) { 
          player.jumpPrepTimer = JUMP_PREP_FRAMES; player.jumpInputReleased = false; 
        }
      } else if (player.isCharging) {
        player.chargeDuration--; player.vel.x += player.facing * CHARGE_ACCEL;
        if (Math.abs(player.vel.x) > CHARGE_SPEED) player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      } else if (player.isUppercutting) {
        player.chargeDuration--; player.vel.y += UPPERCUT_ACCEL;
        if (player.chargeDuration <= 0) { player.isUppercutting = false; }
      }

      if (chargeRequested && player.chargeInputReleased && !player.isCharging && !player.isUppercutting && !player.isDucking && player.specialCharges > 0 && !isFiringFlamethrower) {
        player.chargeInputReleased = false; 
        if (moveUp) { 
          player.specialCharges--; player.chargeDuration = CHARGE_DURATION; player.isUppercutting = true; player.vel.y = UPPERCUT_FORCE; player.isGrounded = false; 
        } else { 
          player.specialCharges--; player.chargeDuration = CHARGE_DURATION; player.isCharging = true; player.vel.x = player.facing * 5; 
        }
      }

      if (shootRequested && player.shootCooldown <= 0) {
        if (currentWeapon === 'GUN') {
          projectiles.push({ id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 }, width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' });
          player.shootCooldown = 12; playGunSound('gun');
        } else if (currentWeapon === 'BOULDER') {
          if (!projectiles.some(p => p.owner === 'player' && p.isBoulder)) {
            projectiles.push({ id: `b-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -40), y: player.pos.y + 20 }, vel: { x: player.facing * BOULDER_SPEED, y: 0 }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true });
            player.shootCooldown = 40;
          }
        } else if (currentWeapon === 'SHOTGUN') {
          for (let i = 0; i < 7; i++) {
            const angle = (i - 3) * 0.15;
            const speed = 11 + Math.random() * 6;
            projectiles.push({ id: `pellet-${Date.now()}-${i}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: Math.cos(angle) * player.facing * speed, y: Math.sin(angle) * speed }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true, life: 25 });
          }
          player.shootCooldown = SHOTGUN_COOLDOWN; playGunSound('ice');
        } else if (currentWeapon === 'FLAMETHROWER') {
            if (state.frame % 2 === 0) {
                playGunSound('flame');
                for (let i = 0; i < 6; i++) {
                    const angle = (Math.random() - 0.5) * 0.6;
                    const speed = 8 + Math.random() * 8;
                    const flameColor = FIRE_COLORS[Math.floor(Math.random() * FIRE_COLORS.length)];
                    state.particles.push({ pos: { x: player.pos.x + (player.facing === 1 ? player.width - 5 : 5), y: player.pos.y + 30 }, vel: { x: Math.cos(angle) * player.facing * speed + player.vel.x, y: Math.sin(angle) * speed }, life: 15 + Math.random() * 20, color: flameColor, size: 8 + Math.random() * 12 });
                }
                const fRect = { x: player.facing === 1 ? player.pos.x + player.width : player.pos.x - FLAMETHROWER_RANGE, y: player.pos.y + 10, w: FLAMETHROWER_RANGE, h: 50 };
                state.enemies.forEach(enemy => {
                    if (enemy.health > 0 && !enemy.isBlownAway) {
                        if (enemy.pos.x < fRect.x + fRect.w && enemy.pos.x + enemy.width > fRect.x && enemy.pos.y < fRect.y + fRect.h && enemy.pos.y + enemy.height > fRect.y) {
                            const isWeakness = checkIsWeakness();
                            if (enemy.type === 'boss') {
                                if (!enemy.hitCooldown || enemy.hitCooldown <= 0) {
                                    enemy.health -= getBossDamage(enemy); enemy.hitCooldown = 60; spawnExplosion(enemy.pos, '#FF4500', 5, 0, 15);
                                    if (enemy.health <= 0) triggerBossDeath(enemy, player.facing, isWeakness);
                                }
                            } else {
                                enemy.health -= FLAMETHROWER_DAMAGE;
                                if (state.frame % 10 === 0) spawnExplosion(enemy.pos, '#FF4500', 3, 0, 10);
                                if (enemy.health <= 0) { 
                                  spawnDeathShower(enemy.pos, player.facing); 
                                  spawnPickup(enemy.pos); 
                                  speakVulgarity('kill'); 
                                  player.killSatisfactionTimer = 60; // Smug look
                                }
                            }
                        }
                    }
                });
            }
        } else if (currentWeapon === 'TSUNAMI') {
            if (!state.tsunamiActive) {
                state.tsunamiActive = true; state.tsunamiDir = player.facing; state.tsunamiStartX = player.facing === 1 ? state.camera.x : state.camera.x + CANVAS_WIDTH; state.tsunamiX = state.tsunamiStartX; player.shootCooldown = TSUNAMI_COOLDOWN; playGunSound('tsunami');
            }
        }
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    player.vel.y += GRAVITY;
    if (!jumpRequested && player.vel.y < 0 && !player.isGrounded && !player.isCharging && !player.isUppercutting) player.vel.y *= 0.5;
    player.pos.x += player.vel.x; player.pos.y += player.vel.y;
    if (player.pos.x < 50) player.pos.x = 50;

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door' && state.doorOpenAmount > 0) return;
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; return; }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; if (player.isCharging) player.isCharging = false; }
        else { if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.hasUsedAirMove = false; player.vel.y = 0; } else { player.pos.y = block.y + block.h; player.vel.y = 0; } }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.isBlownAway) { enemy.pos.x += enemy.vel.x; enemy.pos.y += enemy.vel.y; enemy.vel.y += GRAVITY * 0.5; enemy.rotation = (enemy.rotation || 0) + 0.3; return enemy.pos.y < 1000; }
      if (enemy.health <= 0) return false; 
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
      if (enemy.frozenTimer && enemy.frozenTimer > 0) { enemy.frozenTimer--; return true; } 

      const onScreen = enemy.pos.x + enemy.width > state.camera.x && enemy.pos.x < state.camera.x + CANVAS_WIDTH;
      if (enemy.behavior === 'patrol') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; }
      else if (enemy.behavior === 'fly') { enemy.pos.x += enemy.vel.x; enemy.pos.y += Math.sin(state.frame / 20) * 2; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; }
      else if (enemy.behavior === 'shoot' && (state.bossSpawned || enemy.type !== 'boss')) {
        if (onScreen) {
          enemy.shootTimer++;
          if (enemy.enemyType === 'shield') {
              enemy.isShieldActive = enemy.shootTimer < 80;
              if (enemy.shootTimer > 120) { projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0; }
          } else if (enemy.shootTimer > 60) {
              projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0;
          }
        }
      }

      let hbW = player.width, hbH = player.height, hbX = player.pos.x, hbY = player.pos.y;
      if (player.isCharging) { hbW = player.width + 10; hbH = player.height - 10; }
      else if (player.isUppercutting) { hbW = player.width - 15; hbH = player.height + 40; hbY = player.pos.y - 30; hbX = player.pos.x + 7.5; }
      const chargeHit = (player.isCharging || player.isUppercutting) && hbX < enemy.pos.x + enemy.width && hbX + hbW > enemy.pos.x && hbY < enemy.pos.y + enemy.height && hbY + hbH > enemy.pos.y;

      if (chargeHit && onScreen && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
        enemy.health -= BOSS_CHARGE_DAMAGE; enemy.hitCooldown = 60; 
        if (enemy.health > 0) { 
          enemy.vel.x = player.facing * 20; if (player.isUppercutting) enemy.vel.y = UPPERCUT_FORCE; spawnExplosion(enemy.pos, '#fff', 20, player.facing * 12); player.vel.x = -player.facing * 18; player.vel.y = -4; player.pushbackTimer = 20; player.isCharging = false; player.isUppercutting = false; player.invincibilityTimer = 30; 
        } else {
            if (enemy.type === 'boss') triggerBossDeath(enemy, player.facing, false);
            else { 
              spawnDeathShower(enemy.pos, player.facing); 
              spawnPickup(enemy.pos); 
              speakVulgarity(player.isUppercutting ? 'uppercut_kill' : 'charge_kill'); 
              player.killSatisfactionTimer = 60; // Smug look
            }
            return false;
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x && player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
          player.health -= 15; player.invincibilityTimer = 60; speakVulgarity('hurt');
      }
      return true;
    });

    state.projectiles = projectiles.filter(p => {
      if (p.isBoulder) {
        p.vel.y += GRAVITY; p.pos.y += p.vel.y;
