      blocks.forEach(block => { if (block.type !== 'pit' && p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) { p.pos.y = block.y - p.height; p.vel.y = 0; } });
      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + player.height > player.pos.y) {
        if (p.type.includes('health')) player.health = Math.min(player.maxHealth, player.health + (p.type === 'large_health' ? 50 : 20));
        else {
