      ctx.beginPath(); ctx.moveTo(leftEyeX - 6, eyeY - 5); ctx.lineTo(leftEyeX + 2, eyeY - 8); ctx.stroke(); ctx.beginPath(); ctx.moveTo(rightEyeX + 6, eyeY - 5); ctx.lineTo(rightEyeX - 2, eyeY - 8); ctx.stroke();
    } else if (p.isCharging || p.isUppercutting) {
      ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(leftEyeX - 4, eyeY - 2); ctx.lineTo(leftEyeX + 4, eyeY + 2); ctx.stroke(); ctx.beginPath(); ctx.moveTo(rightEyeX - 4, eyeY + 2); ctx.lineTo(rightEyeX + 4, eyeY - 2); ctx.stroke();
    } else if (p.isDucking) {
