  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onBossTransition, onTogglePause, currentWeapon, respawn, invincibilityEnabled]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player & { killSatisfactionTimer: number }) => {
