    particles.forEach(p => { ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();
    if (state.victoryString) { ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.strokeStyle = 'black'; ctx.lineWidth = 6; ctx.textAlign = 'center'; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); }
    if (state.deathTimer > 0) { 
        ctx.save();
        ctx.font = 'bold 60px "Press Start 2P"'; 
        ctx.fillStyle = '#FF0000'; ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.textAlign = 'center'; 
        ctx.shadowColor = '#8B0000'; ctx.shadowBlur = 30;
        ctx.strokeText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        for(let i=0; i<8; i++) {
            ctx.fillStyle = '#8B0000';
            ctx.fillRect(CANVAS_WIDTH/2 - 250 + i*70, CANVAS_HEIGHT/2 + 40, 15, 20 + (Math.sin(state.frame * 0.1 + i) * 30));
        }
        ctx.restore();
    }
  }, [status, stageId, currentWeapon, invincibilityEnabled]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 400 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, specialCharges: MAX_SPECIAL_CHARGES, specialChargeTimer: 0, pushbackTimer: 0, facing: 1, isCharging: false, isUppercutting: false, isDucking: false, jumpPrepTimer: 0, invincibilityTimer: 0, killSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true, weaponAmmo: { ...initialAmmo } };
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.victoryString = ""; gameStateRef.current.introTimer = 0; gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.tsunamiActive = false; gameStateRef.current.deathTimer = 0; gameStateRef.current.deathString = ""; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.frame = 1;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { draw(); gameStateRef.current.frame = 0; }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

