        ctx.beginPath(); ctx.moveTo(leftEyeX - 5, eyeY - 3 + i*3); ctx.lineTo(leftEyeX - 1, eyeY); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(rightEyeX + 5, eyeY - 3 + i*3); ctx.lineTo(rightEyeX + 1, eyeY); stroke();
      }
      ctx.fillStyle = invincibilityEnabled ? 'lime' : 'red'; ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 2, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 2, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(leftEyeX - 8, eyeY - 6); ctx.lineTo(leftEyeX + 3, eyeY - 2); ctx.stroke(); ctx.beginPath(); ctx.moveTo(rightEyeX + 8, eyeY - 6); ctx.lineTo(rightEyeX - 3, eyeY - 2); ctx.stroke();
    } else if (p.killSatisfactionTimer > 0) {
      ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(leftEyeX, eyeY + 2, eyeSize, Math.PI, 0); ctx.stroke(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY + 2, eyeSize, Math.PI, 0); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(leftEyeX - 6, eyeY - 5); ctx.lineTo(leftEyeX + 2, eyeY - 8); ctx.stroke(); ctx.beginPath(); ctx.moveTo(rightEyeX + 6, eyeY - 5); ctx.lineTo(rightEyeX - 2, eyeY - 8); ctx.stroke();
    } else if (p.isCharging || p.isUppercutting) {
      ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(leftEyeX - 4, eyeY - 2); ctx.lineTo(leftEyeX + 4, eyeY + 2); ctx.stroke(); ctx.beginPath(); ctx.moveTo(rightEyeX - 4, eyeY + 2); ctx.lineTo(rightEyeX + 4, eyeY - 2); ctx.stroke();
    } else if (p.isDucking) {
      ctx.fillStyle = 'black'; ctx.fillRect(leftEyeX - 3, eyeY, 6, 2); ctx.fillRect(rightEyeX - 3, eyeY, 6, 2);
    } else {
      ctx.fillStyle = 'black'; ctx.fillRect(leftEyeX - 2, eyeY - 2, 4, 6); ctx.fillRect(rightEyeX - 2, eyeY - 2, 4, 6);
    }
    ctx.restore();
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14, gunY = p.isDucking ? drawY + 10 : drawY + 25;
    if (!isFlashing) {
        if (currentWeapon === 'GUN') { ctx.fillStyle = '#333'; ctx.fillRect(gunX, gunY, 24, 10); } 
        else if (currentWeapon === 'BOULDER') { ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(gunX + 12, gunY + 5, 12, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); }
        else if (currentWeapon === 'SHOTGUN') { ctx.fillStyle = '#00FFFF'; ctx.fillRect(gunX, gunY, 20, 12); }
        else if (currentWeapon === 'FLAMETHROWER') { ctx.fillStyle = '#444'; ctx.fillRect(gunX, gunY, 30, 14); ctx.fillStyle = '#FF4500'; ctx.fillRect(p.facing === 1 ? gunX + 30 : gunX - 5, gunY + 4, 5, 6); }
        else if (currentWeapon === 'TSUNAMI') { ctx.fillStyle = '#1E90FF'; ctx.fillRect(gunX, gunY, 32, 16); ctx.fillStyle = '#fff'; ctx.fillRect(p.facing === 1 ? gunX + 28 : gunX, gunY + 4, 4, 8); }
    }
    if (gameStateRef.current.lastVulgarity && gameStateRef.current.vulgarityTimer > 0) { ctx.font = 'bold 10px "Press Start 2P"'; ctx.fillStyle = 'white'; ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.textAlign = 'center'; ctx.fillText(gameStateRef.current.lastVulgarity, drawX + drawW/2, drawY - 20); ctx.shadowBlur = 0; }
    ctx.restore();
  };

  const drawBossSprite = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null) => {
      const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
      switch (id) {
        case 'Artie Avalanche':
            ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeStyle = 'black'; ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
            ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#2E86C1'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, Math.PI, 0); ctx.fill(); ctx.stroke(); break;
        case 'Victor Volcano':
            ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
            ctx.fillStyle = '#8b4513'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.3, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#FF4500'; ctx.fillRect(width * 0.2, height * 0.2, width * 0.6, height * 0.1);
            ctx.fillStyle = '#FFD700'; ctx.beginPath(); ctx.arc(width * 0.4, height * 0.3, 4, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(width * 0.6, height * 0.3, 4, 0, Math.PI * 2); ctx.fill(); break;
        case 'Ernie Earthquake':
            ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7);
            ctx.fillStyle = '#e0ac69'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); ctx.strokeRect(width * 0.2, 0, width * 0.6, height * 0.4);
            ctx.fillStyle = '#4E2C00'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.1);
            ctx.fillStyle = '#A04000'; ctx.fillRect(width * 0.3, -height * 0.1, width * 0.4, height * 0.15); break;
        case 'Hector Hurricane':
            ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7);
            ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#D1D1D1'; ctx.beginPath(); ctx.moveTo(width * 0.3, height * 0.15); ctx.lineTo(width * 0.5, -height * 0.1); ctx.lineTo(width * 0.7, height * 0.15); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#00FFFF'; ctx.fillRect(width * 0.35, height * 0.25, width * 0.3, height * 0.08); ctx.strokeRect(width * 0.35, height * 0.25, width * 0.3, height * 0.08); break;
        default: ctx.fillStyle = 'yellow'; ctx.fillRect(0, 0, width, height); break;
      }
      ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return; const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) { ctx.fillStyle = 'black'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); return; }
    const { player, enemies, projectiles, particles, blocks, camera, pickups } = state;
    const colors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = colors.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => { if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); } else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; } else { ctx.fillStyle = colors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = colors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); } });
    pickups.forEach(p => {
        if (p.type.includes('health')) { ctx.fillStyle = 'red'; const thick = p.type === 'large_health' ? 10 : 5; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); } 
        else { ctx.fillStyle = 'yellow'; const thick = p.type === 'large_ammo' ? 12 : 6; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); }
    });
    enemies.forEach(e => {
      if (e.health <= 0 && !e.isBlownAway) return;
      ctx.save();
      if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
      else if (e.type === 'boss' && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }
      if (e.type === 'boss') { drawBossSprite(ctx, e, stageId); } 
      else { if (e.enemyType === 'shield') { ctx.fillStyle = COLORS.ENEMY_SHIELD; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); if (e.isShieldActive) { ctx.fillStyle = '#88f'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, 12, e.height + 10); } } else if (e.enemyType === 'flyer') { ctx.fillStyle = COLORS.ENEMY_FLYER; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } else { ctx.fillStyle = e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } }
      if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
      if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
      ctx.restore();
    });
    if (status !== GameStatus.LEVEL_INTRO || gameStateRef.current.introTimer >= 80) drawPlayer(ctx, player);
    projectiles.forEach(p => { if (p.isBoulder) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.restore(); } else { ctx.fillStyle = p.isIce ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); } });
    particles.forEach(p => { ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    ctx.restore();
    if (state.victoryString) { ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.strokeStyle = 'black'; ctx.lineWidth = 6; ctx.textAlign = 'center'; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); }
    if (state.deathTimer > 0) { 
        ctx.save();
        ctx.font = 'bold 60px "Press Start 2P"'; 
        ctx.fillStyle = '#FF0000'; ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.textAlign = 'center'; 
        ctx.shadowColor = '#8B0000'; ctx.shadowBlur = 30;
        ctx.strokeText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        for(let i=0; i<8; i++) {
            ctx.fillStyle = '#8B0000';
            ctx.fillRect(CANVAS_WIDTH/2 - 250 + i*70, CANVAS_HEIGHT/2 + 40, 15, 20 + (Math.sin(state.frame * 0.1 + i) * 30));
        }
        ctx.restore();
    }
  }, [status, stageId, currentWeapon, invincibilityEnabled]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        createLevel();
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: 150, y: 400 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, specialCharges: MAX_SPECIAL_CHARGES, specialChargeTimer: 0, pushbackTimer: 0, facing: 1, isCharging: false, isUppercutting: false, isDucking: false, jumpPrepTimer: 0, invincibilityTimer: 0, killSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true, weaponAmmo: { ...initialAmmo } };
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.victoryString = ""; gameStateRef.current.introTimer = 0; gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.tsunamiActive = false; gameStateRef.current.deathTimer = 0; gameStateRef.current.deathString = ""; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.frame = 1;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { draw(); gameStateRef.current.frame = 0; }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

