import { GoogleGenAI } from "@google/genai";

// Always use a named parameter for the API key.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates an intimidating boss taunt using the Gemini 3 Flash model.
 * @param bossName - The name of the boss.
 */
export async function getBossTaunt(bossName: string) {
  try {
    // Using gemini-3-flash-preview for basic text tasks as recommended.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a short, intimidating, and slightly vulgar taunt for a boss named "${bossName}" in a retro-style action game called "MEATHEAD" where the protagonist is a steroid-pumped muscleman. The taunt should be one sentence and very aggressive.`,
      config: {
        systemInstruction: "You are writing dialogue for a 90s-style hyper-masculine arcade game. Be gritty, slightly vulgar, and focused on physical dominance/weakness.",
      },
    });
    // Accessing the .text property directly (not a method).
    return response.text?.trim() || "You're dead meat!";
  } catch (error) {
    console.error("Error fetching boss taunt:", error);
    // Fallback to local taunts if API call fails.
    const taunts: Record<string, string> = {
      'Artie Avalanche': "You're going to become freezer burn, Meatface.",
      'Victor Volcano': "Well done. Which is how I'll cook you when I'm done with you.",
      'Hector Hurricane': "Torrent of piss!",
      'Ernie Earthquake': "Are you ready to rumble?"
    };
    return taunts[bossName] || "I'm going to break you!";
  }
}

/**
 * Generates an arrogant victory speech for the protagonist using the Gemini 3 Flash model.
 * @param bossName - The name of the defeated boss.
 */
export async function getMeatheadVictorySpeech(bossName: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Meathead just defeated "${bossName}". Generate a one-sentence victory line that is incredibly arrogant, mentions "gains", "the pump", or "biology", and is slightly vulgar.`,
      config: {
        systemInstruction: "You are the voice of Meathead, a character who only cares about muscle mass and physical superiority. You are extremely arrogant and dismissive of defeated foes.",
      },
    });
    return response.text?.trim() || "Your biological limits were clear from the start. Only the pump endures.";
  } catch (error) {
    console.error("Error fetching victory speech:", error);
    return "Your biological limits were clear from the start. Only the pump endures.";
  }
}

