    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryString: "",
    deathString: "",
    deathTimer: 0,
    postVictoryTimer: 0,
    introTimer: 0,
