      ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(leftEyeX - 8, eyeY - 6); ctx.lineTo(leftEyeX + 3, eyeY - 2); ctx.stroke(); ctx.beginPath(); ctx.moveTo(rightEyeX + 8, eyeY - 6); ctx.lineTo(rightEyeX - 3, eyeY - 2); ctx.stroke();
    } else if (p.killSatisfactionTimer > 0) {
