    if (!isFlashing) { ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6); ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4); }
    ctx.save();
    const eyeY = drawY + (p.isDucking ? 5 : 10), eyeSpacing = 12, eyeSize = 6, centerX = drawX + drawW / 2;
    const leftEyeX = centerX - (p.facing === 1 ? eyeSpacing / 2 : eyeSpacing / 2 + 5);
    const rightEyeX = centerX + (p.facing === 1 ? eyeSpacing / 2 + 5 : eyeSpacing / 2);

    if (gameStateRef.current.playerStunTimer > 0) { 
      ctx.fillStyle = 'yellow'; ctx.beginPath(); ctx.arc(centerX, eyeY - 20, 10, 0, Math.PI * 2); ctx.fill(); 
    }

    if (p.pushbackTimer > 0) {
      // Hurt Expression
      ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 5, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 1.5, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 1.5, 0, Math.PI * 2); ctx.fill();
    } else if (p.invincibilityTimer > 0 || invincibilityEnabled) {
      // Invincibility Expression
      ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 3, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 3, 0, Math.PI * 2); ctx.fill();
    } else if (p.killSatisfactionTimer > 0) {
      // Happy / Kill Expression
      ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(leftEyeX, eyeY + 2, eyeSize, Math.PI, 0); ctx.stroke(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY + 2, eyeSize, Math.PI, 0); ctx.stroke();
    } else { 
