const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      specialCharges: MAX_SPECIAL_CHARGES,
      specialChargeTimer: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0,
      pushbackTimer: 0,
      killSatisfactionTimer: 0,
      hasUsedAirMove: false,
      jumpInputReleased: true,
      chargeInputReleased: true,
      currentWeapon: 'GUN',
      availableWeapons: ['GUN'],
      weaponAmmo: { ...initialAmmo }
    } as Player & { killSatisfactionTimer: number },
    enemies: [] as (Enemy & { bossState?: 'idle' | 'jumping' | 'attacking' | 'hurricane' | 'telegraphing', stateTimer?: number, jumpCount?: number, pauseTimer?: number, isGroundedBoss?: boolean, sideTimer?: number })[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as Particle[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    lastVulgarity: "",
    vulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryString: "",
    deathString: "",
    deathTimer: 0,
    postVictoryTimer: 0,
    introTimer: 0,
    bossExplosionTimer: 0,
    bossExplosionPos: { x: 0, y: 0 },
    tsunamiX: -1,
    tsunamiStartX: 0,
    tsunamiActive: false,
    tsunamiDir: 1,
    bossVolcanoes: [] as Volcano[],
    bossVolcanoTelegraphs: [] as Volcano[],
    bossTsunamiSide: 0 as number,
    bossTsunamiTimer: 0,
    playerStunTimer: 0,
    screenShakeTimer: 0,
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => {
    gameStateRef.current.player.currentWeapon = currentWeapon;
  }, [currentWeapon]);

  useEffect(() => {
    if (gameStateRef.current.deathTimer <= 0) {
      gameStateRef.current.player.weaponAmmo = { ...initialAmmo };
    }
  }, [initialAmmo]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keys.current[e.key.toLowerCase()] = true;
    const handleKeyUp = (e: KeyboardEvent) => keys.current[e.key.toLowerCase()] = false;
    const handleMouseDown = () => mouse.current.down = true;
    const handleMouseUp = () => mouse.current.down = false;
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      if (audioCtxRef.current) audioCtxRef.current.close();
    };
  }, []);

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15, isGlass: boolean = false) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      if (state.particles.length > 300) break;
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: isGlass ? 150 + Math.random() * 200 : 20 + Math.random() * 80,
        color: color,
        size: isGlass ? 1 + Math.random() * 4 : 2 + Math.random() * 12,
        isGlass
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0, multiplier: number = 1) => {
    FLESH_COLORS.forEach(c => spawnExplosion(pos, c, Math.ceil(8 * multiplier), facing * 18, 25));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, Math.ceil(12 * multiplier), facing * 22, 35));
    spawnExplosion(pos, '#FF4500', Math.ceil(10 * multiplier), facing * 12, 40);
    spawnExplosion(pos, '#FFFF00', Math.ceil(5 * multiplier), facing * 8, 30);
  };

  const spawnRockShatter = (pos: Vector2) => {
    ROCK_COLORS.forEach(c => spawnExplosion(pos, c, 10, 0, 10));
  };

  const spawnGlassShatter = (pos: Vector2) => {
    GLASS_COLORS.forEach(c => spawnExplosion(pos, c, 50, 15, 25, true));
  };

  const triggerBossDeath = (boss: Enemy, playerFacing: number, wasWeakness: boolean) => {
    const state = gameStateRef.current;
    if (state.bossExplosionTimer > 0) return;
    const pos = { x: boss.pos.x + boss.width / 2, y: boss.pos.y + boss.height / 2 };
    if (wasWeakness) {
      state.bossExplosionTimer = 220; 
      state.bossExplosionPos = pos;
      spawnDeathShower(pos, playerFacing, 1.5); 
      spawnExplosion(pos, '#FFD700', 5, (Math.random() - 0.5) * 15, 20);
    } else {
      spawnDeathShower(pos, playerFacing, 6);
      onBossDeath(); 
      state.victoryString = "V"; 
      state.postVictoryTimer = 0;
    }
    state.player.killSatisfactionTimer = 120;
    state.arenaLocked = false;
    speakVulgarity('kill');
  };

  const speakVulgarity = (category: VulgarityType) => {
    if (gameStateRef.current.voiceLineCooldown > 0 && category !== 'death') return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); 
      let pool = KILL_VULGARITIES;
      if (category === 'hurt') pool = HURT_VULGARITIES;
      if (category === 'death') pool = DEATH_VULGARITIES;
      if (category === 'charge_kill') pool = CHARGE_KILL_VULGARITIES;
      if (category === 'uppercut_kill') pool = UPPERCUT_KILL_VULGARITIES;

      const text = pool[Math.floor(Math.random() * pool.length)];
      gameStateRef.current.lastVulgarity = text;
      gameStateRef.current.vulgarityTimer = 120;
      gameStateRef.current.voiceLineCooldown = 90;
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  };

  const playGlassShatterSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      for(let i=0; i<12; i++) {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.type = i % 2 === 0 ? 'sine' : 'sawtooth';
        osc.frequency.setValueAtTime(1200 + Math.random() * 5000, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
        gain.gain.setValueAtTime(0.1, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
        osc.connect(gain); gain.connect(ctx.destination);
        osc.start(); osc.stop(ctx.currentTime + 0.3);
      }
    } catch (e) {}
  };

  const playGunSound = (type: 'gun' | 'ice' | 'flame' | 'tsunami' = 'gun') => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator(); const gain = ctx.createGain();
      if (type === 'gun') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(150, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.05, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      } else if (type === 'ice') {
        osc.type = 'sine'; osc.frequency.setValueAtTime(800, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.08, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.15);
      } else if (type === 'flame') {
        osc.type = 'triangle'; osc.frequency.setValueAtTime(40 + Math.random() * 40, ctx.currentTime);
        osc.frequency.linearRampToValueAtTime(120, ctx.currentTime + 0.05);
        gain.gain.setValueAtTime(0.03, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);
      } else if (type === 'tsunami') {
          const bufferSize = ctx.sampleRate * 0.5; 
          const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
          const data = buffer.getChannelData(0);
          for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
          const noise = ctx.createBufferSource();
          noise.buffer = buffer;
          const filter = ctx.createBiquadFilter();
          filter.type = 'lowpass'; filter.frequency.setValueAtTime(1000, ctx.currentTime); filter.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.5);
          noise.connect(filter); filter.connect(ctx.destination);
          noise.start();
          return;
      }
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  const speakIntroLine = (id: string | null) => {
    if (!id || !INTRO_QUOTES[id]) return;
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(INTRO_QUOTES[id]);
      utterance.pitch = 0.1; utterance.rate = 1.0; utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
      gameStateRef.current.lastVulgarity = INTRO_QUOTES[id];
      gameStateRef.current.vulgarityTimer = 180;
    }
  };

  const spawnPickup = (pos: Vector2) => {
    const r = Math.random();
    if (r < 0.6) {
        const pr = Math.random();
        let type: PickupType;
        if (pr < 0.25) type = 'small_health';
        else if (pr < 0.35) type = 'large_health';
        else if (pr < 0.8) type = 'small_ammo';
        else type = 'large_ammo';
        gameStateRef.current.pickups.push({
            id: `pickup-${Date.now()}-${Math.random()}`,
            pos: { ...pos },
            vel: { x: (Math.random() - 0.5) * 4, y: -5 },
            width: 20,
            height: 20,
            type,
            life: 600
        });
    }
  };

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; const doorX = 7200;
    state.arenaLocked = false;
    state.doorState = 'closed';
    state.doorOpenAmount = 0;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: 40, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: 40, h: 1400, type: 'wall' },
      { x: doorX, y: 0, w: stageWidth - doorX, h: 100, type: 'wall' },
      { x: 7960, y: 100, w: 40, h: 500, type: 'wall' }
    ];
    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            state.blocks.push({ x: i, y: 450, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 200, y: 320, w: 150, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 190, w: 150, h: 20, type: 'platform' });
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            state.blocks.push({ x: i, y: 380, w: 300, h: 20, type: 'platform' });
            state.blocks.push({ x: i + 400, y: 250, w: 200, h: 20, type: 'platform' });
        }
        for (let x = 1200; x < doorX; x += 1800) { state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); }
    } else {
        for (let i = 600; i < doorX; i += 600) { state.blocks.push({ x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' }); }
    }
    state.enemies = [];
    if (!jumpToBossEnabled) {
      for (let i = 1200; i < doorX - 300; i += 1000) {
        state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 0, initialX: i, shootTimer: 0, isShieldActive: true });
        state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
        state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
        state.enemies.push({ id: `rusher-${i}`, pos: { x: i + 800, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 300, maxHealth: 300, type: 'enemy', enemyType: 'tank', behavior: 'patrol', patrolRange: 0, initialX: i + 800, shootTimer: 0, pauseTimer: 0 });
      }
    }
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 666, maxHealth: 666, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0, bossState: 'idle', stateTimer: 60 });
  }, [stageId, jumpToBossEnabled]);

  const respawn = useCallback(() => {
    const state = gameStateRef.current;
    state.player.health = INITIAL_PLAYER_HEALTH; 
    state.player.pos = { x: 150, y: 100 }; 
    state.player.vel = { x: 0, y: 0 }; 
    state.player.invincibilityTimer = 60; 
    state.player.facing = 1; 
    state.player.isCharging = false;
    state.player.isUppercutting = false;
    state.player.weaponAmmo = {
        'GUN': Infinity,
        'BOULDER': MAX_AMMO['BOULDER'],
        'SHOTGUN': MAX_AMMO['SHOTGUN'],
        'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
        'TSUNAMI': MAX_AMMO['TSUNAMI']
    };
    state.deathTimer = 0;
    state.deathString = "";
    state.frame = 1; 
    state.arenaLocked = false;
    state.doorState = 'closed';
    state.doorOpenAmount = 0;
    state.bossVolcanoes = [];
    state.bossVolcanoTelegraphs = [];
    state.bossTsunamiSide = 0;
    state.playerStunTimer = 0;
    state.tsunamiActive = false;
    state.screenShakeTimer = 0;
    createLevel();
  }, [createLevel]);

  const checkIsWeakness = (p?: Partial<Projectile>) => {
    if (!p) {
        if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
        return false;
    }
    if (stageId === 'Hector Hurricane' && p.isBoulder) return true;
    if (stageId === 'Victor Volcano' && p.isTsunami) return true;
    if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
    if (stageId === 'Ernie Earthquake' && p.isIce) return true;
    return false;
  };

  const getBossDamage = (boss: Enemy, p?: Partial<Projectile>) => checkIsWeakness(p) ? WEAKNESS_DAMAGE : BULLET_DAMAGE;

  const update = useCallback(() => {
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups } = state;

    state.frame++;

    if (state.screenShakeTimer > 0) state.screenShakeTimer--;

    if (state.deathTimer > 0) {
        state.deathTimer--;
        if (state.deathTimer === 0) respawn();
        state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
        return;
    }

    if (state.bossExplosionTimer > 0) {
      state.bossExplosionTimer--;
      if (state.frame % 3 === 0) {
        const offset = { x: (Math.random() - 0.5) * 200, y: (Math.random() - 0.5) * 200 };
        const pos = { x: state.bossExplosionPos.x + offset.x, y: state.bossExplosionPos.y + offset.y };
        spawnDeathShower(state.bossExplosionPos, player.facing, 1.5); 
        spawnExplosion(pos, '#FFD700', 5, (Math.random() - 0.5) * 15, 20);
      }
      state.particles = state.particles.filter(p => { 
          p.pos.x += p.vel.x; p.pos.y += p.vel.y; 
          if (p.isGlass || (p.color && FIRE_COLORS.includes(p.color))) p.vel.y += 0.25;
          p.life--; return p.life > 0; 
      });
      if (state.bossExplosionTimer === 0) {
        onBossDeath(); state.victoryString = "V"; state.postVictoryTimer = 0;
      }
      return;
    }

    if (status === GameStatus.PAUSED) return;

    if (status === GameStatus.LEVEL_INTRO) {
        state.introTimer++; 
        const baseStartX = jumpToBossEnabled ? 6400 : 0;
        state.camera.x = baseStartX; 
        state.player.facing = 1; 
        if (state.introTimer === 30 && !jumpToBossEnabled) speakIntroLine(stageId); 
        if (state.introTimer < 80) { state.player.pos.x = baseStartX - 150; } 
        else {
            if (state.introTimer === 80) { playGlassShatterSound(); spawnGlassShatter({ x: baseStartX, y: 450 }); }
            const jumpDuration = 60;
            const t = Math.min(1.0, (state.introTimer - 80) / jumpDuration);
            state.player.pos.x = baseStartX - 100 + (t * 250);
            const peakHeight = 250; const groundY = 486; const startY = 400;
            state.player.pos.y = startY + (groundY - startY) * t - Math.sin(t * Math.PI) * peakHeight;
            if (state.introTimer >= 80 + jumpDuration) { 
              state.player.pos.y = groundY; state.player.pos.x = baseStartX + 150; state.player.vel = { x: 0, y: 0 }; 
              onIntroComplete(); 
            }
        }
        state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
        return;
    }

    if (status === GameStatus.BOSS_TRANSITION) {
        const targetCameraX = 7200; 
        const targetPlayerX = 7400; 
        const camDiff = targetCameraX - state.camera.x;
        const playerDiff = targetPlayerX - player.pos.x;
        state.camera.x += camDiff * 0.05;
        player.pos.x += playerDiff * 0.05;
        player.pos.y += (486 - player.pos.y) * 0.05;
        player.vel = { x: 0, y: 0 };
        player.facing = 1;
        if (Math.abs(camDiff) < 1 && Math.abs(playerDiff) < 1) {
            state.camera.x = targetCameraX; 
            player.pos.x = targetPlayerX; 
            if (state.doorState === 'open') state.doorState = 'closing';
        }
        if (state.doorState === 'closing') {
          state.doorOpenAmount -= 5;
          if (state.doorOpenAmount <= 0) { 
            state.doorOpenAmount = 0; 
            state.doorState = 'done';
            onBossEncounter(); 
          }
        }
        return;
    }

    if (status !== GameStatus.PLAYING) return;

    if (state.victoryString) {
      state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
      if (state.victoryString.length < 7) {
        state.postVictoryTimer++;
        if (state.postVictoryTimer >= 30) {
            const fullStr = "VICTORY"; state.victoryString += fullStr[state.victoryString.length]; state.postVictoryTimer = 0;
            if (state.victoryString.length === 7) { setTimeout(() => { onBossDefeated(stageId || ""); }, 2000); }
        }
      }
      return; 
    }

    if (state.tsunamiActive) {
      state.tsunamiX += TSUNAMI_WAVE_SPEED * state.tsunamiDir;
      const dist = Math.abs(state.tsunamiX - state.tsunamiStartX);
      const progress = Math.min(1.0, dist / CANVAS_WIDTH);
      const currentTopY = progress * 550;
      const waveWidth = 200;
      if (progress >= 1.0) state.tsunamiActive = false;
      if (state.frame % 3 === 0) {
        state.particles.push({
          pos: { x: state.tsunamiX - (Math.random() * waveWidth * state.tsunamiDir), y: currentTopY + Math.random() * (CANVAS_HEIGHT - currentTopY) },
          vel: { x: -state.tsunamiDir * 2, y: (Math.random() - 0.5) * 4 },
          life: 15 + Math.random() * 15,
          color: Math.random() > 0.5 ? '#00BFFF' : '#FFFFFF',
          size: 4 + Math.random() * 8
        });
      }

      // Tsunami clears mini volcanoes
      state.bossVolcanoes = state.bossVolcanoes.filter(v => {
        const isWithinWaveX = state.tsunamiDir === 1 
          ? (v.pos.x > state.tsunamiX - waveWidth && v.pos.x < state.tsunamiX)
          : (v.pos.x < state.tsunamiX + waveWidth && v.pos.x > state.tsunamiX);
        const isWithinWaveY = v.pos.y + 20 > currentTopY;
        if (isWithinWaveX && isWithinWaveY) {
           spawnExplosion(v.pos, '#00BFFF', 10, 0, 10); // Steam/Water effect
           return false;
        }
        return true;
      });

      state.enemies.forEach(enemy => {
        if (enemy.health > 0 && !enemy.isBlownAway) {
          const isWithinWaveHorizontal = state.tsunamiDir === 1 
              ? (enemy.pos.x + enemy.width > state.tsunamiX - waveWidth && enemy.pos.x < state.tsunamiX)
              : (enemy.pos.x < state.tsunamiX + waveWidth && enemy.pos.x + enemy.width > state.tsunamiX);
          if (isWithinWaveHorizontal && enemy.pos.y + enemy.height > currentTopY) {
            if (enemy.type === 'boss') {
              if (!enemy.hitCooldown || enemy.hitCooldown <= 0) {
                enemy.health -= getBossDamage(enemy, { isTsunami: true });
                enemy.hitCooldown = 40;
                if (enemy.health <= 0) triggerBossDeath(enemy, player.facing, checkIsWeakness({ isTsunami: true }));
              }
            } else {
              enemy.health = 0; enemy.isBlownAway = true;
              enemy.vel = { x: (25 + Math.random() * 10) * state.tsunamiDir, y: -15 - Math.random() * 10 };
              player.killSatisfactionTimer = 60;
            }
          }
        }
      });
    }

    const gamepads = navigator.getGamepads();
    let padMoveX = 0, padMoveY = 0, padJump = false, padSpecial = false, padShoot = false;
    if (gamepads[0]) {
      const gp = gamepads[0]; const DEADZONE = 0.2;
      if (Math.abs(gp.axes[0]) > DEADZONE) padMoveX = gp.axes[0];
      if (Math.abs(gp.axes[1]) > DEADZONE) padMoveY = gp.axes[1];
      if (gp.buttons[14]?.pressed) padMoveX = -1;
      if (gp.buttons[15]?.pressed) padMoveX = 1;
      if (gp.buttons[12]?.pressed) padMoveY = -1;
      if (gp.buttons[13]?.pressed) padMoveY = 1;
      padJump = gp.buttons[0]?.pressed; 
      padShoot = gp.buttons[2]?.pressed || gp.buttons[3]?.pressed; 
      padSpecial = gp.buttons[7]?.pressed; 
    }

    const km = keys.current;
    const isStunned = state.playerStunTimer > 0;
    const hasAmmo = (wpn: WeaponType) => wpn === 'GUN' || player.weaponAmmo[wpn] >= 1;
    const shootRequested = !isStunned && player.pushbackTimer <= 0 && (mouse.current.down || padShoot); 
    const isFiringFlamethrower = currentWeapon === 'FLAMETHROWER' && shootRequested && hasAmmo('FLAMETHROWER');

    const moveLeft = !isStunned && player.pushbackTimer <= 0 && (km['a'] || km['arrowleft'] || km['keya'] || padMoveX < -0.3);
    const moveRight = !isStunned && player.pushbackTimer <= 0 && (km['d'] || km['arrowright'] || km['keyd'] || padMoveX > 0.3);
    const moveDown = !isStunned && player.pushbackTimer <= 0 && (km['s'] || km['arrowdown'] || km['keys'] || padMoveY > 0.3);
    const moveUp = !isStunned && player.pushbackTimer <= 0 && (km['w'] || km['arrowup'] || km['keyw'] || padMoveY < -0.3);
    const jumpRequested = !isStunned && player.pushbackTimer <= 0 && (km[' '] || km['space'] || km['z'] || km['keyz'] || km['j'] || km['keyj'] || padJump);
    const chargeRequested = !isStunned && player.pushbackTimer <= 0 && (km['shift'] || km['shiftleft'] || km['shiftright'] || km['c'] || km['keyc'] || padSpecial);

    if (state.playerStunTimer > 0) state.playerStunTimer--;
    if (state.vulgarityTimer > 0) { state.vulgarityTimer--; if (state.vulgarityTimer <= 0) state.lastVulgarity = ""; }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;
    if (player.killSatisfactionTimer > 0) player.killSatisfactionTimer--;
    if (player.pushbackTimer > 0) { player.pushbackTimer--; player.vel.x *= 0.9; }

    if (player.specialCharges < MAX_SPECIAL_CHARGES) {
      player.specialChargeTimer++;
      if (player.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) { player.specialCharges++; player.specialChargeTimer = 0; }
    }

    if (!jumpRequested) player.jumpInputReleased = true;
    if (!chargeRequested) player.chargeInputReleased = true;

    enemies.forEach(e => {
        if (e.type === 'boss' && e.health > 0 && state.arenaLocked) {
            e.stateTimer = (e.stateTimer || 0) - 1;
            const dirToPlayer = player.pos.x + player.width/2 < e.pos.x + e.width/2 ? -1 : 1;

            if (stageId === 'Hector Hurricane') {
                if (e.bossState === 'hurricane') {
                  const forceX = (e.pos.x + e.width/2 - (player.pos.x + player.width/2)) > 0 ? 18.5 : -18.5;
                  if (!player.isCharging) {
                    player.vel.x += forceX * 0.35; 
                  }

                  projectiles.forEach(p => {
                    if (p.owner === 'player' && p.isBoulder) {
                      const pullDir = (e.pos.x + e.width/2 - (p.pos.x + p.width/2)) > 0 ? 1 : -1;
                      p.vel.x += pullDir * 1.5; 
                    }
                  });

                  if (state.frame % 4 === 0) {
                     projectiles.push({ 
                        id: `debris-${Date.now()}`, pos: { x: e.pos.x + (forceX > 0 ? 400 : -400), y: 100 + Math.random()*400 }, 
                        vel: { x: forceX > 0 ? -14 : 14, y: (Math.random()-0.5)*4 }, width: 20, height: 20, health: 1, maxHealth: 1, 
                        type: 'projectile', damage: 15, owner: 'enemy' 
                     });
                  }
                  const dist = Math.abs((e.pos.x + e.width/2) - (player.pos.x + player.width/2));
                  const stormRadius = 300;
                  if (dist < stormRadius && player.invincibilityTimer <= 0 && !invincibilityEnabled) {
                    player.health -= 8; 
                    player.invincibilityTimer = 25; 
                    player.pushbackTimer = 2;
                  }
                  if (e.stateTimer <= 0) {
                    e.bossState = 'idle';
                    e.stateTimer = 40;
                  }
                } else if (e.bossState === 'jumping') {
                  if (e.isGroundedBoss) {
                    e.bossState = 'hurricane';
                    e.stateTimer = 220; 
                    e.vel.x = 0;
                  }
                } else {
                  if (e.stateTimer <= 0) {
                    e.bossState = 'jumping';
                    e.vel.y = -22 - Math.random() * 4;
                    const targetX = e.pos.x > 7600 ? 7300 : 7900;
                    e.vel.x = (targetX - e.pos.x) * 0.035;
                  }
                }
            } else if (stageId === 'Victor Volcano') {
                if (e.stateTimer <= 0) {
                    if (e.bossState === 'telegraphing') {
                        state.bossVolcanoes = state.bossVolcanoTelegraphs.map(t => ({ ...t, life: 180 }));
                        state.bossVolcanoTelegraphs = [];
                        e.bossState = 'attacking';
                        e.stateTimer = 180;
                    } else if (e.bossState === 'attacking' || e.bossState === 'idle') {
                        if (e.bossState === 'attacking') {
                            e.bossState = 'idle';
                            e.stateTimer = 120; // Attack Cooldown
                        } else {
                            state.bossVolcanoTelegraphs = [
                                { pos: { x: 7200 + Math.random() * 700, y: 530 }, life: 60, type: 'ground' },
                                { pos: { x: Math.random() > 0.5 ? 7210 : 7960, y: 200 + Math.random() * 200 }, life: 60, type: 'wall' }
                            ];
                            e.bossState = 'telegraphing';
                            e.stateTimer = 60; // Telegraph duration
                            e.vel.y = -15; e.vel.x = (player.pos.x - e.pos.x) * 0.02;
                        }
                    }
                }
            } else if (stageId === 'Artie Avalanche') {
                if (e.stateTimer <= 0) {
                    if (Math.random() < 0.3) { 
                        e.vel.y = -20;
                        e.vel.x = (e.pos.x < 7200 + 400 ? 1 : -1) * 8;
                        e.stateTimer = 80;
                    } else { 
                        projectiles.push({ id: `ice-big-${Date.now()}`, pos: { x: e.pos.x + e.width/2, y: 400 }, vel: { x: dirToPlayer * 10, y: 0 }, width: 60, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true });
                        e.stateTimer = 90;
                    }
                }
            } else if (stageId === 'Ernie Earthquake') {
                if (e.stateTimer <= 0) {
                    e.vel.y = -20; 
                    e.vel.x = (player.pos.x - e.pos.x) * 0.03;
                    e.stateTimer = 180; 
                    projectiles.push({ 
                        id: `b-ernie-jump-${Date.now()}`, 
                        pos: { x: e.pos.x + e.width/2, y: e.pos.y + 20 }, 
                        vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, 
                        width: 48, height: 48, health: 1, maxHealth: 1, 
                        type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true 
                    });
                }
            }

            e.vel.y += GRAVITY;
            e.pos.x += e.vel.x;
            const prevY = e.pos.y;
            e.pos.y += e.vel.y;

            e.pos.x = Math.max(7200 + 10, Math.min(8000 - e.width - 10, e.pos.x));
            if (e.pos.y < 100) { e.pos.y = 100; e.vel.y = 0; }
            if (e.pos.y > 470) {
                e.pos.y = 470; 
                if (prevY < 470 && e.vel.y > 0) {
                    if (stageId === 'Ernie Earthquake') {
                        state.screenShakeTimer = 30;
                        if (player.isGrounded && player.pos.x > 7200) {
                            state.playerStunTimer = 50;
                        }
                        projectiles.push({ 
                            id: `b-ernie-land-${Date.now()}`, 
                            pos: { x: e.pos.x + e.width/2, y: e.pos.y + 20 }, 
                            vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, 
                            width: 48, height: 48, health: 1, maxHealth: 1, 
                            type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true 
                        });
                    }
                }
                e.vel.y = 0; e.vel.x = 0; e.isGroundedBoss = true;
            } else {
                e.isGroundedBoss = false;
            }
        }
    });

    state.bossVolcanoes = state.bossVolcanoes.filter(v => {
        v.life--;
        if (state.frame % 10 === 0) {
            const magVelX = v.type === 'wall' ? (v.pos.x < 7600 ? 10 : -10) : (Math.random()-0.5)*4;
            const magVelY = v.type === 'ground' ? -8 : (Math.random()-0.5)*6;
            projectiles.push({ id: `magma-${Date.now()}`, pos: { x: v.pos.x, y: v.pos.y }, vel: { x: magVelX, y: magVelY }, width: 12, height: 12, health: 1, maxHealth: 1, type: 'projectile', damage: 15, owner: 'enemy' });
        }
        return v.life > 0;
    });

    if (state.doorState === 'opening') {
      state.doorOpenAmount += 5; 
      if (state.doorOpenAmount >= 150) {
        state.doorOpenAmount = 150;
        state.doorState = 'open';
        state.enemies = state.enemies.filter(e => e.type === 'boss');
        state.projectiles = state.projectiles.filter(p => p.owner === 'player');
        state.arenaLocked = true;
        onBossTransition();
      }
    }

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting && !isFiringFlamethrower;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging && !player.isUppercutting && player.pushbackTimer <= 0 && state.playerStunTimer <= 0) {
        if (!player.isDucking) {
          const speed = isFiringFlamethrower ? PLAYER_SPEED * FLAMETHROWER_SPEED_MULT : PLAYER_SPEED;
          if (moveLeft) { player.vel.x = -speed; if(!isFiringFlamethrower) player.facing = -1; }
          else if (moveRight) { player.vel.x = speed; if(!isFiringFlamethrower) player.facing = 1; }
          else {
              const frictionVal = (stageId === 'Artie Avalanche' && player.isGrounded) ? 0.98 : FRICTION;
              player.vel.x *= frictionVal;
          }
