        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="animate-in fade-in duration-1000 max-w-xl bg-black/90 p-8 md:p-12 border-4 border-yellow-400 shadow-[0_0_50px_rgba(255,255,0,0.3)]">
