        if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); } 
        else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; } 
        else { ctx.fillStyle = colors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = colors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); } 
    });
    pickups.forEach(p => {
        if (p.type.includes('health')) { ctx.fillStyle = 'red'; const thick = p.type === 'large_health' ? 10 : 5; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); } 
        else { ctx.fillStyle = 'yellow'; const thick = p.type === 'large_ammo' ? 12 : 6; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); }
    });

    state.bossVolcanoTelegraphs.forEach(v => {
       ctx.save();
       ctx.globalCompositeOperation = 'screen';
       ctx.fillStyle = `rgba(255, 100, 0, ${0.3 + Math.sin(state.frame * 0.2) * 0.2})`;
       if (v.type === 'ground') {
           ctx.fillRect(v.pos.x - 40, v.pos.y - 10, 80, 40);
           ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 2; ctx.strokeRect(v.pos.x - 40, v.pos.y - 10, 80, 40);
       } else {
           ctx.fillRect(v.pos.x - 10, v.pos.y - 40, 40, 80);
           ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 2; ctx.strokeRect(v.pos.x - 10, v.pos.y - 40, 40, 80);
       }
       ctx.restore();
    });

    state.bossVolcanoes.forEach(v => { ctx.save(); ctx.fillStyle = '#FF4500'; if (v.type === 'ground') ctx.fillRect(v.pos.x - 20, v.pos.y, 40, 20); else ctx.fillRect(v.pos.x, v.pos.y - 20, 20, 40); ctx.restore(); });
    enemies.forEach(e => {
      if (e.health <= 0 && !e.isBlownAway) return;
      ctx.save();
      if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
      else if (e.type === 'boss' && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }
      if (e.type === 'boss') { 
        if (e.bossState === 'hurricane') {
          ctx.save();
          const centerX = e.pos.x + e.width/2;
          const centerY = e.pos.y + e.height/2;
          const gradient = ctx.createRadialGradient(centerX, centerY, 50, centerX, centerY, 300);
          gradient.addColorStop(0, 'rgba(100, 100, 150, 0.4)');
          gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
          ctx.fillStyle = gradient;
          ctx.beginPath(); ctx.arc(centerX, centerY, 300, 0, Math.PI * 2); ctx.fill();
          ctx.strokeStyle = 'rgba(174, 214, 241, 0.6)';
          ctx.lineWidth = 1.5;
          for(let i=0; i<30; i++) {
             const rx = (Math.random()-0.5)*600;
             const ry = (Math.random()-0.5)*600;
             if (Math.sqrt(rx*rx + ry*ry) < 300) {
               ctx.beginPath();
               ctx.moveTo(centerX + rx, centerY + ry);
               ctx.lineTo(centerX + rx - 5, centerY + ry + 15);
               ctx.stroke();
             }
          }
          if (state.frame % 15 < 3) {
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath();
            let lx = centerX + (Math.random()-0.5)*400;
            let ly = centerY - 300;
            ctx.moveTo(lx, ly);
            for(let j=0; j<5; j++) {
              lx += (Math.random()-0.5)*100;
              ly += 60;
              ctx.lineTo(lx, ly);
            }
            ctx.stroke();
          }
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)'; ctx.lineWidth = 3;
          for(let i=0; i<6; i++) {
             ctx.beginPath();
             const rot = (state.frame * 0.15) + (i * Math.PI * 0.33);
             ctx.arc(centerX, centerY, 80 + i * 35, rot, rot + 1.2);
             ctx.stroke();
          }
          ctx.restore();
        }
        drawBossSprite(ctx, e, stageId); 
      } 
      else { 
        if (e.enemyType === 'shield') { 
          // Draw Body
          ctx.fillStyle = '#444';
          ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height);
          // Draw Shield
          if (e.isShieldActive) {
            ctx.fillStyle = '#2C3E50'; // Dark Metal
            ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
            ctx.strokeStyle = '#00FFFF'; // Active cyan highlight
            ctx.lineWidth = 2;
            ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
            // Detail lines on shield
            ctx.beginPath();
            ctx.moveTo(e.pos.x + 4, e.pos.y + 10);
            ctx.lineTo(e.pos.x + 4, e.pos.y + e.height - 10);
            ctx.stroke();
          } else {
            // Retracted shield look
            ctx.fillStyle = '#7F8C8D';
            ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20);
          }
        } else if (e.id.startsWith('rusher')) {
          // Rushdown enemy is purple
          ctx.fillStyle = '#9B59B6'; 
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          // Add some "rush" details
          ctx.fillStyle = 'white';
          ctx.fillRect(e.pos.x + (e.vel.x > 0 ? e.width - 10 : 0), e.pos.y + 10, 10, 5);
        } else if (e.enemyType === 'flyer' && e.width > 60) {
            // Heavy Flying Gunship Visuals
            ctx.fillStyle = '#34495E'; // Metallic dark blue/grey
            ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30); // Body
            ctx.fillStyle = '#2ECC71'; // Engine glow
            ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 15, 10);
            ctx.fillRect(e.pos.x + e.width - 20, e.pos.y + 10, 15, 10);
            ctx.fillStyle = '#E74C3C'; // Sensor/Eye
            ctx.fillRect(e.pos.x + e.width/2 - 10, e.pos.y + 25, 20, 8);
            // Turret underneath
            ctx.fillStyle = '#1C2833';
            ctx.fillRect(e.pos.x + e.width/2 - 5, e.pos.y + e.height - 15, 10, 15);
        } else { 
          ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); 
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); 
        } 
      }
      if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
      if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
      ctx.restore();
    });
    if (status !== GameStatus.LEVEL_INTRO || gameStateRef.current.introTimer >= 80) drawPlayer(ctx, player);
    projectiles.forEach(p => { 
        if (p.isBoulder) { 
            ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); 
            ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = 'black'; ctx.stroke(); ctx.restore(); 
        } else { 
            ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); 
            ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); 
            if (p.isIce) { ctx.strokeStyle = 'white'; ctx.lineWidth = 1; ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height); }
        } 
    });
    particles.forEach(p => { 
      if (p.isWater) {
        ctx.save();
        ctx.globalAlpha = p.life < 10 ? p.life / 10 : 1.0;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.pos.x, p.pos.y, p.size / 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      } else {
        ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; 
        ctx.fillStyle = p.color; 
        ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); 
      }
    });
    ctx.restore();
    if (state.victoryString) { ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); }
    if (state.deathTimer > 0) { ctx.save(); ctx.font = 'bold 60px "Press Start 2P"'; ctx.fillStyle = '#FF0000'; ctx.textAlign = 'center'; ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
  }, [status, stageId, currentWeapon, invincibilityEnabled, jumpToBossEnabled]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        // Correct order: cleanup arrays BEFORE calling createLevel
        gameStateRef.current.particles = [];
        gameStateRef.current.projectiles = [];
        gameStateRef.current.pickups = [];
        gameStateRef.current.enemies = []; 

        createLevel();

        const baseStartX = jumpToBossEnabled ? BOSS_DOOR_X - 800 : 0;
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: baseStartX + 150, y: 400 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, specialCharges: MAX_SPECIAL_CHARGES, specialChargeTimer: 0, pushbackTimer: 0, facing: 1, isCharging: false, isUppercutting: false, isDucking: false, jumpPrepTimer: 0, invincibilityTimer: 0, killSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true, currentWeapon: 'GUN', weaponAmmo: { ...initialAmmo } };
        gameStateRef.current.camera.x = baseStartX;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.victoryString = ""; gameStateRef.current.introTimer = 0; gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.tsunamiActive = false; gameStateRef.current.deathTimer = 0; gameStateRef.current.deathString = ""; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.bossVolcanoes = []; gameStateRef.current.bossVolcanoTelegraphs = []; gameStateRef.current.bossTsunamiSide = 0; gameStateRef.current.playerStunTimer = 0;
        gameStateRef.current.screenShakeTimer = 0;

        gameStateRef.current.frame = 1;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { 
      // Cleanup arrays when in Menu/Stage Select to prevent ghost entities
      gameStateRef.current.particles = [];
      gameStateRef.current.projectiles = [];
      gameStateRef.current.pickups = [];
      gameStateRef.current.enemies = [];
      draw(); 
      gameStateRef.current.frame = 0; 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

