      ctx.save();
      if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
      else if (e.type === 'boss' && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }
      if (e.type === 'boss') { 
        if (e.bossState === 'hurricane') {
          ctx.save();
          const centerX = e.pos.x + e.width/2;
          const centerY = e.pos.y + e.height/2;
          const gradient = ctx.createRadialGradient(centerX, centerY, 50, centerX, centerY, 300);
          gradient.addColorStop(0, 'rgba(100, 100, 150, 0.4)');
          gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
          ctx.fillStyle = gradient;
          ctx.beginPath(); ctx.arc(centerX, centerY, 300, 0, Math.PI * 2); ctx.fill();
          ctx.strokeStyle = 'rgba(174, 214, 241, 0.6)';
          ctx.lineWidth = 1.5;
          for(let i=0; i<30; i++) {
             const rx = (Math.random()-0.5)*600;
             const ry = (Math.random()-0.5)*600;
             if (Math.sqrt(rx*rx + ry*ry) < 300) {
               ctx.beginPath();
               ctx.moveTo(centerX + rx, centerY + ry);
               ctx.lineTo(centerX + rx - 5, centerY + ry + 15);
               ctx.stroke();
             }
          }
          if (state.frame % 15 < 3) {
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath();
            let lx = centerX + (Math.random()-0.5)*400;
            let ly = centerY - 300;
            ctx.moveTo(lx, ly);
            for(let j=0; j<5; j++) {
              lx += (Math.random()-0.5)*100;
              ly += 60;
              ctx.lineTo(lx, ly);
            }
            ctx.stroke();
          }
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)'; ctx.lineWidth = 3;
          for(let i=0; i<6; i++) {
             ctx.beginPath();
             const rot = (state.frame * 0.15) + (i * Math.PI * 0.33);
             ctx.arc(centerX, centerY, 80 + i * 35, rot, rot + 1.2);
             ctx.stroke();
          }
          ctx.restore();
        }
        drawBossSprite(ctx, e, stageId); 
      } 
      else { 
        if (e.enemyType === 'shield') { 
          // Draw Body
          ctx.fillStyle = '#444';
          ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height);
          // Draw Shield
          if (e.isShieldActive) {
            ctx.fillStyle = '#2C3E50'; // Dark Metal
            ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
            ctx.strokeStyle = '#00FFFF'; // Active cyan highlight
            ctx.lineWidth = 2;
            ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
            // Detail lines on shield
            ctx.beginPath();
            ctx.moveTo(e.pos.x + 4, e.pos.y + 10);
            ctx.lineTo(e.pos.x + 4, e.pos.y + e.height - 10);
            ctx.stroke();
          } else {
            // Retracted shield look
            ctx.fillStyle = '#7F8C8D';
            ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20);
          }
        } else if (e.id.startsWith('rusher')) {
          // Rushdown enemy is purple
          ctx.fillStyle = '#9B59B6'; 
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
          // Add some "rush" details
          ctx.fillStyle = 'white';
          ctx.fillRect(e.pos.x + (e.vel.x > 0 ? e.width - 10 : 0), e.pos.y + 10, 10, 5);

          // Visual feedback for "waiting patiently" vs chasing
          const yDiff = Math.abs((player.pos.y + player.height/2) - (e.pos.y + e.height/2));
          if (yDiff >= 80 && (!e.pauseTimer || e.pauseTimer <= 0)) {
            ctx.fillStyle = 'rgba(255, 255, 255, 0.2)';
            ctx.font = '10px monospace';
            ctx.fillText('...', e.pos.x + e.width/2 - 10, e.pos.y - 15);
          }
        } else if (e.enemyType === 'flyer' && e.width > 60) {
            // Heavy Flying Gunship Visuals
            ctx.fillStyle = '#34495E'; // Metallic dark blue/grey
            ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30); // Body
            ctx.fillStyle = '#2ECC71'; // Engine glow
            ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 15, 10);
            ctx.fillRect(e.pos.x + e.width - 20, e.pos.y + 10, 15, 10);
            ctx.fillStyle = '#E74C3C'; // Sensor/Eye
            ctx.fillRect(e.pos.x + e.width/2 - 10, e.pos.y + 25, 20, 8);
            // Turret underneath
            ctx.fillStyle = '#1C2833';
            ctx.fillRect(e.pos.x + e.width/2 - 5, e.pos.y + e.height - 15, 10, 15);
        } else { 
          ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); 
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); 
        } 
      }
      if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
      if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
      ctx.restore();
    });
    if (status !== GameStatus.LEVEL_INTRO || gameStateRef.current.introTimer >= 80) drawPlayer(ctx, player);
    projectiles.forEach(p => { 
        if (p.isBoulder) { 
            ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); 
            ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = 'black'; ctx.stroke(); ctx.restore(); 
        } else { 
            ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); 
            ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); 
            if (p.isIce) { ctx.strokeStyle = 'white'; ctx.lineWidth = 1; ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height); }
        } 
    });
    particles.forEach(p => { 
      if (p.isWater) {
        ctx.save();
        ctx.globalAlpha = p.life < 10 ? p.life / 10 : 1.0;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.pos.x, p.pos.y, p.size / 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      } else {
        ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; 
        ctx.fillStyle = p.color; 
        ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); 
      }
    });
    ctx.restore();
    if (state.victoryString) { ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); }
    if (state.deathTimer > 0) { ctx.save(); ctx.font = 'bold 60px "Press Start 2P"'; ctx.fillStyle = '#FF0000'; ctx.textAlign = 'center'; ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
  }, [status, stageId, currentWeapon, invincibilityEnabled, jumpToBossEnabled]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        // Correct order: cleanup arrays BEFORE calling createLevel
        gameStateRef.current.particles = [];
        gameStateRef.current.projectiles = [];
        gameStateRef.current.pickups = [];
        gameStateRef.current.enemies = []; 

        createLevel();

        const baseStartX = jumpToBossEnabled ? BOSS_DOOR_X - 800 : 0;
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: baseStartX + 150, y: 400 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, specialCharges: MAX_SPECIAL_CHARGES, specialChargeTimer: 0, pushbackTimer: 0, facing: 1, isCharging: false, isUppercutting: false, isDucking: false, jumpPrepTimer: 0, invincibilityTimer: 0, killSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true, currentWeapon: 'GUN', weaponAmmo: { ...initialAmmo } };
        gameStateRef.current.camera.x = baseStartX;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.victoryString = ""; gameStateRef.current.introTimer = 0; gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.tsunamiActive = false; gameStateRef.current.deathTimer = 0; gameStateRef.current.deathString = ""; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.bossVolcanoes = []; gameStateRef.current.bossVolcanoTelegraphs = []; gameStateRef.current.bossTsunamiSide = 0; gameStateRef.current.playerStunTimer = 0;
        gameStateRef.current.screenShakeTimer = 0;

        gameStateRef.current.frame = 1;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { 
      // Cleanup arrays when in Menu/Stage Select to prevent ghost entities
      gameStateRef.current.particles = [];
      gameStateRef.current.projectiles = [];
      gameStateRef.current.pickups = [];
      gameStateRef.current.enemies = [];
      draw(); 
      gameStateRef.current.frame = 0; 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

export const playGlassShatterSound = (audioCtx: AudioContext | null) => {
  if (!audioCtx) return;
  try {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    for(let i=0; i<12; i++) {
      const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
      osc.type = i % 2 === 0 ? 'sine' : 'sawtooth';
      osc.frequency.setValueAtTime(1200 + Math.random() * 5000, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(100, audioCtx.currentTime + 0.3);
      gain.gain.setValueAtTime(0.1, audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.3);
      osc.connect(gain); gain.connect(audioCtx.destination);
      osc.start(); osc.stop(audioCtx.currentTime + 0.3);
    }
  } catch (e) {}
};

export const playGunSound = (audioCtx: AudioContext | null, type: 'gun' | 'ice' | 'flame' | 'tsunami' = 'gun') => {
  if (!audioCtx) return;
  try {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
    if (type === 'gun') {
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(150, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, audioCtx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);
    } else if (type === 'ice') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(800, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(1200, audioCtx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.08, audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.15);
    } else if (type === 'flame') {
      osc.type = 'triangle'; osc.frequency.setValueAtTime(40 + Math.random() * 40, audioCtx.currentTime);
      osc.frequency.linearRampToValueAtTime(120, audioCtx.currentTime + 0.05);
      gain.gain.setValueAtTime(0.03, audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.05);
    } else if (type === 'tsunami') {
        const bufferSize = audioCtx.sampleRate * 0.5; 
        const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
        const noise = audioCtx.createBufferSource();
        noise.buffer = buffer;
        const filter = audioCtx.createBiquadFilter();
        filter.type = 'lowpass'; filter.frequency.setValueAtTime(1000, audioCtx.currentTime); filter.frequency.exponentialRampToValueAtTime(100, audioCtx.currentTime + 0.5);
        noise.connect(filter); filter.connect(audioCtx.destination);
        noise.start();
        return;
    }
    osc.connect(gain); gain.connect(audioCtx.destination);
    osc.start(); osc.stop(audioCtx.currentTime + 0.1);
  } catch (e) {}
};

import { Vector2, PickupType, Enemy, WeaponType } from '../types';
import { BOSS_DOOR_X, DOOR_WIDTH, MAX_AMMO, AMMO_PICKUP_PCT } from '../constants';
import { 
  GUN_KILL_VULGARITIES, BOULDER_KILL_VULGARITIES, SHOTGUN_KILL_VULGARITIES, 
  FLAMETHROWER_KILL_VULGARITIES, TSUNAMI_KILL_VULGARITIES, CHARGE_KILL_VULGARITIES, 
  UPPERCUT_KILL_VULGARITIES, HURT_VULGARITIES, DEATH_VULGARITIES, INTRO_QUOTES
} from './vulgarities';
import { playGlassShatterSound } from './audio';

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02'];
const FLESH_COLORS = ['#f1c27d', '#e0ac69', '#d2b48c', '#8b4513'];
const ROCK_COLORS = ['#4E342E', '#3E2723', '#212121', '#757575'];

export type VulgarityType = 'gun_kill' | 'boulder_kill' | 'shotgun_kill' | 'flamethrower_kill' | 'tsunami_kill' | 'hurt' | 'death' | 'charge_kill' | 'uppercut_kill';

export const spawnExplosion = (state: any, pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15, isGlass: boolean = false) => {
  for (let i = 0; i < count; i++) {
    if (state.particles.length > 800) break;
    state.particles.push({
      pos: { ...pos },
      vel: { 
        x: baseVelX + (Math.random() - 0.5) * spread, 
        y: (Math.random() - 0.5) * spread 
      },
      life: isGlass ? 150 + Math.random() * 200 : 20 + Math.random() * 80,
      color: color,
      size: isGlass ? 1 + Math.random() * 4 : 2 + Math.random() * 12,
      isGlass
    });
  }
};

export const spawnDeathShower = (state: any, pos: Vector2, facing: number = 0, multiplier: number = 1) => {
  FLESH_COLORS.forEach(c => spawnExplosion(state, pos, c, Math.ceil(8 * multiplier), facing * 18, 25));
  GORE_COLORS.forEach(c => spawnExplosion(state, pos, c, Math.ceil(12 * multiplier), facing * 22, 35));
  spawnExplosion(state, pos, '#FF4500', Math.ceil(10 * multiplier), facing * 12, 40);
  spawnExplosion(state, pos, '#FFFF00', Math.ceil(5 * multiplier), facing * 8, 30);
};

export const spawnRockShatter = (state: any, pos: Vector2) => {
  ROCK_COLORS.forEach(c => spawnExplosion(state, pos, c, 8, 0, 20));
};

export const spawnGlassShatter = (state: any, audioCtx: AudioContext | null, pos: Vector2) => {
  const GLASS_COLORS = ['#ADD8E6', '#F0F8FF', '#FFFFFF', '#B0C4DE'];
  GLASS_COLORS.forEach(c => spawnExplosion(state, pos, c, 5, 0, 25, true));
  playGlassShatterSound(audioCtx);
};

export const spawnPickup = (state: any, pos: Vector2) => {
  const r = Math.random();
  if (r < 0.6) {
    const pr = Math.random();
    let type: PickupType;
    if (pr < 0.25) type = 'small_health';
    else if (pr < 0.35) type = 'large_health';
    else if (pr < 0.8) type = 'small_ammo';
    else type = 'large_ammo';
    state.pickups.push({
      id: `pickup-${Date.now()}-${Math.random()}`,
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -5 },
      width: 20, height: 20, type, life: 600
    });
  }
};

export const speakVulgarity = (state: any, category: VulgarityType) => {
  if (state.voiceLineCooldown > 0 && category !== 'death') return;
  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel(); 
    let pool = GUN_KILL_VULGARITIES;
    if (category === 'hurt') pool = HURT_VULGARITIES;
    if (category === 'death') pool = DEATH_VULGARITIES;
    if (category === 'charge_kill') pool = CHARGE_KILL_VULGARITIES;
    if (category === 'uppercut_kill') pool = UPPERCUT_KILL_VULGARITIES;
    if (category === 'boulder_kill') pool = BOULDER_KILL_VULGARITIES;
    if (category === 'shotgun_kill') pool = SHOTGUN_KILL_VULGARITIES;
    if (category === 'flamethrower_kill') pool = FLAMETHROWER_KILL_VULGARITIES;
    if (category === 'tsunami_kill') pool = TSUNAMI_KILL_VULGARITIES;

    const text = pool[Math.floor(Math.random() * pool.length)];
    state.lastVulgarity = text;
    state.vulgarityTimer = 120;
    state.voiceLineCooldown = 90;
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
    window.speechSynthesis.speak(utterance);
  }
};

export const speakIntroLine = (state: any, id: string | null) => {
  if (!id || !INTRO_QUOTES[id]) return;
  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(INTRO_QUOTES[id]);
    utterance.pitch = 0.1; utterance.rate = 1.0; utterance.volume = 1.0;
    window.speechSynthesis.speak(utterance);
    state.lastVulgarity = INTRO_QUOTES[id];
    state.vulgarityTimer = 180;
  }
};

