export const updateEnemies = (state: any, invincibilityEnabled: boolean) => {
  const { player, camera, stageId, arenaLocked, frame } = state;
  state.enemies = state.enemies.filter((enemy: any) => {
    if (enemy.isBlownAway) { enemy.pos.x += enemy.vel.x; enemy.pos.y += enemy.vel.y; enemy.vel.y += GRAVITY * 0.5; enemy.rotation = (enemy.rotation || 0) + 0.3; return enemy.pos.y < 1000; }
    if (enemy.health <= 0) return false; 
    if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
    if (enemy.frozenTimer && enemy.frozenTimer > 0) { enemy.frozenTimer--; return true; } 
    const onScreen = enemy.pos.x + enemy.width > camera.x && enemy.pos.x < camera.x + CANVAS_WIDTH;

    if (enemy.enemyType === 'flyer') enemy.pos.y += Math.sin((frame + (enemy.initialX || 0)) / 25) * 1.2;

    if (enemy.type !== 'boss') {
      if (enemy.id.startsWith('rusher')) {
          if (enemy.pauseTimer && enemy.pauseTimer > 0) { enemy.pauseTimer--; enemy.vel.x *= 0.92; } 
          else {
              const yDiff = Math.abs((player.pos.y + player.height/2) - (enemy.pos.y + enemy.height/2));
              if (onScreen && player.invincibilityTimer <= 0 && yDiff < 80) enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 6; 
              else enemy.vel.x = 0;
          }
      } else if (enemy.behavior === 'patrol') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; } 
      else if (enemy.behavior === 'fly') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; } 
      else if (enemy.behavior === 'shoot' && onScreen) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) { state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0; }
        } else if (enemy.shootTimer > 60) {
            const projY = enemy.enemyType === 'flyer' ? enemy.pos.y + enemy.height - 10 : enemy.pos.y + 20;
            state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width/2, y: projY }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0;
        }
      }
      enemy.pos.x += enemy.vel.x;
    }

    let hbW = player.width, hbH = player.height, hbX = player.pos.x, hbY = player.pos.y;
    if (player.isCharging) { hbW = player.width + 10; hbH = player.height - 10; }
    else if (player.isUppercutting) { hbW = player.width - 15; hbH = player.height + 40; hbY = player.pos.y - 30; hbX = player.pos.x + 7.5; }
    const chargeHit = (player.isCharging || player.isUppercutting) && hbX < enemy.pos.x + enemy.width && hbX + hbW > enemy.pos.x && hbY < enemy.pos.y + enemy.height && hbY + hbH > enemy.pos.y;

    if (chargeHit && onScreen && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
      const damage = player.isUppercutting ? BOSS_UPPERCUT_DAMAGE : BOSS_CHARGE_DAMAGE;
      enemy.health -= damage; enemy.hitCooldown = 60; 
      if (enemy.health > 0) { 
        if (enemy.id.startsWith('rusher')) { enemy.vel.x = player.facing * 15; enemy.pauseTimer = 120; } 
        else { enemy.vel.x = 0; enemy.vel.y = 0; }
        player.vel = { x: -player.facing * 18, y: -4 }; player.pushbackTimer = 20; player.isCharging = false; player.isUppercutting = false; player.invincibilityTimer = 30; 
      } else {
          if (enemy.type === 'boss') triggerBossDeath(state, enemy, player.facing, false);
          else { 
              enemy.isBlownAway = true; enemy.vel = { x: player.isUppercutting ? 0 : player.facing * 30, y: player.isUppercutting ? -30 : -5 };
              spawnDeathShower(state, enemy.pos, player.facing); spawnPickup(state, enemy.pos); speakVulgarity(state, player.isUppercutting ? 'uppercut_kill' : 'charge_kill'); player.killSatisfactionTimer = 60; 
          }
          return false;
      }
    } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x && player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
        if (!invincibilityEnabled) player.health -= 15;
        player.invincibilityTimer = 60; speakVulgarity(state, 'hurt');
        if (enemy.id.startsWith('rusher') || (enemy.type === 'boss' && state.arenaLocked)) {
            if (enemy.id.startsWith('rusher')) enemy.pauseTimer = 60;
            player.pushbackTimer = 30; player.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 20; player.vel.y = -8;
        }
    }
    return true;
  });
};

export const drawBossSprite = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null) => {
    const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
    if (e.rotation) { ctx.translate(width / 2, height / 2); ctx.rotate(e.rotation); ctx.translate(-width / 2, -height / 2); }
    switch (id) {
      case 'Artie Avalanche':
          ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
          ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
      case 'Victor Volcano':
          ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
          ctx.fillStyle = '#8b4513'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.3, 0, Math.PI * 2); ctx.fill(); break;
      case 'Ernie Earthquake':
          ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7);
          ctx.fillStyle = '#e0ac69'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
      case 'Hector Hurricane':
          ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7);
          ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
    }
    ctx.restore();
};

export const drawEnemy = (ctx: CanvasRenderingContext2D, e: any, state: any) => {
  if (e.health <= 0 && !e.isBlownAway) return;
  ctx.save();
  if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
  else if (e.type === 'boss' && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }

  if (e.type === 'boss') drawBossSprite(ctx, e, state.stageId); 
  else { 
    if (e.enemyType === 'shield') { 
      ctx.fillStyle = '#444'; ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height);
      if (e.isShieldActive) { ctx.fillStyle = '#2C3E50'; ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); ctx.strokeStyle = '#00FFFF'; ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); } 
      else { ctx.fillStyle = '#7F8C8D'; ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20); }
    } else if (e.id.startsWith('rusher')) {
      ctx.fillStyle = '#9B59B6'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      const yDiff = Math.abs((state.player.pos.y + state.player.height/2) - (e.pos.y + e.height/2));
      if (yDiff >= 80 && (!e.pauseTimer || e.pauseTimer <= 0)) { ctx.fillStyle = 'rgba(255, 255, 255, 0.2)'; ctx.font = '10px monospace'; ctx.fillText('...', e.pos.x + e.width/2 - 10, e.pos.y - 15); }
    } else if (e.enemyType === 'flyer' && e.width > 60) {
        ctx.fillStyle = '#34495E'; ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30);
        ctx.fillStyle = '#E74C3C'; ctx.fillRect(e.pos.x + e.width/2 - 10, e.pos.y + 25, 20, 8);
    } else { 
      ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); 
      ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); 
    } 
  }
  if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
  if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
  ctx.restore();
};

import { Player, WeaponType, Projectile, Vector2 } from '../types';
import { 
  COLORS, PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_ACCEL, UPPERCUT_FORCE, 
  CHARGE_DURATION, GRAVITY, FRICTION, BULLET_DAMAGE, BOULDER_SPEED, BOULDER_DAMAGE, 
  SHOTGUN_COOLDOWN, SHOTGUN_DAMAGE, FLAMETHROWER_SPEED_MULT, FLAMETHROWER_RANGE, FLAMETHROWER_DAMAGE, 
  TSUNAMI_COOLDOWN, CANVAS_WIDTH, JUMP_PREP_FRAMES, MAX_AMMO, INITIAL_PLAYER_HEALTH, MAX_SPECIAL_CHARGES,
  SPECIAL_CHARGE_REGEN_FRAMES
} from '../constants';
import { playGunSound } from './audio';
import { spawnDeathShower, spawnPickup, speakVulgarity } from './systems';

export const updatePlayer = (state: any, controls: any, audioCtx: AudioContext | null, infiniteAmmoEnabled: boolean, invincibilityEnabled: boolean) => {
  const { player } = state;
  const { moveLeft, moveRight, moveUp, moveDown, jumpRequested, chargeRequested, shootRequested, currentWeapon, isFiringFlamethrower } = controls;

  // Track input releases to prevent auto-jump/auto-charge
  if (!jumpRequested) player.jumpInputReleased = true;
  if (!chargeRequested) player.chargeInputReleased = true;

  // Handle Timers
  if (player.invincibilityTimer > 0) player.invincibilityTimer--;
  if (player.pushbackTimer > 0) player.pushbackTimer--;
  if (player.killSatisfactionTimer > 0) player.killSatisfactionTimer--;
  if (state.playerStunTimer > 0) state.playerStunTimer--;

  // Special Charge Regeneration
  if (player.specialCharges < MAX_SPECIAL_CHARGES) {
    player.specialChargeTimer++;
    if (player.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) {
      player.specialCharges++;
      player.specialChargeTimer = 0;
    }
  } else {
    player.specialChargeTimer = 0;
  }

  player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting && !isFiringFlamethrower;

  if (player.jumpPrepTimer > 0) {
    player.jumpPrepTimer--;
    if (player.jumpPrepTimer === 0) { 
      player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; 
      player.isGrounded = false; 
    }
  } else {
    // Movement logic - only blocked if currently in a hard stun or pushback
    if (!player.isCharging && !player.isUppercutting && player.pushbackTimer <= 0 && state.playerStunTimer <= 0) {
      if (!player.isDucking) {
        const speed = isFiringFlamethrower ? PLAYER_SPEED * FLAMETHROWER_SPEED_MULT : PLAYER_SPEED;
        if (moveLeft) { 
          player.vel.x = -speed; 
          if(!isFiringFlamethrower) player.facing = -1; 
        }
        else if (moveRight) { 
          player.vel.x = speed; 
          if(!isFiringFlamethrower) player.facing = 1; 
        }
        else {
            const frictionVal = (state.stageId === 'Artie Avalanche' && player.isGrounded) ? 0.98 : FRICTION;
            player.vel.x *= frictionVal;
        }
      } else {
        player.vel.x *= FRICTION;
      }

      if (jumpRequested && player.isGrounded && player.jumpInputReleased) { 
        player.jumpPrepTimer = JUMP_PREP_FRAMES; 
        player.jumpInputReleased = false; 
      }
    } else if (player.isCharging) {
      player.chargeDuration--; 
      player.vel.x += player.facing * CHARGE_ACCEL;
      if (Math.abs(player.vel.x) > CHARGE_SPEED) player.vel.x = player.facing * CHARGE_SPEED;
      if (player.chargeDuration <= 0) { 
        player.isCharging = false; 
        player.vel.x = player.facing * PLAYER_SPEED; 
      }
    } else if (player.isUppercutting) {
      player.chargeDuration--;
      if (player.chargeDuration <= 0) player.isUppercutting = false;
    }

    // Skill Triggering
    if (chargeRequested && player.chargeInputReleased && !player.isCharging && !player.isUppercutting && !player.isDucking && player.specialCharges > 0 && !isFiringFlamethrower && state.playerStunTimer <= 0) {
      player.chargeInputReleased = false; 
      player.specialCharges--; 
      player.chargeDuration = CHARGE_DURATION;
      if (moveUp) { 
        player.isUppercutting = true; 
        player.vel.y = UPPERCUT_FORCE; 
        player.isGrounded = false; 
      } 
      else { 
        player.isCharging = true; 
        player.vel.x = player.facing * 5; 
      }
    }

    // Weapon Firing
    if (shootRequested && player.shootCooldown <= 0 && (player.currentWeapon === 'GUN' || player.weaponAmmo[player.currentWeapon] >= 1)) {
      if (player.currentWeapon === 'GUN') {
        state.projectiles.push({ id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 }, width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' });
        player.shootCooldown = 12; playGunSound(audioCtx, 'gun');
      } else if (player.currentWeapon === 'BOULDER') {
        if (!state.projectiles.some((p: Projectile) => p.owner === 'player' && p.isBoulder)) {
          state.projectiles.push({ id: `b-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -40), y: player.pos.y + 20 }, vel: { x: player.facing * BOULDER_SPEED, y: 0 }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true });
          player.shootCooldown = 40; if (!infiniteAmmoEnabled) player.weaponAmmo['BOULDER']--;
        }
      } else if (player.currentWeapon === 'SHOTGUN') {
        for (let i = 0; i < 7; i++) {
          const angle = (i - 3) * 0.15; const speed = 11 + Math.random() * 6;
          state.projectiles.push({ id: `pellet-${Date.now()}-${i}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: Math.cos(angle) * player.facing * speed, y: Math.sin(angle) * speed }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true });
        }
        player.shootCooldown = SHOTGUN_COOLDOWN; playGunSound(audioCtx, 'ice'); if (!infiniteAmmoEnabled) player.weaponAmmo['SHOTGUN']--;
      } else if (player.currentWeapon === 'FLAMETHROWER') {
          if (state.frame % 2 === 0) {
              if (!infiniteAmmoEnabled) player.weaponAmmo['FLAMETHROWER']--; 
              playGunSound(audioCtx, 'flame');
              const FIRE_COLORS = ['#FF4500', '#FF8C00', '#FFA500', '#FFD700', '#FF0000'];
              for (let i = 0; i < 6; i++) {
                  const angle = (Math.random() - 0.5) * 0.6; const speed = 8 + Math.random() * 8;
                  const flameColor = FIRE_COLORS[Math.floor(Math.random() * FIRE_COLORS.length)];
                  state.particles.push({ pos: { x: player.pos.x + (player.facing === 1 ? player.width - 5 : 5), y: player.pos.y + 30 }, vel: { x: Math.cos(angle) * player.facing * speed + player.vel.x, y: Math.sin(angle) * speed }, life: 15 + Math.random() * 20, color: flameColor, size: 8 + Math.random() * 12 });
              }
              const fRect = { x: player.facing === 1 ? player.pos.x + player.width : player.pos.x - FLAMETHROWER_RANGE, y: player.pos.y + 10, w: FLAMETHROWER_RANGE, h: 50 };
              state.projectiles.forEach((p: Projectile) => {
                  if (p.owner === 'enemy' && p.pos.x < fRect.x + fRect.w && p.pos.x + p.width > fRect.x && p.pos.y < fRect.y + fRect.h && p.pos.y + p.height > fRect.y) {
                      p.health = 0;
                  }
              });
              state.enemies.forEach((enemy: any) => {
                  if (enemy.health > 0 && !enemy.isBlownAway) {
                      if (enemy.pos.x < fRect.x + fRect.w && enemy.pos.x + enemy.width > fRect.x && enemy.pos.y < fRect.y + fRect.h && enemy.pos.y + enemy.height > fRect.y) {
                          if (enemy.type === 'boss') {
                              if (!enemy.hitCooldown || enemy.hitCooldown <= 0) {
                                  enemy.health -= 15; enemy.hitCooldown = 60; // Base flamethrower boss dmg
                              }
                          } else {
                              enemy.health -= FLAMETHROWER_DAMAGE;
                              if (enemy.health <= 0) { 
                                spawnDeathShower(state, enemy.pos, player.facing); 
                                spawnPickup(state, enemy.pos); 
                                speakVulgarity(state, 'flamethrower_kill'); 
                                player.killSatisfactionTimer = 60; 
                              }
                          }
                      }
                  }
              });
          }
      } else if (player.currentWeapon === 'TSUNAMI') {
          if (!state.tsunamiActive) {
              state.tsunamiActive = true; 
              state.tsunamiDir = player.facing; 
              state.tsunamiStartX = player.facing === 1 ? state.camera.x : state.camera.x + CANVAS_WIDTH; 
              state.tsunamiX = state.tsunamiStartX; 
              player.shootCooldown = TSUNAMI_COOLDOWN; 
              playGunSound(audioCtx, 'tsunami'); 
              if (!infiniteAmmoEnabled) player.weaponAmmo['TSUNAMI']--;
          }
      }
    }
  }

  if (player.shootCooldown > 0) player.shootCooldown--;
  player.vel.y += GRAVITY;
  if (!jumpRequested && player.vel.y < 0 && !player.isGrounded && !player.isCharging && !player.isUppercutting) player.vel.y *= 0.5;

  if (state.playerStunTimer > 0) player.pos.y += (state.frame % 2 === 0 ? -2 : 2);

  player.pos.x += player.vel.x; player.pos.y += player.vel.y;
  if (player.pos.x < 50) player.pos.x = 50;

  player.isGrounded = false;
  state.blocks.forEach((block: any) => {
    if (block.type === 'door' && (state.doorState === 'opening' || state.doorState === 'open' || state.doorState === 'closing')) return;
    if (block.type === 'pit') return; 
    if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
      if (block.type === 'door' && state.doorState === 'closed') { state.doorState = 'opening'; player.vel.x = 0; return; }
      const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
      const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
      if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; if (player.isCharging) player.isCharging = false; }
      else { if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.vel.y = 0; } else { player.pos.y = block.y + block.h; player.vel.y = 0; } }
    }
  });
};

export const drawPlayer = (ctx: CanvasRenderingContext2D, state: any, invincibilityEnabled: boolean) => {
  const p = state.player;
  if (state.deathTimer > 0) return;
  ctx.save(); let drawX = p.pos.x, drawY = p.pos.y, drawW = p.width, drawH = p.height;

  if (p.isDucking) { drawY += 28; drawH -= 28; } 
  else if (p.jumpPrepTimer > 0) { drawY += 15; drawH -= 15; }

  if (p.isUppercutting) { 
    drawH += 30; drawW -= 10; drawY -= 30; drawX += 5; 
    ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 5, drawY - 5, drawW + 10, drawH + 10); ctx.globalAlpha = 1.0; 
  }
  else if (p.isCharging) { 
    drawW += 20; 
    ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0; 
  }

  const isFlashing = (p.invincibilityTimer > 0 || invincibilityEnabled) && Math.floor(state.frame / 5) % 2 === 0;
  if (!isFlashing) { 
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6); 
    ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4); 
  }

  ctx.save();
  const eyeY = drawY + (p.isDucking ? 5 : 10), eyeSpacing = 12, eyeSize = 6, centerX = drawX + drawW / 2;
  const leftEyeX = centerX - (p.facing === 1 ? eyeSpacing / 2 : eyeSpacing / 2 + 5);
  const rightEyeX = centerX + (p.facing === 1 ? eyeSpacing / 2 + 5 : eyeSpacing / 2);

  if (state.playerStunTimer > 0) { 
    ctx.fillStyle = 'yellow'; ctx.beginPath(); ctx.arc(centerX, eyeY - 20, 10, 0, Math.PI * 2); ctx.fill(); 
  }

  if (p.pushbackTimer > 0) {
    // Surprised look when pushed back
    ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 6, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 6, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill();
  } else if (p.invincibilityTimer > 0) {
    // Bloodshot and Angry look when hurt (invincibility phase)
    ctx.fillStyle = '#ffaaaa'; ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 4, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 4, 0, Math.PI * 2); ctx.fill();

    // Angry red pupils
    ctx.fillStyle = 'red'; ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill();

    // Veins (bloodshot)
    ctx.strokeStyle = '#ff0000'; ctx.lineWidth = 1;
    for(let i=0; i<4; i++) {
        const ang = i * Math.PI * 0.5;
        ctx.beginPath(); ctx.moveTo(leftEyeX, eyeY); ctx.lineTo(leftEyeX + Math.cos(ang)*8, eyeY + Math.sin(ang)*8); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(rightEyeX, eyeY); ctx.lineTo(rightEyeX + Math.cos(ang)*8, eyeY + Math.sin(ang)*8); ctx.stroke();
    }

    // Very Angry Furrowed brows
    ctx.strokeStyle = 'black'; ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(leftEyeX - 10, eyeY - 6); ctx.lineTo(leftEyeX + 6, eyeY + 1); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(rightEyeX + 10, eyeY - 6); ctx.lineTo(rightEyeX - 6, eyeY + 1); ctx.stroke();
  } else if (p.killSatisfactionTimer > 0) {
    ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(leftEyeX, eyeY + 2, eyeSize + 2, Math.PI, 0); ctx.stroke(); ctx.beginPath(); ctx.arc(rightEyeX, eyeY + 2, eyeSize + 2, Math.PI, 0); ctx.stroke();
  } else { 
    // Default: Closed eyes with furrowed brows
    ctx.strokeStyle = 'black'; 
    // Left eye/brow
    ctx.lineWidth = 4; // Thick furrowed brow
    ctx.beginPath(); ctx.moveTo(leftEyeX - 8, eyeY - 4); ctx.lineTo(leftEyeX + 4, eyeY + 1); ctx.stroke();
    ctx.lineWidth = 2; // Thin closed eye slit
    ctx.beginPath(); ctx.moveTo(leftEyeX - 6, eyeY + 3); ctx.lineTo(leftEyeX + 6, eyeY + 3); ctx.stroke();

    // Right eye/brow
    ctx.lineWidth = 4; // Thick furrowed brow
    ctx.beginPath(); ctx.moveTo(rightEyeX + 8, eyeY - 4); ctx.lineTo(rightEyeX - 4, eyeY + 1); ctx.stroke();
    ctx.lineWidth = 2; // Thin closed eye slit
    ctx.beginPath(); ctx.moveTo(rightEyeX - 6, eyeY + 3); ctx.lineTo(rightEyeX + 6, eyeY + 3); ctx.stroke();
  }
  ctx.restore();

  const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14, gunY = p.isDucking ? drawY + 10 : drawY + 25;
  if (!isFlashing) {
      if (p.currentWeapon === 'GUN') { ctx.fillStyle = '#333'; ctx.fillRect(gunX, gunY, 24, 10); } 
      else if (p.currentWeapon === 'BOULDER') { ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(gunX + 12, gunY + 5, 12, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); }
      else if (p.currentWeapon === 'SHOTGUN') { ctx.fillStyle = '#00FFFF'; ctx.fillRect(gunX, gunY, 20, 12); }
      else if (p.currentWeapon === 'FLAMETHROWER') { ctx.fillStyle = '#444'; ctx.fillRect(gunX, gunY, 30, 14); ctx.fillStyle = '#FF4500'; ctx.fillRect(p.facing === 1 ? gunX + 30 : gunX - 5, gunY + 4, 5, 6); }
      else if (p.currentWeapon === 'TSUNAMI') { ctx.fillStyle = '#1E90FF'; ctx.fillRect(gunX, gunY, 32, 16); ctx.fillStyle = '#fff'; ctx.fillRect(p.facing === 1 ? gunX + 28 : gunX, gunY + 4, 4, 8); }
  }

  if (state.lastVulgarity && state.vulgarityTimer > 0) { 
    ctx.font = 'bold 10px "Press Start 2P"'; ctx.fillStyle = 'white'; ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.textAlign = 'center'; ctx.fillText(state.lastVulgarity, drawX + drawW/2, drawY - 20); ctx.shadowBlur = 0; 
  }
  ctx.restore();
};

import { Enemy, Projectile } from '../types';
import { 
  COLORS, GRAVITY, BULLET_DAMAGE, BOSS_CHARGE_DAMAGE, BOSS_UPPERCUT_DAMAGE, WEAKNESS_DAMAGE, 
  BOULDER_SPEED, CANVAS_WIDTH, BOSS_DOOR_X 
} from '../constants';
import { spawnDeathShower, spawnPickup, speakVulgarity, triggerBossDeath } from './systems';

export const updateEnemies = (state: any, invincibilityEnabled: boolean) => {
  const { player, camera, stageId, arenaLocked, frame } = state;
  state.enemies = state.enemies.filter((enemy: any) => {
    if (enemy.isBlownAway) { enemy.pos.x += enemy.vel.x; enemy.pos.y += enemy.vel.y; enemy.vel.y += GRAVITY * 0.5; enemy.rotation = (enemy.rotation || 0) + 0.3; return enemy.pos.y < 1000; }
    if (enemy.health <= 0) return false; 
    if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
    if (enemy.frozenTimer && enemy.frozenTimer > 0) { enemy.frozenTimer--; return true; } 
    const onScreen = enemy.pos.x + enemy.width > camera.x && enemy.pos.x < camera.x + CANVAS_WIDTH;

    if (enemy.enemyType === 'flyer') enemy.pos.y += Math.sin((frame + (enemy.initialX || 0)) / 25) * 1.2;

    if (enemy.type !== 'boss') {
      if (enemy.id.startsWith('rusher')) {
          if (enemy.pauseTimer && enemy.pauseTimer > 0) { enemy.pauseTimer--; enemy.vel.x *= 0.92; } 
          else {
              const yDiff = Math.abs((player.pos.y + player.height/2) - (enemy.pos.y + enemy.height/2));
              if (onScreen && player.invincibilityTimer <= 0 && yDiff < 80) enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 6; 
              else enemy.vel.x = 0;
          }
      } else if (enemy.behavior === 'patrol') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; } 
      else if (enemy.behavior === 'fly') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; } 
      else if (enemy.behavior === 'shoot' && onScreen) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) { state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0; }
        } else if (enemy.shootTimer > 60) {
            const projY = enemy.enemyType === 'flyer' ? enemy.pos.y + enemy.height - 10 : enemy.pos.y + 20;
            state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width/2, y: projY }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0;
        }
      }
      enemy.pos.x += enemy.vel.x;
    }

    let hbW = player.width, hbH = player.height, hbX = player.pos.x, hbY = player.pos.y;
    if (player.isCharging) { hbW = player.width + 10; hbH = player.height - 10; }
    else if (player.isUppercutting) { hbW = player.width - 15; hbH = player.height + 40; hbY = player.pos.y - 30; hbX = player.pos.x + 7.5; }
    const chargeHit = (player.isCharging || player.isUppercutting) && hbX < enemy.pos.x + enemy.width && hbX + hbW > enemy.pos.x && hbY < enemy.pos.y + enemy.height && hbY + hbH > enemy.pos.y;

    if (chargeHit && onScreen && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
      const damage = player.isUppercutting ? BOSS_UPPERCUT_DAMAGE : BOSS_CHARGE_DAMAGE;
      enemy.health -= damage; enemy.hitCooldown = 60; 
      if (enemy.health > 0) { 
        if (enemy.id.startsWith('rusher')) { enemy.vel.x = player.facing * 15; enemy.pauseTimer = 120; } 
        else { enemy.vel.x = 0; enemy.vel.y = 0; }
        player.vel = { x: -player.facing * 18, y: -4 }; player.pushbackTimer = 20; player.isCharging = false; player.isUppercutting = false; player.invincibilityTimer = 30; 
      } else {
          if (enemy.type === 'boss') triggerBossDeath(state, enemy, player.facing, false);
          else { 
              enemy.isBlownAway = true; enemy.vel = { x: player.isUppercutting ? 0 : player.facing * 30, y: player.isUppercutting ? -30 : -5 };
              spawnDeathShower(state, enemy.pos, player.facing); spawnPickup(state, enemy.pos); speakVulgarity(state, player.isUppercutting ? 'uppercut_kill' : 'charge_kill'); player.killSatisfactionTimer = 60; 
          }
          return false;
      }
    } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x && player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
        if (!invincibilityEnabled) player.health -= 7.5; // Halved from 15
        player.invincibilityTimer = 60; speakVulgarity(state, 'hurt');
        if (enemy.id.startsWith('rusher') || (enemy.type === 'boss' && state.arenaLocked)) {
            if (enemy.id.startsWith('rusher')) enemy.pauseTimer = 60;
            player.pushbackTimer = 30; player.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 20; player.vel.y = -8;
        }
    }
    return true;
  });
};

export const drawBossSprite = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null) => {
    const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
    if (e.rotation) { ctx.translate(width / 2, height / 2); ctx.rotate(e.rotation); ctx.translate(-width / 2, -height / 2); }
    switch (id) {
      case 'Artie Avalanche':
          ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
          ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
      case 'Victor Volcano':
          ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
          ctx.fillStyle = '#8b4513'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.3, 0, Math.PI * 2); ctx.fill(); break;
      case 'Ernie Earthquake':
          ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7);
          ctx.fillStyle = '#e0ac69'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
      case 'Hector Hurricane':
          ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7);
          ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
    }
    ctx.restore();
};

export const drawEnemy = (ctx: CanvasRenderingContext2D, e: any, state: any) => {
  if (e.health <= 0 && !e.isBlownAway) return;
  ctx.save();
  if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
  else if (e.type === 'boss' && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }

  if (e.type === 'boss') drawBossSprite(ctx, e, state.stageId); 
  else { 
    if (e.enemyType === 'shield') { 
      ctx.fillStyle = '#444'; ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height);
      if (e.isShieldActive) { ctx.fillStyle = '#2C3E50'; ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); ctx.strokeStyle = '#00FFFF'; ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); } 
      else { ctx.fillStyle = '#7F8C8D'; ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20); }
    } else if (e.id.startsWith('rusher')) {
      ctx.fillStyle = '#9B59B6'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      const yDiff = Math.abs((state.player.pos.y + state.player.height/2) - (e.pos.y + e.height/2));
      if (yDiff >= 80 && (!e.pauseTimer || e.pauseTimer <= 0)) { ctx.fillStyle = 'rgba(255, 255, 255, 0.2)'; ctx.font = '10px monospace'; ctx.fillText('...', e.pos.x + e.width/2 - 10, e.pos.y - 15); }
    } else if (e.enemyType === 'flyer' && e.width > 60) {
        ctx.fillStyle = '#34495E'; ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30);
        ctx.fillStyle = '#E74C3C'; ctx.fillRect(e.pos.x + e.width/2 - 10, e.pos.y + 25, 20, 8);
    } else { 
      ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); 
      ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); 
    } 
  }
  if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
  if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
  ctx.restore();
};

import { Projectile, WeaponType } from '../types';
import { 
  COLORS, GRAVITY, BOULDER_BOUNCE_DAMPING, CANVAS_WIDTH, SHOTGUN_FREEZE_TIME, 
  WEAKNESS_DAMAGE, BULLET_DAMAGE 
} from '../constants';
import { 
  spawnRockShatter, spawnGlassShatter, spawnDeathShower, spawnPickup, 
  speakVulgarity, triggerBossDeath 
} from './systems';

export const updateProjectiles = (state: any, audioCtx: AudioContext | null, invincibilityEnabled: boolean) => {
  const { player, blocks, enemies, stageId } = state;
  state.projectiles = state.projectiles.filter((p: any) => {
    if (p.health <= 0) return false;
    const isGiantIce = p.isIce && p.width > 30;
    const isShard = p.isIce && p.width <= 20; 
    const isPlayerIce = p.owner === 'player' && p.isIce;

    if (p.bounceDecay !== undefined) { p.bounceDecay--; if (p.bounceDecay <= 0) return false; }

    if (p.isBoulder || isGiantIce || isShard || isPlayerIce) {
      p.vel.y += (isShard || isPlayerIce ? GRAVITY * 0.3 : GRAVITY); p.pos.y += p.vel.y;
      for (const b of blocks) {
        if (b.type !== 'pit' && p.pos.x < b.x + b.w && p.pos.x + p.width > b.x && p.pos.y < b.y + b.h && p.pos.y + p.height > b.y) {
          const overlapX = Math.min(p.pos.x + p.width - b.x, b.x + b.w - p.pos.x);
          const overlapY = Math.min(p.pos.y + p.height - b.y, b.y + b.h - p.pos.y);
          if (overlapX < overlapY) {
            if (p.isBoulder) { spawnRockShatter(state, { x: p.pos.x + p.width / 2, y: p.pos.y + p.height / 2 }); return false; }
            if (isGiantIce) { spawnGlassShatter(state, audioCtx, { x: p.pos.x + p.width / 2, y: p.pos.y + p.height / 2 }); return false; }
            if (isShard || isPlayerIce) { p.vel.x *= -1.0; p.pos.x += p.vel.x; if (isPlayerIce && p.bounceDecay === undefined) p.bounceDecay = 60; } 
          } else {
            if (Math.abs(p.vel.y) > 1.0) { p.vel.y = -p.vel.y * (p.isBoulder ? BOULDER_BOUNCE_DAMPING : 0.85); if (isPlayerIce && p.bounceDecay === undefined) p.bounceDecay = 60; } 
            else p.vel.y = 0; p.pos.y = (p.pos.y + p.height / 2 < b.y + b.h / 2) ? b.y - p.height : b.y + b.h;
          }
        }
      }
      p.pos.x += p.vel.x;
    } else { p.pos.x += p.vel.x; p.pos.y += p.vel.y; }

    if (p.pos.x < state.camera.x - 200 || p.pos.x > state.camera.x + CANVAS_WIDTH + 200) return false;
    if (p.owner === 'player') {
      for (const enemy of enemies) {
        if (enemy.health > 0 && !enemy.isBlownAway && p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
          if (enemy.enemyType === 'shield' && enemy.isShieldActive && ((p.vel.x > 0 && p.pos.x < enemy.pos.x) || (p.vel.x < 0 && p.pos.x > enemy.pos.x))) return false; 
          if (enemy.type === 'boss') {
            if (enemy.hitCooldown && enemy.hitCooldown > 0) return false; 
            enemy.health -= 25; enemy.hitCooldown = 60; if (enemy.health <= 0) triggerBossDeath(state, enemy, p.vel.x > 0 ? 1 : -1, false);
          } else {
            enemy.health -= p.damage; if (p.isIce) enemy.frozenTimer = SHOTGUN_FREEZE_TIME;
            if (enemy.health <= 0) { spawnDeathShower(state, enemy.pos, 0, 1.2); spawnPickup(state, enemy.pos); speakVulgarity(state, p.isBoulder ? 'boulder_kill' : (p.isIce ? 'shotgun_kill' : 'gun_kill')); player.killSatisfactionTimer = 60; }
          }
          if (p.isBoulder) spawnRockShatter(state, { x: p.pos.x + p.width / 2, y: p.pos.y + p.height / 2 });
          return false;
        }
      }
    } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + player.height > player.pos.y) {
        if (!invincibilityEnabled) player.health -= p.damage / 2; // Halved damage
        player.invincibilityTimer = 60; speakVulgarity(state, 'hurt'); player.pushbackTimer = 20;
        if (p.isBoulder) spawnRockShatter(state, { x: p.pos.x + p.width / 2, y: p.pos.y + p.height / 2 });
        return false;
    }
    return true;
  });
};

export const drawProjectile = (ctx: CanvasRenderingContext2D, p: any) => {
  if (p.isBoulder) { 
      ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); 
      ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = 'black'; ctx.stroke(); ctx.restore(); 
  } else { 
      ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); 
      ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); 
      if (p.isIce) { ctx.strokeStyle = 'white'; ctx.lineWidth = 1; ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height); }
  } 
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import HUD from './components/HUD';
import Overlay from './components/Overlay';
import GameCanvas from './components/GameCanvas';
import { GameStatus, WeaponType } from './types';
import { INITIAL_PLAYER_HEALTH, SPECIAL_CHARGE_REGEN_FRAMES, MAX_AMMO } from './constants';

const STAGES = ['Artie Avalanche', 'Victor Volcano', 'Ernie Earthquake', 'Hector Hurricane'];

// --- DEV CONFIG ---
const SHOW_CHEATS = true;
// ------------------

const REBUKES = [
  "I ALREADY KILLED HIM, YOU DUMB FUCK.",
  "THAT SHIT-STAIN IS ALREADY GONE.",
  "HE'S SCRAP METAL. QUIT WASTING MY GAINS.",
  "I ALREADY OBLITERATED THAT TRASH."
];

const LOCAL_BOSS_TAUNTS: Record<string, string[]> = {
  'Artie Avalanche': ["Prepare for freezer burn, meat bag."],
  'Victor Volcano': ["Well done. This is how you will be cooked, Meatface."],
  'Ernie Earthquake': ["Let's get ready to rumble, fucko."],
  'Hector Hurricane': ["I'll turn you into a soggy lump of shit."],
  'default': ["I'll break you in half!"]
};

const LOCAL_VICTORY_LINES: string[] = [
  "YOUR BIOLOGY WAS INFERIOR. THE PUMP PREVAILS.",
  "GAINS ACHIEVED. WEAKNESS DELETED.",
  "THAT WAS JUST A WARM-UP SET.",
  "IMAGINE BEING ORGANIC AND THIS WEAK.",
  "I'VE HAD TOUGHER WORKOUTS IN THE SAUNA.",
  "PURE BEEF BEATS METAL EVERY TIME."
];

const BOSS_WEAPON_MAP: Record<string, WeaponType> = {
  'Artie Avalanche': 'SHOTGUN',
  'Victor Volcano': 'FLAMETHROWER',
  'Ernie Earthquake': 'BOULDER',
  'Hector Hurricane': 'TSUNAMI'
};

const ALL_WEAPONS: WeaponType[] = ['GUN', 'BOULDER', 'SHOTGUN', 'FLAMETHROWER', 'TSUNAMI'];

const App: React.FC = () => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.START);
  const [health, setHealth] = useState(INITIAL_PLAYER_HEALTH);
  const [specialCharges, setSpecialCharges] = useState(2);
  const [specialChargeTimer, setSpecialChargeTimer] = useState(0);
  const [bossTaunt, setBossTaunt] = useState("YOU'RE TOAST.");
  const [victorySpeech, setVictorySpeech] = useState("");
  const [briefing, setBriefing] = useState("Your mission is to kill everything in sight for no particular reason.");
  const [selectedStage, setSelectedStage] = useState<string | null>(null);
  const [defeatedStages, setDefeatedStages] = useState<string[]>([]);
  const [availableWeapons, setAvailableWeapons] = useState<WeaponType[]>(['GUN']);
  const [currentWeapon, setCurrentWeapon] = useState<WeaponType>('GUN');
  const [weaponAmmo, setWeaponAmmo] = setWeaponAmmo = useState<Record<WeaponType, number>>({
    'GUN': Infinity,
    'BOULDER': MAX_AMMO['BOULDER'],
    'SHOTGUN': MAX_AMMO['SHOTGUN'],
    'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
    'TSUNAMI': MAX_AMMO['TSUNAMI']
  });

  const [cheatEnabled, setCheatEnabled] = useState(false);
  const [invincibilityEnabled, setInvincibilityEnabled] = useState(false);
  const [infiniteAmmoEnabled, setInfiniteAmmoEnabled] = useState(false);
  const [jumpToBossEnabled, setJumpToBossEnabled] = useState(false);

  const [isVictoryPhase, setIsVictoryPhase] = useState(false);
  const [overlayActiveTime, setOverlayActiveTime] = useState(0);

  const [selectedIndex, setSelectedIndex] = useState(0);
  const lastPadInputRef = useRef(0);
  const lastAStateRef = useRef(false);
  const lastBStateRef = useRef(false);
  const lastStartStateRef = useRef(false);
  const lastLBStateRef = useRef(false);
  const lastRBStateRef = useRef(false);

  useEffect(() => {
    let interval: number;
    if (status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.START || status === GameStatus.VICTORY) {
      setOverlayActiveTime(0);
      interval = window.setInterval(() => {
        setOverlayActiveTime(prev => prev + 100);
      }, 100);
    }
    return () => clearInterval(interval);
  }, [status]);

  const cycleWeapon = useCallback((dir: number) => {
    setAvailableWeapons(prevAvailable => {
      if (prevAvailable.length <= 1) return prevAvailable;
      setCurrentWeapon(current => {
        const idx = prevAvailable.indexOf(current);
        const nextIdx = (idx + dir + prevAvailable.length) % prevAvailable.length;
        return prevAvailable[nextIdx];
      });
      return prevAvailable;
    });
  }, []);

  const speakRebuke = useCallback(() => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const text = REBUKES[Math.floor(Math.random() * REBUKES.length)];
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1;
      utterance.rate = 1.1;
      utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  const togglePause = useCallback(() => {
    setStatus(prev => {
      if (isVictoryPhase || 
          prev === GameStatus.BOSS_TRANSITION || 
          prev === GameStatus.BOSS_INTRO || 
          prev === GameStatus.BOSS_VICTORY_SPEECH || 
          prev === GameStatus.LEVEL_INTRO ||
          prev === GameStatus.VICTORY) {
        return prev;
      }

      if (prev === GameStatus.PLAYING) {
        setSelectedIndex(0);
        return GameStatus.PAUSED;
      }
      if (prev === GameStatus.PAUSED) return GameStatus.PLAYING;
      return prev;
    });
  }, [isVictoryPhase]);

  const handleStart = useCallback(() => {
    if (overlayActiveTime < 2000) return;

    if (status === GameStatus.VICTORY || status === GameStatus.GAME_OVER) {
      setDefeatedStages([]);
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS : ['GUN'];
      setAvailableWeapons(weaponsToStart);
      setCurrentWeapon('GUN');
      setWeaponAmmo({
        'GUN': Infinity,
        'BOULDER': MAX_AMMO['BOULDER'],
        'SHOTGUN': MAX_AMMO['SHOTGUN'],
        'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
        'TSUNAMI': MAX_AMMO['TSUNAMI']
      });
      setSelectedIndex(0);
      setIsVictoryPhase(false);
      setStatus(GameStatus.START);
    } else if (status === GameStatus.START) {
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS : ['GUN'];
      setAvailableWeapons(weaponsToStart);
      setCurrentWeapon('GUN');
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.BOSS_INTRO) {
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_VICTORY_SPEECH) {
      setIsVictoryPhase(false);
      if (defeatedStages.length >= 4) {
        setStatus(GameStatus.VICTORY);
      } else {
        setStatus(GameStatus.STAGE_SELECT);
        setSelectedStage(null);
        setSelectedIndex(0);
        setCurrentWeapon('GUN');
        setWeaponAmmo({
          'GUN': Infinity,
          'BOULDER': MAX_AMMO['BOULDER'],
          'SHOTGUN': MAX_AMMO['SHOTGUN'],
          'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
          'TSUNAMI': MAX_AMMO['TSUNAMI']
        });
      }
    }
  }, [status, defeatedStages, overlayActiveTime, cheatEnabled]);

  const handleResume = useCallback(() => {
    setStatus(GameStatus.PLAYING);
  }, []);

  const handleBossSelect = useCallback(() => {
    setSelectedStage(null);
    setSelectedIndex(0);
    setIsVictoryPhase(false);
    setCurrentWeapon('GUN');
    setStatus(GameStatus.STAGE_SELECT);
    setWeaponAmmo({
      'GUN': Infinity,
      'BOULDER': MAX_AMMO['BOULDER'],
      'SHOTGUN': MAX_AMMO['SHOTGUN'],
      'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
      'TSUNAMI': MAX_AMMO['TSUNAMI']
    });
  }, []);

  const handleQuitToMenu = useCallback(() => {
    setSelectedStage(null);
    setSelectedIndex(0);
    setIsVictoryPhase(false);
    setDefeatedStages([]);
    setCurrentWeapon('GUN');
    setStatus(GameStatus.START);
  }, []);

  const handleSelectStage = useCallback((stage: string) => {
    if (defeatedStages.includes(stage)) {
      speakRebuke();
      return;
    }
    setSelectedStage(stage);
    setHealth(INITIAL_PLAYER_HEALTH);
    setSpecialCharges(2);
    setSpecialChargeTimer(0);
    setCurrentWeapon('GUN');
    setWeaponAmmo({
      'GUN': Infinity,
      'BOULDER': MAX_AMMO['BOULDER'],
      'SHOTGUN': MAX_AMMO['SHOTGUN'],
      'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
      'TSUNAMI': MAX_AMMO['TSUNAMI']
    });
    setIsVictoryPhase(false);
    setStatus(GameStatus.LEVEL_INTRO);
  }, [defeatedStages, speakRebuke]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      if (key === 'escape') {
        togglePause();
      }

      if (status === GameStatus.PAUSED || status === GameStatus.STAGE_SELECT) {
        if (key === 'arrowup' || key === 'w') {
          if (status === GameStatus.PAUSED) setSelectedIndex(p => (p - 1 + 3) % 3);
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p - 2 + 4) % 4);
        } else if (key === 'arrowdown' || key === 's') {
          if (status === GameStatus.PAUSED) setSelectedIndex(p => (p + 1) % 3);
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p + 2) % 4);
        } else if (key === 'arrowleft' || key === 'a') {
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
        } else if (key === 'arrowright' || key === 'd') {
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
        } else if (key === 'enter' || key === ' ') {
          if (status === GameStatus.PAUSED) {
            if (selectedIndex === 0) handleResume();
            else if (selectedIndex === 1) handleBossSelect();
            else if (selectedIndex === 2) handleQuitToMenu();
          } else if (status === GameStatus.STAGE_SELECT) {
            handleSelectStage(STAGES[selectedIndex]);
          }
        }
      } else if (status === GameStatus.PLAYING) {
        if (key === 'q') cycleWeapon(-1);
        if (key === 'e') cycleWeapon(1);
      } else if (status === GameStatus.START || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY) {
        if (key === 'enter' || key === ' ') handleStart();
      }
    };
    const handleWheel = (e: WheelEvent) => {
      if (status === GameStatus.PLAYING) {
        cycleWeapon(e.deltaY > 0 ? 1 : -1);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('wheel', handleWheel);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('wheel', handleWheel);
    };
  }, [togglePause, status, cycleWeapon, selectedIndex, handleResume, handleBossSelect, handleQuitToMenu, handleSelectStage, handleStart]);

  const handleToggleCheat = useCallback(() => {
    setCheatEnabled(prev => !prev);
  }, []);

  const handleToggleInvincibility = useCallback(() => {
    setInvincibilityEnabled(prev => !prev);
  }, []);

  const handleToggleInfiniteAmmo = useCallback(() => {
    setInfiniteAmmoEnabled(prev => !prev);
  }, []);

  const handleToggleJumpToBoss = useCallback(() => {
    setJumpToBossEnabled(prev => !prev);
  }, []);

  const handleBossTransition = useCallback(() => {
    setStatus(GameStatus.BOSS_TRANSITION);
  }, []);

  const handleBossDeath = useCallback(() => {
    setIsVictoryPhase(true);
  }, []);

  const handleBossEncounter = useCallback(() => {
    setStatus(GameStatus.BOSS_INTRO);
    const pool = LOCAL_BOSS_TAUNTS[selectedStage || ''] || LOCAL_BOSS_TAUNTS['default'];
    const taunt = pool[Math.floor(Math.random() * pool.length)];
    setBossTaunt(taunt);
  }, [selectedStage]);

  const handleBossDefeated = useCallback((stageId: string) => {
    const newWeapon = BOSS_WEAPON_MAP[stageId];
    if (newWeapon) {
      setAvailableWeapons(prev => {
        if (!prev.includes(newWeapon)) {
          return [...prev, newWeapon];
        }
        return prev;
      });
    }
    setDefeatedStages(prev => [...prev, stageId]);
    const speech = LOCAL_VICTORY_LINES[Math.floor(Math.random() * LOCAL_VICTORY_LINES.length)];
    setVictorySpeech(speech);
    setStatus(GameStatus.BOSS_VICTORY_SPEECH);
  }, []);

  const handleGameOver = useCallback((victory: boolean) => {
    if (!victory) {
        setIsVictoryPhase(false);
        setStatus(GameStatus.GAME_OVER);
    }
  }, []);

  const handlePlayerUpdate = useCallback((h: number, sc: number, st: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => {
    setHealth(h);
    setSpecialCharges(sc);
    setSpecialChargeTimer(st);
    if (ammo) setWeaponAmmo(ammo);
    if (forcedWeapon) setCurrentWeapon(forcedWeapon);
  }, []);

  const handleIntroComplete = useCallback(() => {
    setStatus(GameStatus.PLAYING);
  }, []);

  useEffect(() => {
    let frameId: number;
    const poll = () => {
      const allGamepads = navigator.getGamepads();
      const gp = Array.from(allGamepads).find(p => p !== null);

      if (gp) {
        const now = Date.now();

        if (now - lastPadInputRef.current > 200) {
            let dx = 0; let dy = 0;
            // Check sticks
            if (gp.axes[0] < -0.4) dx = -1;
            else if (gp.axes[0] > 0.4) dx = 1;
            if (gp.axes[1] < -0.4) dy = -1;
            else if (gp.axes[1] > 0.4) dy = 1;

            // Check D-Pad
            if (gp.buttons[14]?.pressed) dx = -1;
            else if (gp.buttons[15]?.pressed) dx = 1;
            if (gp.buttons[12]?.pressed) dy = -1;
            else if (gp.buttons[13]?.pressed) dy = 1;

            if (status === GameStatus.STAGE_SELECT) {
              if (dx !== 0) {
                setSelectedIndex(prev => (prev % 2 === 0 ? prev + 1 : prev - 1));
                lastPadInputRef.current = now;
              } else if (dy !== 0) {
                setSelectedIndex(prev => (prev < 2 ? prev + 2 : prev - 2));
                lastPadInputRef.current = now;
              }
            } else if (status === GameStatus.PAUSED) {
              if (dy < -0.4) { // Up
                  setSelectedIndex(prev => (prev - 1 + 3) % 3);
                  lastPadInputRef.current = now;
              } else if (dy > 0.4) { // Down
                  setSelectedIndex(prev => (prev + 1) % 3);
                  lastPadInputRef.current = now;
              }
            }
        }

        const aPressed = gp.buttons[0]?.pressed; 
        const bPressed = gp.buttons[1]?.pressed; 
        const startPressed = gp.buttons[9]?.pressed;
        const lbPressed = gp.buttons[4]?.pressed;
        const rbPressed = gp.buttons[5]?.pressed;

        if (aPressed && !lastAStateRef.current) {
            if (status === GameStatus.START || status === GameStatus.VICTORY || status === GameStatus.GAME_OVER || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) {
              handleStart();
            } else if (status === GameStatus.STAGE_SELECT) {
              handleSelectStage(STAGES[selectedIndex]);
            } else if (status === GameStatus.PAUSED) {
              if (selectedIndex === 0) handleResume();
              else if (selectedIndex === 1) handleBossSelect();
              else handleQuitToMenu();
            }
        }

        if (bPressed && !lastBStateRef.current) {
            if (status === GameStatus.PAUSED) handleResume();
            else if (status === GameStatus.STAGE_SELECT) setStatus(GameStatus.START);
        }

        if (startPressed && !lastStartStateRef.current) {
            if (status === GameStatus.START) handleStart();
            else if (status === GameStatus.PLAYING || status === GameStatus.PAUSED) togglePause();
        }

        if (status === GameStatus.PLAYING) {
          if (lbPressed && !lastLBStateRef.current) cycleWeapon(-1);
          if (rbPressed && !lastRBStateRef.current) cycleWeapon(1);
        }

        lastAStateRef.current = !!aPressed;
        lastBStateRef.current = !!bPressed;
        lastStartStateRef.current = !!startPressed;
        lastLBStateRef.current = !!lbPressed;
        lastRBStateRef.current = !!rbPressed;
      }
      frameId = requestAnimationFrame(poll);
    };
    frameId = requestAnimationFrame(poll);
    return () => cancelAnimationFrame(frameId);
  }, [status, selectedIndex, handleStart, handleSelectStage, handleResume, handleBossSelect, handleQuitToMenu, togglePause, cycleWeapon]);

  return (
    <div className="relative w-screen h-screen flex items-center justify-center bg-black overflow-hidden">
      <div className="relative shadow-2xl border-4 border-gray-800 bg-[#121212]" style={{ width: 800, height: 600 }}>
        {(status === GameStatus.LEVEL_INTRO || status === GameStatus.PLAYING || status === GameStatus.BOSS_TRANSITION || status === GameStatus.PAUSED || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) && (
          <HUD 
            health={health} 
            maxHealth={INITIAL_PLAYER_HEALTH} 
            specialCharges={specialCharges}
            specialChargeTimer={specialChargeTimer}
            maxChargeTimer={SPECIAL_CHARGE_REGEN_FRAMES}
            currentWeapon={currentWeapon}
            ammo={weaponAmmo[currentWeapon]}
            maxAmmo={MAX_AMMO[currentWeapon]}
          />
        )}

        <Overlay 
          status={status} 
          onStart={handleStart} 
          onResume={handleResume}
          onBossSelect={handleBossSelect}
          onQuitToMenu={handleQuitToMenu}
          onSelectStage={handleSelectStage}
          onCheatAllWeapons={handleToggleCheat}
          onToggleInvincibility={handleToggleInvincibility}
          onToggleInfiniteAmmo={handleToggleInfiniteAmmo}
          onToggleJumpToBoss={handleToggleJumpToBoss}
          cheatEnabled={cheatEnabled}
          invincibilityEnabled={invincibilityEnabled}
          infiniteAmmoEnabled={infiniteAmmoEnabled}
          jumpToBossEnabled={jumpToBossEnabled}
          showCheats={SHOW_CHEATS}
          bossTaunt={bossTaunt}
          victorySpeech={victorySpeech}
          briefing={briefing}
          defeatedStages={defeatedStages}
          selectedIndex={selectedIndex}
          overlayActiveTime={overlayActiveTime}
          stageId={selectedStage}
        />

        <GameCanvas 
          status={status}
          stageId={selectedStage}
          onPlayerUpdate={handlePlayerUpdate}
          onBossEncounter={handleBossEncounter}
          onBossTransition={handleBossTransition}
          onBossDefeated={handleBossDefeated}
          onBossDeath={handleBossDeath}
          onGameOver={handleGameOver}
          onIntroComplete={handleIntroComplete}
          onTogglePause={togglePause}
          currentWeapon={currentWeapon}
          initialAmmo={weaponAmmo}
          invincibilityEnabled={invincibilityEnabled && (SHOW_CHEATS)}
          infiniteAmmoEnabled={infiniteAmmoEnabled && (SHOW_CHEATS)}
          jumpToBossEnabled={jumpToBossEnabled && (SHOW_CHEATS)}
        />
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useCallback } from 'react';
import { GameStatus, WeaponType } from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, STAGE_COLORS, COLORS, 
  MAX_SPECIAL_CHARGES, INITIAL_PLAYER_HEALTH, BOSS_DOOR_X, DOOR_WIDTH 
} from '../constants';
import { updatePlayer, drawPlayer } from '../logic/player';
import { updateEnemies, drawEnemy } from '../logic/enemies';
import { updateProjectiles, drawProjectile } from '../logic/projectiles';
import { updateTsunami, updatePickups, updateParticles } from '../logic/environment';
import { createLevel, speakIntroLine, spawnDeathShower, spawnGlassShatter } from '../logic/systems';

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, specialCharges: number, specialChargeTimer: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  jumpToBossEnabled: boolean;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const gameStateRef = useRef({
    player: {
      id: 'player', pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, width: 44, height: 64, health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH, type: 'player', isCharging: false, isUppercutting: false, isDucking: false,
      specialCharges: MAX_SPECIAL_CHARGES, specialChargeTimer: 0, chargeDuration: 0, isJumping: false, isGrounded: false,
      facing: 1, shootCooldown: 0, jumpPrepTimer: 0, landTimer: 0, invincibilityTimer: 0, pushbackTimer: 0,
      killSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true, currentWeapon: 'GUN', weaponAmmo: { ...initialAmmo }
    } as any,
    enemies: [] as any[], projectiles: [] as any[], pickups: [] as any[], particles: [] as any[],
    blocks: [] as any[], camera: { x: 0, y: 0 }, arenaLocked: false, doorOpenAmount: 0,
    doorState: 'closed' as any, frame: 0, lastVulgarity: "", vulgarityTimer: 0, voiceLineCooldown: 0,
    victoryString: "", deathString: "", deathTimer: 0, postVictoryTimer: 0, introTimer: 0, tsunamiActive: false,
    playerStunTimer: 0, screenShakeTimer: 0, stageId: stageId,
    onBossDeath, onBossDefeated
  });

  useEffect(() => {
    gameStateRef.current.onBossDeath = onBossDeath;
    gameStateRef.current.onBossDefeated = onBossDefeated;
  }, [onBossDeath, onBossDefeated]);

  useEffect(() => { 
    gameStateRef.current.player.currentWeapon = currentWeapon; 
  }, [currentWeapon]);

  useEffect(() => { 
    if (gameStateRef.current.deathTimer <= 0) {
      gameStateRef.current.player.weaponAmmo = { ...initialAmmo }; 
    }
  }, [initialAmmo]);

  useEffect(() => {
    const kd = (e: KeyboardEvent) => keys.current[e.key.toLowerCase()] = true;
    const ku = (e: KeyboardEvent) => keys.current[e.key.toLowerCase()] = false;
    window.addEventListener('keydown', kd); window.addEventListener('keyup', ku);
    window.addEventListener('mousedown', () => mouse.current.down = true); 
    window.addEventListener('mouseup', () => mouse.current.down = false);
    return () => {
      window.removeEventListener('keydown', kd); window.removeEventListener('keyup', ku);
      if (audioCtxRef.current) audioCtxRef.current.close();
    };
  }, []);

  const resetGame = useCallback(() => {
    const state = gameStateRef.current;
    state.player.health = INITIAL_PLAYER_HEALTH; 
    state.player.pos = { x: 150, y: 100 }; 
    state.player.vel = { x: 0, y: 0 };
    state.deathTimer = 0; 
    state.particles = []; 
    state.projectiles = []; 
    state.pickups = [];
    state.victoryString = ""; 
    state.postVictoryTimer = 0;
    state.arenaLocked = false;
    state.doorState = 'closed';
    state.doorOpenAmount = 0;
    createLevel(state, stageId, jumpToBossEnabled);
  }, [stageId, jumpToBossEnabled]);

  const update = useCallback(() => {
    const state = gameStateRef.current;
    state.frame++;

    if (state.screenShakeTimer > 0) state.screenShakeTimer--;

    if (state.deathTimer > 0) {
        state.deathTimer--;
        if (state.deathTimer === 0) resetGame();
        updateParticles(state); 
        return;
    }

    if (status === GameStatus.PAUSED) return;

    if (state.victoryString) { 
        state.postVictoryTimer--;
        if (state.postVictoryTimer <= 0 && stageId) {
            onBossDefeated(stageId);
        }
        updateParticles(state); 
        return; 
    }

    if (status === GameStatus.LEVEL_INTRO) {
        state.introTimer++; 
        const baseStartX = jumpToBossEnabled ? BOSS_DOOR_X - 800 : 0;
        state.camera.x = baseStartX; 
        state.player.facing = 1;

        if (state.introTimer === 30 && !jumpToBossEnabled) speakIntroLine(state, stageId); 

        if (state.introTimer < 80) {
          state.player.pos.x = baseStartX - 150; 
        } else {
            if (state.introTimer === 80) { 
              if (!audioCtxRef.current) audioCtxRef.current = new AudioContext();
              spawnGlassShatter(state, audioCtxRef.current, { x: baseStartX, y: 450 }); 
            }
            const jumpDuration = 60;
            const t = Math.min(1.0, (state.introTimer - 80) / jumpDuration);
            state.player.pos.x = baseStartX - 100 + (t * 250);
            const peakHeight = 250; const groundY = 486; const startY = 400;
            state.player.pos.y = startY + (groundY - startY) * t - Math.sin(t * Math.PI) * peakHeight;

            if (state.introTimer >= 80 + jumpDuration) { 
              state.player.pos.y = groundY; 
              state.player.pos.x = baseStartX + 150; 
              state.player.vel = { x: 0, y: 0 }; 
              onIntroComplete(); 
            }
        }
        updateParticles(state); 
        return;
    }

    if (status === GameStatus.BOSS_TRANSITION) {
        state.camera.x += (BOSS_DOOR_X - state.camera.x) * 0.1;
        if (state.doorState === 'opening') { 
          state.doorOpenAmount += 5; 
          if (state.doorOpenAmount >= 150) { 
            state.doorState = 'open'; 
            onBossEncounter(); 
          } 
        }
        return;
    }

    // Trigger Boss Transition if player hits door block (handled in updatePlayer)
    if (state.doorState === 'opening' && status === GameStatus.PLAYING) {
        onBossTransition();
    }

    // Arena locking logic
    if (status === GameStatus.PLAYING) {
        if (state.doorState === 'open' && state.player.pos.x > BOSS_DOOR_X + 100) {
            state.doorState = 'closing';
        }
        if (state.doorState === 'closing') {
            state.doorOpenAmount -= 10;
            if (state.doorOpenAmount <= 0) {
                state.doorOpenAmount = 0;
                state.doorState = 'closed';
                state.arenaLocked = true;
                state.camera.x = BOSS_DOOR_X;
            }
        }
    }

    if (status !== GameStatus.PLAYING) return;

    const km = keys.current;
    const allGamepads = navigator.getGamepads();
    const pad = Array.from(allGamepads).find(p => p !== null);

    const controls = {
      moveLeft: km['a'] || km['arrowleft'] || (pad?.axes[0] ?? 0) < -0.3 || pad?.buttons[14]?.pressed,
      moveRight: km['d'] || km['arrowright'] || (pad?.axes[0] ?? 0) > 0.3 || pad?.buttons[15]?.pressed,
      moveUp: km['w'] || km['arrowup'] || (pad?.axes[1] ?? 0) < -0.3 || pad?.buttons[12]?.pressed,
      moveDown: km['s'] || km['arrowdown'] || (pad?.axes[1] ?? 0) > 0.3 || pad?.buttons[13]?.pressed,
      jumpRequested: km[' '] || km['z'] || pad?.buttons[0]?.pressed,
      chargeRequested: km['shift'] || km['c'] || pad?.buttons[7]?.pressed || pad?.buttons[5]?.pressed,
      shootRequested: mouse.current.down || pad?.buttons[2]?.pressed || pad?.buttons[3]?.pressed,
      isFiringFlamethrower: currentWeapon === 'FLAMETHROWER' && (mouse.current.down || pad?.buttons[2]?.pressed || pad?.buttons[3]?.pressed)
    };

    if (state.vulgarityTimer > 0) { state.vulgarityTimer--; if (state.vulgarityTimer <= 0) state.lastVulgarity = ""; }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;

    if (!audioCtxRef.current) audioCtxRef.current = new AudioContext();

    updatePlayer(state, controls, audioCtxRef.current, infiniteAmmoEnabled, invincibilityEnabled);
    updateEnemies(state, invincibilityEnabled);
    updateProjectiles(state, audioCtxRef.current, invincibilityEnabled);
    updateTsunami(state);
    updatePickups(state);
    updateParticles(state);

    if (!state.arenaLocked) {
      const targetCamX = state.player.pos.x - CANVAS_WIDTH/2;
      const maxCamX = (state.doorState === 'closed') ? (BOSS_DOOR_X + DOOR_WIDTH - CANVAS_WIDTH) : (8000 - CANVAS_WIDTH);
      state.camera.x = Math.max(0, Math.min(maxCamX, targetCamX));
    } else {
      state.camera.x = BOSS_DOOR_X;
    }

    if (state.player.health <= 0 || state.player.pos.y > 1000) { 
      state.deathTimer = 180; 
      state.deathString = "YOU DIED"; 
      spawnDeathShower(state, state.player.pos, state.player.facing, 3); 
    }

    onPlayerUpdate(state.player.health, state.player.specialCharges, state.player.specialChargeTimer, state.player.weaponAmmo);
  }, [status, stageId, currentWeapon, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled, onBossDefeated, onBossEncounter, onIntroComplete, onPlayerUpdate, resetGame, onBossTransition]);

  const draw = useCallback(() => {
    const ctx = canvasRef.current?.getContext('2d'); if (!ctx) return;
    const state = gameStateRef.current;
    const colors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };

    ctx.fillStyle = colors.bg; 
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save(); 
    ctx.translate(-state.camera.x, -state.camera.y);

    state.blocks.forEach(b => { 
      if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); } 
      else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.2; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; } 
      else { ctx.fillStyle = colors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = colors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); } 
    });

    state.pickups.forEach(p => { 
      ctx.fillStyle = p.type.includes('health') ? 'red' : 'yellow'; 
      ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); 
    });

    state.enemies.forEach(e => drawEnemy(ctx, e, state));
    state.projectiles.forEach(p => drawProjectile(ctx, p));
    state.particles.forEach(p => { 
      ctx.fillStyle = p.color; 
      ctx.globalAlpha = p.life/100; 
      ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); 
      ctx.globalAlpha = 1; 
    });

    if (status !== GameStatus.LEVEL_INTRO || state.introTimer >= 80) {
      drawPlayer(ctx, state, invincibilityEnabled);
    }

    ctx.restore();

    if (state.deathTimer > 0) { 
      ctx.font = 'bold 60px "Press Start 2P"'; 
      ctx.fillStyle = '#f00'; 
      ctx.textAlign = 'center'; 
      ctx.fillText(state.deathString, CANVAS_WIDTH/2, CANVAS_HEIGHT/2); 
    }

    if (state.victoryString) { 
      ctx.font = 'bold 40px "Press Start 2P"'; 
      ctx.fillStyle = '#ff0'; 
      ctx.textAlign = 'center'; 
      ctx.fillText(state.victoryString, CANVAS_WIDTH/2, CANVAS_HEIGHT/2); 
    }
  }, [stageId, invincibilityEnabled, status]);

  useEffect(() => {
    let frameId: number;
    const loop = () => { update(); draw(); frameId = requestAnimationFrame(loop); };

    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0) {
        gameStateRef.current.introTimer = 0;
        createLevel(gameStateRef.current, stageId, jumpToBossEnabled);
      }
      frameId = requestAnimationFrame(loop);
    }
    return () => cancelAnimationFrame(frameId);
  }, [status, update, draw, stageId, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import { Enemy, Projectile } from '../types';
import { 
  COLORS, GRAVITY, BULLET_DAMAGE, BOSS_CHARGE_DAMAGE, BOSS_UPPERCUT_DAMAGE, WEAKNESS_DAMAGE, 
  BOULDER_SPEED, CANVAS_WIDTH, BOSS_DOOR_X 
} from '../constants';
import { spawnDeathShower, spawnPickup, speakVulgarity, triggerBossDeath } from './systems';

export const updateEnemies = (state: any, invincibilityEnabled: boolean) => {
  const { player, camera, stageId, arenaLocked, frame } = state;
  state.enemies = state.enemies.filter((enemy: any) => {
    if (enemy.isBlownAway) { enemy.pos.x += enemy.vel.x; enemy.pos.y += enemy.vel.y; enemy.vel.y += GRAVITY * 0.5; enemy.rotation = (enemy.rotation || 0) + 0.3; return enemy.pos.y < 1000; }
    if (enemy.health <= 0) return false; 
    if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
    if (enemy.frozenTimer && enemy.frozenTimer > 0) { enemy.frozenTimer--; return true; } 
    const onScreen = enemy.pos.x + enemy.width > camera.x && enemy.pos.x < camera.x + CANVAS_WIDTH;

    if (enemy.enemyType === 'flyer') enemy.pos.y += Math.sin((frame + (enemy.initialX || 0)) / 25) * 1.2;

    if (enemy.type === 'boss') {
      // Boss AI Logic
      if (arenaLocked) {
        enemy.stateTimer--;
        if (enemy.stateTimer <= 0) {
          const rand = Math.random();
          if (rand < 0.4) {
            enemy.bossState = 'leap';
            enemy.vel.y = -15;
            enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 8;
            enemy.stateTimer = 60;
          } else if (rand < 0.7) {
            enemy.bossState = 'shoot';
            enemy.stateTimer = 90;
          } else {
            enemy.bossState = 'idle';
            enemy.stateTimer = 40;
          }
        }

        if (enemy.bossState === 'shoot' && enemy.stateTimer % 20 === 0) {
          const projY = enemy.pos.y + 20;
          const dir = player.pos.x < enemy.pos.x ? -1 : 1;
          if (stageId === 'Artie Avalanche') {
            for (let i = -1; i <= 1; i++) {
              state.projectiles.push({ id: `bp-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width / 2, y: projY }, vel: { x: dir * 8, y: i * 3 }, width: 20, height: 20, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true });
            }
          } else if (stageId === 'Victor Volcano') {
            state.projectiles.push({ id: `bp-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width / 2, y: projY }, vel: { x: dir * 12, y: 0 }, width: 25, height: 25, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE * 1.5, owner: 'enemy' });
          } else {
            state.projectiles.push({ id: `bp-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width / 2, y: projY }, vel: { x: dir * 10, y: 0 }, width: 18, height: 18, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' });
          }
        }

        if (enemy.bossState === 'leap') {
          enemy.vel.y += GRAVITY;
          enemy.pos.y += enemy.vel.y;
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.y > 470) {
            enemy.pos.y = 470;
            enemy.vel.y = 0;
            enemy.vel.x = 0;
            enemy.bossState = 'idle';
            if (stageId === 'Ernie Earthquake') {
              state.screenShakeTimer = 20;
              if (player.isGrounded) state.playerStunTimer = 40;
            }
          }
        }

        // Horizontal constraint for boss
        if (enemy.pos.x < BOSS_DOOR_X) enemy.pos.x = BOSS_DOOR_X;
        if (enemy.pos.x > BOSS_DOOR_X + CANVAS_WIDTH - enemy.width) enemy.pos.x = BOSS_DOOR_X + CANVAS_WIDTH - enemy.width;
      }
    } else {
      // Normal Enemy Logic
      if (enemy.id.startsWith('rusher')) {
          if (enemy.pauseTimer && enemy.pauseTimer > 0) { enemy.pauseTimer--; enemy.vel.x *= 0.92; } 
          else {
              const yDiff = Math.abs((player.pos.y + player.height/2) - (enemy.pos.y + enemy.height/2));
              if (onScreen && player.invincibilityTimer <= 0 && yDiff < 80) enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 6; 
              else enemy.vel.x = 0;
          }
      } else if (enemy.behavior === 'patrol') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; } 
      else if (enemy.behavior === 'fly') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; } 
      else if (enemy.behavior === 'shoot' && onScreen) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) { state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0; }
        } else if (enemy.shootTimer > 60) {
            const projY = enemy.enemyType === 'flyer' ? enemy.pos.y + enemy.height - 10 : enemy.pos.y + 20;
            state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width/2, y: projY }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0;
        }
      }
      enemy.pos.x += enemy.vel.x;
    }

    let hbW = player.width, hbH = player.height, hbX = player.pos.x, hbY = player.pos.y;
    if (player.isCharging) { hbW = player.width + 10; hbH = player.height - 10; }
    else if (player.isUppercutting) { hbW = player.width - 15; hbH = player.height + 40; hbY = player.pos.y - 30; hbX = player.pos.x + 7.5; }
    const chargeHit = (player.isCharging || player.isUppercutting) && hbX < enemy.pos.x + enemy.width && hbX + hbW > enemy.pos.x && hbY < enemy.pos.y + enemy.height && hbY + hbH > enemy.pos.y;

    if (chargeHit && onScreen && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
      const damage = player.isUppercutting ? BOSS_UPPERCUT_DAMAGE : BOSS_CHARGE_DAMAGE;
      enemy.health -= damage; enemy.hitCooldown = 60; 
      if (enemy.health > 0) { 
        if (enemy.id.startsWith('rusher')) { enemy.vel.x = player.facing * 15; enemy.pauseTimer = 120; } 
        else { enemy.vel.x = 0; enemy.vel.y = 0; }
        player.vel = { x: -player.facing * 18, y: -4 }; player.pushbackTimer = 20; player.isCharging = false; player.isUppercutting = false; player.invincibilityTimer = 30; 
      } else {
          if (enemy.type === 'boss') triggerBossDeath(state, enemy, player.facing, false);
          else { 
              enemy.isBlownAway = true; enemy.vel = { x: player.isUppercutting ? 0 : player.facing * 30, y: player.isUppercutting ? -30 : -5 };
              spawnDeathShower(state, enemy.pos, player.facing); spawnPickup(state, enemy.pos); speakVulgarity(state, player.isUppercutting ? 'uppercut_kill' : 'charge_kill'); player.killSatisfactionTimer = 60; 
          }
          return false;
      }
    } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x && player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
        if (!invincibilityEnabled) player.health -= 7.5; // Halved from 15
        player.invincibilityTimer = 60; speakVulgarity(state, 'hurt');
        if (enemy.id.startsWith('rusher') || (enemy.type === 'boss' && state.arenaLocked)) {
            if (enemy.id.startsWith('rusher')) enemy.pauseTimer = 60;
            player.pushbackTimer = 30; player.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 20; player.vel.y = -8;
        }
    }
    return true;
  });
};

export const drawBossSprite = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null) => {
    const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
    if (e.rotation) { ctx.translate(width / 2, height / 2); ctx.rotate(e.rotation); ctx.translate(-width / 2, -height / 2); }
    switch (id) {
      case 'Artie Avalanche':
          ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
          ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
      case 'Victor Volcano':
          ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
          ctx.fillStyle = '#8b4513'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.3, 0, Math.PI * 2); ctx.fill(); break;
      case 'Ernie Earthquake':
          ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7);
          ctx.fillStyle = '#e0ac69'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
      case 'Hector Hurricane':
          ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7);
          ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
    }
    ctx.restore();
};

export const drawEnemy = (ctx: CanvasRenderingContext2D, e: any, state: any) => {
  if (e.health <= 0 && !e.isBlownAway) return;
  ctx.save();
  if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
  else if (e.type === 'boss' && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }

  if (e.type === 'boss') drawBossSprite(ctx, e, state.stageId); 
  else { 
    if (e.enemyType === 'shield') { 
      ctx.fillStyle = '#444'; ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height);
      if (e.isShieldActive) { ctx.fillStyle = '#2C3E50'; ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); ctx.strokeStyle = '#00FFFF'; ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); } 
      else { ctx.fillStyle = '#7F8C8D'; ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20); }
    } else if (e.id.startsWith('rusher')) {
      ctx.fillStyle = '#9B59B6'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      const yDiff = Math.abs((state.player.pos.y + state.player.height/2) - (e.pos.y + e.height/2));
      if (yDiff >= 80 && (!e.pauseTimer || e.pauseTimer <= 0)) { ctx.fillStyle = 'rgba(255, 255, 255, 0.2)'; ctx.font = '10px monospace'; ctx.fillText('...', e.pos.x + e.width/2 - 10, e.pos.y - 15); }
    } else if (e.enemyType === 'flyer' && e.width > 60) {
        ctx.fillStyle = '#34495E'; ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30);
        ctx.fillStyle = '#E74C3C'; ctx.fillRect(e.pos.x + e.width/2 - 10, e.pos.y + 25, 20, 8);
    } else { 
      ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); 
      ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); 
    } 
  }
  if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
  if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
  ctx.restore();
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import HUD from './components/HUD';
import Overlay from './components/Overlay';
import GameCanvas from './components/GameCanvas';
import { GameStatus, WeaponType } from './types';
import { INITIAL_PLAYER_HEALTH, SPECIAL_CHARGE_REGEN_FRAMES, MAX_AMMO } from './constants';

const STAGES = ['Artie Avalanche', 'Victor Volcano', 'Ernie Earthquake', 'Hector Hurricane'];

// --- DEV CONFIG ---
const SHOW_CHEATS = true;
// ------------------

const REBUKES = [
  "I ALREADY KILLED HIM, YOU DUMB FUCK.",
  "THAT SHIT-STAIN IS ALREADY GONE.",
  "HE'S SCRAP METAL. QUIT WASTING MY GAINS.",
  "I ALREADY OBLITERATED THAT TRASH."
];

const LOCAL_BOSS_TAUNTS: Record<string, string[]> = {
  'Artie Avalanche': ["Prepare for freezer burn, meat bag."],
  'Victor Volcano': ["Well done. This is how you will be cooked, Meatface."],
  'Ernie Earthquake': ["Let's get ready to rumble, fucko."],
  'Hector Hurricane': ["I'll turn you into a soggy lump of shit."],
  'default': ["I'll break you in half!"]
};

const LOCAL_VICTORY_LINES: string[] = [
  "YOUR BIOLOGY WAS INFERIOR. THE PUMP PREVAILS.",
  "GAINS ACHIEVED. WEAKNESS DELETED.",
  "THAT WAS JUST A WARM-UP SET.",
  "IMAGINE BEING ORGANIC AND THIS WEAK.",
  "I'VE HAD TOUGHER WORKOUTS IN THE SAUNA.",
  "PURE BEEF BEATS METAL EVERY TIME."
];

const BOSS_WEAPON_MAP: Record<string, WeaponType> = {
  'Artie Avalanche': 'SHOTGUN',
  'Victor Volcano': 'FLAMETHROWER',
  'Ernie Earthquake': 'BOULDER',
  'Hector Hurricane': 'TSUNAMI'
};

const ALL_WEAPONS: WeaponType[] = ['GUN', 'BOULDER', 'SHOTGUN', 'FLAMETHROWER', 'TSUNAMI'];

const App: React.FC = () => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.START);
  const [health, setHealth] = useState(INITIAL_PLAYER_HEALTH);
  const [specialCharges, setSpecialCharges] = useState(2);
  const [specialChargeTimer, setSpecialChargeTimer] = useState(0);
  const [bossTaunt, setBossTaunt] = useState("YOU'RE TOAST.");
  const [victorySpeech, setVictorySpeech] = useState("");
  const [briefing, setBriefing] = useState("Your mission is to kill everything in sight for no particular reason.");
  const [selectedStage, setSelectedStage] = useState<string | null>(null);
  const [defeatedStages, setDefeatedStages] = useState<string[]>([]);
  const [availableWeapons, setAvailableWeapons] = useState<WeaponType[]>(['GUN']);
  const [currentWeapon, setCurrentWeapon] = useState<WeaponType>('GUN');
  // Fixed syntax error: removed redundant and invalid self-assignment in useState destructuring
  const [weaponAmmo, setWeaponAmmo] = useState<Record<WeaponType, number>>({
    'GUN': Infinity,
    'BOULDER': MAX_AMMO['BOULDER'],
    'SHOTGUN': MAX_AMMO['SHOTGUN'],
    'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
    'TSUNAMI': MAX_AMMO['TSUNAMI']
  });

  const [cheatEnabled, setCheatEnabled] = useState(false);
  const [invincibilityEnabled, setInvincibilityEnabled] = useState(false);
  const [infiniteAmmoEnabled, setInfiniteAmmoEnabled] = useState(false);
  const [jumpToBossEnabled, setJumpToBossEnabled] = useState(false);

  const [isVictoryPhase, setIsVictoryPhase] = useState(false);
  const [overlayActiveTime, setOverlayActiveTime] = useState(0);

  const [selectedIndex, setSelectedIndex] = useState(0);
  const lastPadInputRef = useRef(0);
  const lastAStateRef = useRef(false);
  const lastBStateRef = useRef(false);
  const lastStartStateRef = useRef(false);
  const lastLBStateRef = useRef(false);
  const lastRBStateRef = useRef(false);

  useEffect(() => {
    let interval: number;
    if (status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.START || status === GameStatus.VICTORY) {
      setOverlayActiveTime(0);
      interval = window.setInterval(() => {
        setOverlayActiveTime(prev => prev + 100);
      }, 100);
    }
    return () => clearInterval(interval);
  }, [status]);

  const cycleWeapon = useCallback((dir: number) => {
    setAvailableWeapons(prevAvailable => {
      if (prevAvailable.length <= 1) return prevAvailable;
      setCurrentWeapon(current => {
        const idx = prevAvailable.indexOf(current);
        const nextIdx = (idx + dir + prevAvailable.length) % prevAvailable.length;
        return prevAvailable[nextIdx];
      });
      return prevAvailable;
    });
  }, []);

  const speakRebuke = useCallback(() => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const text = REBUKES[Math.floor(Math.random() * REBUKES.length)];
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1;
      utterance.rate = 1.1;
      utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  const togglePause = useCallback(() => {
    setStatus(prev => {
      if (isVictoryPhase || 
          prev === GameStatus.BOSS_TRANSITION || 
          prev === GameStatus.BOSS_INTRO || 
          prev === GameStatus.BOSS_VICTORY_SPEECH || 
          prev === GameStatus.LEVEL_INTRO ||
          prev === GameStatus.VICTORY) {
        return prev;
      }

      if (prev === GameStatus.PLAYING) {
        setSelectedIndex(0);
        return GameStatus.PAUSED;
      }
      if (prev === GameStatus.PAUSED) return GameStatus.PLAYING;
      return prev;
    });
  }, [isVictoryPhase]);

  const handleStart = useCallback(() => {
    if (overlayActiveTime < 2000) return;

    if (status === GameStatus.VICTORY || status === GameStatus.GAME_OVER) {
      setDefeatedStages([]);
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS : ['GUN'];
      setAvailableWeapons(weaponsToStart);
      setCurrentWeapon('GUN');
      setWeaponAmmo({
        'GUN': Infinity,
        'BOULDER': MAX_AMMO['BOULDER'],
        'SHOTGUN': MAX_AMMO['SHOTGUN'],
        'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
        'TSUNAMI': MAX_AMMO['TSUNAMI']
      });
      setSelectedIndex(0);
      setIsVictoryPhase(false);
      setStatus(GameStatus.START);
    } else if (status === GameStatus.START) {
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS : ['GUN'];
      setAvailableWeapons(weaponsToStart);
      setCurrentWeapon('GUN');
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.BOSS_INTRO) {
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_VICTORY_SPEECH) {
      setIsVictoryPhase(false);
      if (defeatedStages.length >= 4) {
        setStatus(GameStatus.VICTORY);
      } else {
        setStatus(GameStatus.STAGE_SELECT);
        setSelectedStage(null);
        setSelectedIndex(0);
        setCurrentWeapon('GUN');
        setWeaponAmmo({
          'GUN': Infinity,
          'BOULDER': MAX_AMMO['BOULDER'],
          'SHOTGUN': MAX_AMMO['SHOTGUN'],
          'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
          'TSUNAMI': MAX_AMMO['TSUNAMI']
        });
      }
    }
  }, [status, defeatedStages, overlayActiveTime, cheatEnabled]);

  const handleResume = useCallback(() => {
    setStatus(GameStatus.PLAYING);
  }, []);

  const handleBossSelect = useCallback(() => {
    setSelectedStage(null);
    setSelectedIndex(0);
    setIsVictoryPhase(false);
    setCurrentWeapon('GUN');
    setStatus(GameStatus.STAGE_SELECT);
    setWeaponAmmo({
      'GUN': Infinity,
      'BOULDER': MAX_AMMO['BOULDER'],
      'SHOTGUN': MAX_AMMO['SHOTGUN'],
      'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
      'TSUNAMI': MAX_AMMO['TSUNAMI']
    });
  }, []);

  const handleQuitToMenu = useCallback(() => {
    setSelectedStage(null);
    setSelectedIndex(0);
    setIsVictoryPhase(false);
    setDefeatedStages([]);
    setCurrentWeapon('GUN');
    setStatus(GameStatus.START);
  }, []);

  const handleSelectStage = useCallback((stage: string) => {
    if (defeatedStages.includes(stage)) {
      speakRebuke();
      return;
    }
    setSelectedStage(stage);
    setHealth(INITIAL_PLAYER_HEALTH);
    setSpecialCharges(2);
    setSpecialChargeTimer(0);
    setCurrentWeapon('GUN');
    setWeaponAmmo({
      'GUN': Infinity,
      'BOULDER': MAX_AMMO['BOULDER'],
      'SHOTGUN': MAX_AMMO['SHOTGUN'],
      'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
      'TSUNAMI': MAX_AMMO['TSUNAMI']
    });
    setIsVictoryPhase(false);
    setStatus(GameStatus.LEVEL_INTRO);
  }, [defeatedStages, speakRebuke]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      if (key === 'escape') {
        togglePause();
      }

      if (status === GameStatus.PAUSED || status === GameStatus.STAGE_SELECT) {
        if (key === 'arrowup' || key === 'w') {
          if (status === GameStatus.PAUSED) setSelectedIndex(p => (p - 1 + 3) % 3);
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p - 2 + 4) % 4);
        } else if (key === 'arrowdown' || key === 's') {
          if (status === GameStatus.PAUSED) setSelectedIndex(p => (p + 1) % 3);
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p + 2) % 4);
        } else if (key === 'arrowleft' || key === 'a') {
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
        } else if (key === 'arrowright' || key === 'd') {
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
        } else if (key === 'enter' || key === ' ') {
          if (status === GameStatus.PAUSED) {
            if (selectedIndex === 0) handleResume();
            else if (selectedIndex === 1) handleBossSelect();
            else if (selectedIndex === 2) handleQuitToMenu();
          } else if (status === GameStatus.STAGE_SELECT) {
            handleSelectStage(STAGES[selectedIndex]);
          }
        }
      } else if (status === GameStatus.PLAYING) {
        if (key === 'q') cycleWeapon(-1);
        if (key === 'e') cycleWeapon(1);
      } else if (status === GameStatus.START || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY) {
        if (key === 'enter' || key === ' ') handleStart();
      }
    };
    const handleWheel = (e: WheelEvent) => {
      if (status === GameStatus.PLAYING) {
        cycleWeapon(e.deltaY > 0 ? 1 : -1);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('wheel', handleWheel);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('wheel', handleWheel);
    };
  }, [togglePause, status, cycleWeapon, selectedIndex, handleResume, handleBossSelect, handleQuitToMenu, handleSelectStage, handleStart]);

  const handleToggleCheat = useCallback(() => {
    setCheatEnabled(prev => !prev);
  }, []);

  const handleToggleInvincibility = useCallback(() => {
    setInvincibilityEnabled(prev => !prev);
  }, []);

  const handleToggleInfiniteAmmo = useCallback(() => {
    setInfiniteAmmoEnabled(prev => !prev);
  }, []);

  const handleToggleJumpToBoss = useCallback(() => {
    setJumpToBossEnabled(prev => !prev);
  }, []);

  const handleBossTransition = useCallback(() => {
    setStatus(GameStatus.BOSS_TRANSITION);
  }, []);

  const handleBossDeath = useCallback(() => {
    setIsVictoryPhase(true);
  }, []);

  const handleBossEncounter = useCallback(() => {
    setStatus(GameStatus.BOSS_INTRO);
    const pool = LOCAL_BOSS_TAUNTS[selectedStage || ''] || LOCAL_BOSS_TAUNTS['default'];
    const taunt = pool[Math.floor(Math.random() * pool.length)];
    setBossTaunt(taunt);
  }, [selectedStage]);

  const handleBossDefeated = useCallback((stageId: string) => {
    const newWeapon = BOSS_WEAPON_MAP[stageId];
    if (newWeapon) {
      setAvailableWeapons(prev => {
        if (!prev.includes(newWeapon)) {
          return [...prev, newWeapon];
        }
        return prev;
      });
    }
    setDefeatedStages(prev => [...prev, stageId]);
    const speech = LOCAL_VICTORY_LINES[Math.floor(Math.random() * LOCAL_VICTORY_LINES.length)];
    setVictorySpeech(speech);
    setStatus(GameStatus.BOSS_VICTORY_SPEECH);
  }, []);

  const handleGameOver = useCallback((victory: boolean) => {
    if (!victory) {
        setIsVictoryPhase(false);
        setStatus(GameStatus.GAME_OVER);
    }
  }, []);

  const handlePlayerUpdate = useCallback((h: number, sc: number, st: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => {
    setHealth(h);
    setSpecialCharges(sc);
    setSpecialChargeTimer(st);
    if (ammo) setWeaponAmmo(ammo);
    if (forcedWeapon) setCurrentWeapon(forcedWeapon);
  }, []);

  const handleIntroComplete = useCallback(() => {
    setStatus(GameStatus.PLAYING);
  }, []);

  useEffect(() => {
    let frameId: number;
    const poll = () => {
      const allGamepads = navigator.getGamepads();
      const gp = Array.from(allGamepads).find(p => p !== null);

      if (gp) {
        const now = Date.now();

        if (now - lastPadInputRef.current > 200) {
            let dx = 0; let dy = 0;
            // Check sticks
            if (gp.axes[0] < -0.4) dx = -1;
            else if (gp.axes[0] > 0.4) dx = 1;
            if (gp.axes[1] < -0.4) dy = -1;
            else if (gp.axes[1] > 0.4) dy = 1;

            // Check D-Pad
            if (gp.buttons[14]?.pressed) dx = -1;
            else if (gp.buttons[15]?.pressed) dx = 1;
            if (gp.buttons[12]?.pressed) dy = -1;
            else if (gp.buttons[13]?.pressed) dy = 1;

            if (status === GameStatus.STAGE_SELECT) {
              if (dx !== 0) {
                setSelectedIndex(prev => (prev % 2 === 0 ? prev + 1 : prev - 1));
                lastPadInputRef.current = now;
              } else if (dy !== 0) {
                setSelectedIndex(prev => (prev < 2 ? prev + 2 : prev - 2));
                lastPadInputRef.current = now;
              }
            } else if (status === GameStatus.PAUSED) {
              if (dy < -0.4) { // Up
                  setSelectedIndex(prev => (prev - 1 + 3) % 3);
                  lastPadInputRef.current = now;
              } else if (dy > 0.4) { // Down
                  setSelectedIndex(prev => (prev + 1) % 3);
                  lastPadInputRef.current = now;
              }
            }
        }

        const aPressed = gp.buttons[0]?.pressed; 
        const bPressed = gp.buttons[1]?.pressed; 
        const startPressed = gp.buttons[9]?.pressed;
        const lbPressed = gp.buttons[4]?.pressed;
        const rbPressed = gp.buttons[5]?.pressed;

        if (aPressed && !lastAStateRef.current) {
            if (status === GameStatus.START || status === GameStatus.VICTORY || status === GameStatus.GAME_OVER || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) {
              handleStart();
            } else if (status === GameStatus.STAGE_SELECT) {
              handleSelectStage(STAGES[selectedIndex]);
            } else if (status === GameStatus.PAUSED) {
              if (selectedIndex === 0) handleResume();
              else if (selectedIndex === 1) handleBossSelect();
              else handleQuitToMenu();
            }
        }

        if (bPressed && !lastBStateRef.current) {
            if (status === GameStatus.PAUSED) handleResume();
            else if (status === GameStatus.STAGE_SELECT) setStatus(GameStatus.START);
        }

        if (startPressed && !lastStartStateRef.current) {
            if (status === GameStatus.START) handleStart();
            else if (status === GameStatus.PLAYING || status === GameStatus.PAUSED) togglePause();
        }

        if (status === GameStatus.PLAYING) {
          if (lbPressed && !lastLBStateRef.current) cycleWeapon(-1);
          if (rbPressed && !lastRBStateRef.current) cycleWeapon(1);
        }

        lastAStateRef.current = !!aPressed;
        lastBStateRef.current = !!bPressed;
        lastStartStateRef.current = !!startPressed;
        lastLBStateRef.current = !!lbPressed;
        lastRBStateRef.current = !!rbPressed;
      }
      frameId = requestAnimationFrame(poll);
    };
    frameId = requestAnimationFrame(poll);
    return () => cancelAnimationFrame(frameId);
  }, [status, selectedIndex, handleStart, handleSelectStage, handleResume, handleBossSelect, handleQuitToMenu, togglePause, cycleWeapon]);

  return (
    <div className="relative w-screen h-screen flex items-center justify-center bg-black overflow-hidden">
      <div className="relative shadow-2xl border-4 border-gray-800 bg-[#121212]" style={{ width: 800, height: 600 }}>
        {(status === GameStatus.LEVEL_INTRO || status === GameStatus.PLAYING || status === GameStatus.BOSS_TRANSITION || status === GameStatus.PAUSED || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) && (
          <HUD 
            health={health} 
            maxHealth={INITIAL_PLAYER_HEALTH} 
            specialCharges={specialCharges}
            specialChargeTimer={specialChargeTimer}
            maxChargeTimer={SPECIAL_CHARGE_REGEN_FRAMES}
            currentWeapon={currentWeapon}
            ammo={weaponAmmo[currentWeapon]}
            maxAmmo={MAX_AMMO[currentWeapon]}
          />
        )}

        <Overlay 
          status={status} 
          onStart={handleStart} 
          onResume={handleResume}
          onBossSelect={handleBossSelect}
          onQuitToMenu={handleQuitToMenu}
          onSelectStage={handleSelectStage}
          onCheatAllWeapons={handleToggleCheat}
          onToggleInvincibility={handleToggleInvincibility}
          onToggleInfiniteAmmo={handleToggleInfiniteAmmo}
          onToggleJumpToBoss={handleToggleJumpToBoss}
          cheatEnabled={cheatEnabled}
          invincibilityEnabled={invincibilityEnabled}
          infiniteAmmoEnabled={infiniteAmmoEnabled}
          jumpToBossEnabled={jumpToBossEnabled}
          showCheats={SHOW_CHEATS}
          bossTaunt={bossTaunt}
          victorySpeech={victorySpeech}
          briefing={briefing}
          defeatedStages={defeatedStages}
          selectedIndex={selectedIndex}
          overlayActiveTime={overlayActiveTime}
          stageId={selectedStage}
        />

        <GameCanvas 
          status={status}
          stageId={selectedStage}
          onPlayerUpdate={handlePlayerUpdate}
          onBossEncounter={handleBossEncounter}
          onBossTransition={handleBossTransition}
          onBossDefeated={handleBossDefeated}
          onBossDeath={handleBossDeath}
          onGameOver={handleGameOver}
          onIntroComplete={handleIntroComplete}
          onTogglePause={togglePause}
          currentWeapon={currentWeapon}
          initialAmmo={weaponAmmo}
          invincibilityEnabled={invincibilityEnabled && (SHOW_CHEATS)}
          infiniteAmmoEnabled={infiniteAmmoEnabled && (SHOW_CHEATS)}
          jumpToBossEnabled={jumpToBossEnabled && (SHOW_CHEATS)}
        />
      </div>
    </div>
  );
};

export default App;

import { Enemy, Projectile } from '../types';
import { 
  COLORS, GRAVITY, BULLET_DAMAGE, BOSS_CHARGE_DAMAGE, BOSS_UPPERCUT_DAMAGE, WEAKNESS_DAMAGE, 
  BOULDER_SPEED, CANVAS_WIDTH, BOSS_DOOR_X 
} from '../constants';
import { spawnDeathShower, spawnPickup, speakVulgarity, triggerBossDeath, spawnRockShatter } from './systems';

export const updateEnemies = (state: any, invincibilityEnabled: boolean) => {
  const { player, camera, stageId, arenaLocked, frame } = state;
  state.enemies = state.enemies.filter((enemy: any) => {
    if (enemy.isBlownAway) { 
      enemy.pos.x += enemy.vel.x; 
      enemy.pos.y += enemy.vel.y; 
      enemy.vel.y += GRAVITY * 0.5; 
      enemy.rotation = (enemy.rotation || 0) + 0.3; 
      return enemy.pos.y < 1000; 
    }
    if (enemy.health <= 0) return false; 
    if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
    if (enemy.frozenTimer && enemy.frozenTimer > 0) { enemy.frozenTimer--; return true; } 
    const onScreen = enemy.pos.x + enemy.width > camera.x && enemy.pos.x < camera.x + CANVAS_WIDTH;

    if (enemy.enemyType === 'flyer') enemy.pos.y += Math.sin((frame + (enemy.initialX || 0)) / 25) * 1.2;

    if (enemy.type === 'boss') {
      if (arenaLocked) {
        enemy.stateTimer--;

        // --- BOSS STATE MACHINE ---
        if (enemy.stateTimer <= 0) {
          const rand = Math.random();
          if (stageId === 'Artie Avalanche') {
            if (rand < 0.3) { enemy.bossState = 'leap'; enemy.vel.y = -18; enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 7; enemy.stateTimer = 60; }
            else if (rand < 0.7) { enemy.bossState = 'shoot'; enemy.stateTimer = 120; }
            else { enemy.bossState = 'ice_scatter'; enemy.stateTimer = 100; }
          } 
          else if (stageId === 'Victor Volcano') {
            if (rand < 0.4) { enemy.bossState = 'dash'; enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 15; enemy.stateTimer = 40; }
            else if (rand < 0.8) { enemy.bossState = 'shoot'; enemy.stateTimer = 90; }
            else { enemy.bossState = 'leap'; enemy.vel.y = -20; enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 5; enemy.stateTimer = 60; }
          }
          else if (stageId === 'Ernie Earthquake') {
            if (rand < 0.5) { enemy.bossState = 'leap'; enemy.vel.y = -22; enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 6; enemy.stateTimer = 80; }
            else if (rand < 0.8) { enemy.bossState = 'boulder_toss'; enemy.stateTimer = 100; }
            else { enemy.bossState = 'idle'; enemy.stateTimer = 40; }
          }
          else if (stageId === 'Hector Hurricane') {
            if (rand < 0.4) { enemy.bossState = 'wind_push'; enemy.stateTimer = 180; }
            else if (rand < 0.7) { enemy.bossState = 'tornado'; enemy.stateTimer = 120; }
            else { enemy.bossState = 'leap'; enemy.vel.y = -15; enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 10; enemy.stateTimer = 60; }
          }
          else {
            enemy.bossState = 'idle'; enemy.stateTimer = 60;
          }
        }

        // --- SPECIAL MECHANICS PER BOSS ---
        const dir = player.pos.x < enemy.pos.x ? -1 : 1;
        const projY = enemy.pos.y + 20;

        if (enemy.bossState === 'shoot') {
          if (enemy.stateTimer % 20 === 0) {
            if (stageId === 'Artie Avalanche') {
              for (let i = -1; i <= 1; i++) {
                state.projectiles.push({ id: `bp-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width / 2, y: projY }, vel: { x: dir * 9, y: i * 3 }, width: 24, height: 24, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true });
              }
            } else if (stageId === 'Victor Volcano') {
              state.projectiles.push({ id: `bp-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width / 2, y: projY }, vel: { x: dir * 14, y: (Math.random()-0.5)*4 }, width: 30, height: 30, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE * 1.5, owner: 'enemy' });
            }
          }
        }

        if (enemy.bossState === 'ice_scatter' && stageId === 'Artie Avalanche' && enemy.stateTimer % 5 === 0) {
          state.projectiles.push({ id: `bp-${Date.now()}`, pos: { x: BOSS_DOOR_X + Math.random()*800, y: -50 }, vel: { x: 0, y: 12 }, width: 20, height: 40, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true });
        }

        if (enemy.bossState === 'dash' && stageId === 'Victor Volcano') {
          enemy.pos.x += enemy.vel.x;
          if (frame % 3 === 0) state.particles.push({ pos: { x: enemy.pos.x + enemy.width/2, y: enemy.pos.y + enemy.height/2 }, vel: { x: 0, y: -2 }, life: 30, color: '#FF4500', size: 15 });
        }

        if (enemy.bossState === 'boulder_toss' && stageId === 'Ernie Earthquake' && enemy.stateTimer === 50) {
           state.projectiles.push({ id: `bb-${Date.now()}`, pos: { x: enemy.pos.x + (dir === 1 ? enemy.width : -40), y: enemy.pos.y - 20 }, vel: { x: dir * 10, y: -8 }, width: 60, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE * 2, owner: 'enemy', isBoulder: true });
        }

        if (enemy.bossState === 'wind_push' && stageId === 'Hector Hurricane') {
          const pushForce = 0.45;
          player.vel.x += (dir === -1 ? pushForce : -pushForce);
          if (frame % 5 === 0) state.particles.push({ pos: { x: enemy.pos.x + (dir === 1 ? 0 : enemy.width), y: Math.random()*600 }, vel: { x: dir * -15, y: 0 }, life: 40, color: 'rgba(255,255,255,0.3)', size: 4 });
        }

        if (enemy.bossState === 'tornado' && stageId === 'Hector Hurricane' && enemy.stateTimer % 30 === 0) {
           state.projectiles.push({ id: `bt-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width/2, y: 500 }, vel: { x: dir * 5, y: 0 }, width: 60, height: 100, health: 5, maxHealth: 5, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' });
        }

        if (enemy.bossState === 'leap') {
          enemy.vel.y += GRAVITY;
          enemy.pos.y += enemy.vel.y;
          enemy.pos.x += enemy.vel.x;
          if (enemy.pos.y > 470) {
            enemy.pos.y = 470;
            enemy.vel.y = 0;
            enemy.vel.x = 0;
            enemy.bossState = 'idle';
            if (stageId === 'Ernie Earthquake') {
              state.screenShakeTimer = 30;
              if (player.isGrounded) {
                state.playerStunTimer = 45;
                speakVulgarity(state, 'hurt'); // Stun makes him angry
              }
            }
            if (stageId === 'Victor Volcano') {
              for(let i=0; i<5; i++) {
                state.projectiles.push({ id: `bf-${Date.now()}-${i}`, pos: { x: enemy.pos.x + enemy.width/2, y: 470 }, vel: { x: (i-2)*5, y: -10 }, width: 25, height: 25, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' });
              }
            }
          }
        }

        // Horizontal constraint for boss in arena
        if (enemy.pos.x < BOSS_DOOR_X) { enemy.pos.x = BOSS_DOOR_X; enemy.vel.x *= -0.5; }
        if (enemy.pos.x > BOSS_DOOR_X + CANVAS_WIDTH - enemy.width) { enemy.pos.x = BOSS_DOOR_X + CANVAS_WIDTH - enemy.width; enemy.vel.x *= -0.5; }
      }
    } else {
      // Normal Enemy Logic
      if (enemy.id.startsWith('rusher')) {
          if (enemy.pauseTimer && enemy.pauseTimer > 0) { enemy.pauseTimer--; enemy.vel.x *= 0.92; } 
          else {
              const yDiff = Math.abs((player.pos.y + player.height/2) - (enemy.pos.y + enemy.height/2));
              if (onScreen && player.invincibilityTimer <= 0 && yDiff < 80) enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 6; 
              else enemy.vel.x = 0;
          }
      } else if (enemy.behavior === 'patrol') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; } 
      else if (enemy.behavior === 'fly') { enemy.pos.x += enemy.vel.x; if (enemy.pos.x > enemy.initialX + enemy.patrolRange || enemy.pos.x < enemy.initialX) enemy.vel.x *= -1; } 
      else if (enemy.behavior === 'shoot' && onScreen) {
        enemy.shootTimer++;
        if (enemy.enemyType === 'shield') {
            enemy.isShieldActive = enemy.shootTimer < 80;
            if (enemy.shootTimer > 120) { state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 20 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0; }
        } else if (enemy.shootTimer > 60) {
            const projY = enemy.enemyType === 'flyer' ? enemy.pos.y + enemy.height - 10 : enemy.pos.y + 20;
            state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width/2, y: projY }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0;
        }
      }
      enemy.pos.x += enemy.vel.x;
    }

    let hbW = player.width, hbH = player.height, hbX = player.pos.x, hbY = player.pos.y;
    if (player.isCharging) { hbW = player.width + 20; hbH = player.height - 10; hbX -= 10; }
    else if (player.isUppercutting) { hbW = player.width - 15; hbH = player.height + 50; hbY = player.pos.y - 40; hbX = player.pos.x + 7.5; }

    const chargeHit = (player.isCharging || player.isUppercutting) && hbX < enemy.pos.x + enemy.width && hbX + hbW > enemy.pos.x && hbY < enemy.pos.y + enemy.height && hbY + hbH > enemy.pos.y;

    if (chargeHit && onScreen && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
      const damage = player.isUppercutting ? BOSS_UPPERCUT_DAMAGE : BOSS_CHARGE_DAMAGE;
      enemy.health -= damage; enemy.hitCooldown = 60; 
      if (enemy.health > 0) { 
        if (enemy.id.startsWith('rusher')) { enemy.vel.x = player.facing * 15; enemy.pauseTimer = 120; } 
        else { enemy.vel.x = 0; enemy.vel.y = 0; }
        player.vel = { x: -player.facing * 18, y: -4 }; 
        player.pushbackTimer = 20; 
        player.isCharging = false; 
        player.isUppercutting = false; 
        player.invincibilityTimer = 30; 
      } else {
          if (enemy.type === 'boss') triggerBossDeath(state, enemy, player.facing, false);
          else { 
              enemy.isBlownAway = true; 
              enemy.vel = { x: player.isUppercutting ? 0 : player.facing * 30, y: player.isUppercutting ? -30 : -5 };
              spawnDeathShower(state, enemy.pos, player.facing); 
              spawnPickup(state, enemy.pos); 
              speakVulgarity(state, player.isUppercutting ? 'uppercut_kill' : 'charge_kill'); 
              player.killSatisfactionTimer = 60; 
          }
          return false;
      }
    } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x && player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
        if (!invincibilityEnabled) player.health -= 7.5;
        player.invincibilityTimer = 60; 
        speakVulgarity(state, 'hurt');
        if (enemy.id.startsWith('rusher') || (enemy.type === 'boss' && state.arenaLocked)) {
            if (enemy.id.startsWith('rusher')) enemy.pauseTimer = 60;
            player.pushbackTimer = 30; 
            player.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 20; 
            player.vel.y = -8;
        }
    }
    return true;
  });
};

export const drawBossSprite = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null) => {
    const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
    if (e.rotation) { ctx.translate(width / 2, height / 2); ctx.rotate(e.rotation); ctx.translate(-width / 2, -height / 2); }
    switch (id) {
      case 'Artie Avalanche':
          ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
          ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
      case 'Victor Volcano':
          ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
          ctx.fillStyle = '#8b4513'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.3, 0, Math.PI * 2); ctx.fill(); break;
      case 'Ernie Earthquake':
          ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7);
          ctx.fillStyle = '#e0ac69'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
      case 'Hector Hurricane':
          ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7);
          ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
    }
    ctx.restore();
};

export const drawEnemy = (ctx: CanvasRenderingContext2D, e: any, state: any) => {
  if (e.health <= 0 && !e.isBlownAway) return;
  ctx.save();
  if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
  else if (e.type === 'boss' && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }

  if (e.type === 'boss') drawBossSprite(ctx, e, state.stageId); 
  else { 
    if (e.enemyType === 'shield') { 
      ctx.fillStyle = '#444'; ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height);
      if (e.isShieldActive) { ctx.fillStyle = '#2C3E50'; ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); ctx.strokeStyle = '#00FFFF'; ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); } 
      else { ctx.fillStyle = '#7F8C8D'; ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20); }
    } else if (e.id.startsWith('rusher')) {
      ctx.fillStyle = '#9B59B6'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      const yDiff = Math.abs((state.player.pos.y + state.player.height/2) - (e.pos.y + e.height/2));
      if (yDiff >= 80 && (!e.pauseTimer || e.pauseTimer <= 0)) { ctx.fillStyle = 'rgba(255, 255, 255, 0.2)'; ctx.font = '10px monospace'; ctx.fillText('...', e.pos.x + e.width/2 - 10, e.pos.y - 15); }
    } else if (e.enemyType === 'flyer' && e.width > 60) {
        ctx.fillStyle = '#34495E'; ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30);
        ctx.fillStyle = '#E74C3C'; ctx.fillRect(e.pos.x + e.width/2 - 10, e.pos.y + 25, 20, 8);
    } else { 
      ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); 
      ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); 
    } 
  }
  if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
  if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
  ctx.restore();
};

import { Vector2, PickupType, Enemy, WeaponType } from '../types';
