      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0,
      pushbackTimer: 0,
      killSatisfactionTimer: 0,
