interface HUDProps {
  health: number;
  maxHealth: number;
  specialCharges: number;
  specialChargeTimer: number;
  maxChargeTimer: number;
  currentWeapon: WeaponType;
  ammo: number;
  maxAmmo: number;
}

const ProgressBar = ({ pct, color, width = 'w-48' }: { pct: number, color: string, width?: string }) => (
  <div className={`${width} h-5 bg-black border-2 border-white overflow-hidden shadow-[2px_2px_0px_white]`}>
    <div className={`h-full ${color} transition-all duration-150`} style={{ width: `${pct}%` }} />
  </div>
);

const HUD: React.FC<HUDProps> = ({ 
  health, maxHealth, specialCharges, specialChargeTimer, 
  maxChargeTimer, currentWeapon, ammo, maxAmmo 
}) => {
  const hpPct = Math.max(0, (health / maxHealth) * 100);
  const pwrPct = (specialChargeTimer / maxChargeTimer) * 100;
  const hasAmmo = maxAmmo !== Infinity;
  const ammoPct = hasAmmo ? Math.max(0, (ammo / maxAmmo) * 100) : 100;

  return (
    <div className="absolute inset-0 pt-10 px-8 pointer-events-none select-none z-50">
      <div className="flex flex-col gap-2 max-w-xs">
        {/* HP */}
        <div className="flex items-center gap-4">
          <span className="text-white text-[10px] font-black italic">HP</span>
          <ProgressBar pct={hpPct} color="bg-red-600" />
        </div>

        {/* Special Charges */}
        <div className="flex items-center gap-4">
          <span className="text-white text-[10px] font-black italic">PWR</span>
          <div className="flex gap-1 items-center">
            {[...Array(2)].map((_, i) => {
              const isFull = i < specialCharges;
              const isCharging = i === specialCharges;
              return (
                <div key={i} className="w-8 h-4 bg-black border-2 border-white relative shadow-[1px_1px_0px_white]">
                  {isFull && <div className="absolute inset-0 bg-yellow-500" />}
                  {isCharging && <div className="absolute inset-y-0 left-0 bg-yellow-500/50" style={{ width: `${pwrPct}%` }} />}
                </div>
              );
            })}
          </div>
        </div>

        {/* Weapon */}
        <div className="mt-1 flex items-center gap-4">
          <span className="text-white text-[10px] font-black italic">WPN</span>
          <div className="flex flex-col gap-1">
            <div className="px-3 py-1 bg-red-800 border-2 border-white text-white text-[10px] font-black italic shadow-[2px_2px_0px_white]">
              {currentWeapon}
            </div>
            {hasAmmo && (
              <div className="flex items-center gap-2">
                <ProgressBar pct={ammoPct} color="bg-yellow-400" width="w-24" />
                <span className="text-white text-[8px] font-black">{Math.floor(ammo)}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

