        <div className="bg-red-950/90 border-4 border-red-600 p-8 max-w-lg">
          <h2 className="text-2xl text-red-500 mb-4 font-black uppercase italic">ENEMY LOG:</h2>
          <p className="text-white italic mb-8 uppercase tracking-tight leading-relaxed">"{bossTaunt}"</p>
          <button onClick={onStart} disabled={isInputLocked} className="px-8 py-4 bg-red-600 text-white font-black border-b-[6px] border-red-900 uppercase">STFU AND DIE</button>
        </div>
      )}

      {status === GameStatus.PAUSED && (
        <div className="flex flex-col gap-4">
          <h2 className="text-4xl text-white mb-8 font-black uppercase italic border-b-4 border-yellow-500 pb-2">RESTING SET</h2>
          <button onClick={onResume} className="px-10 py-4 bg-yellow-600 text-white font-black border-b-[8px] border-yellow-800 uppercase">RESUME</button>
          <button onClick={onBossSelect} className="px-10 py-4 bg-red-700 text-white font-black border-b-[8px] border-red-900 uppercase">STAGE SELECT</button>
          <button onClick={onQuitToMenu} className="px-10 py-4 bg-gray-700 text-white font-black border-b-[8px] border-gray-900 uppercase">QUIT</button>
        </div>
      )}
    </div>
  );
};

