const BOSS_DOOR_X = 7200;
const DOOR_WIDTH = 40;

// Added GameCanvasProps interface to fix "Cannot find name 'GameCanvasProps'" error.
interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (h: number, sc: number, st: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, 
  jumpToBossEnabled, bossTauntText
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const state = useRef({
    player: {
      id: 'player', pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, width: 44, height: 64,
      health: INITIAL_PLAYER_HEALTH, maxHealth: INITIAL_PLAYER_HEALTH, type: 'player',
      isCharging: false, isUppercutting: false, isDucking: false, specialCharges: MAX_SPECIAL_CHARGES,
      specialChargeTimer: 0, chargeDuration: 0, isJumping: false, isGrounded: false, facing: 1,
      shootCooldown: 0, jumpPrepTimer: 0, landTimer: 0, invincibilityTimer: 0, pushbackTimer: 0,
      killSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true,
      currentWeapon: 'GUN', availableWeapons: ['GUN'], weaponAmmo: { ...initialAmmo }
    } as Player & { killSatisfactionTimer: number },
    enemies: [] as any[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as any[],
    damageNumbers: [] as DamageNumber[],
    blocks: [] as any[],
    camera: { x: 0, y: 0 },
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    playerLastVulgarity: "",
    playerVulgarityTimer: 0,
    bossLastVulgarity: "",
    bossVulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryString: "",
    deathString: "",
    deathTimer: 0,
    postVictoryTimer: 0,
    introTimer: 0,
    bossExplosionTimer: 0,
    bossExplosionPos: { x: 0, y: 0 },
    tsunamiX: -1,
    tsunamiStartX: 0,
    tsunamiActive: false,
    tsunamiDir: 1,
    bossVolcanoes: [] as any[],
    bossVolcanoTelegraphs: [] as any[],
    screenShakeTimer: 0,
    playerStunTimer: 0
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  useEffect(() => {
    const handleDown = (e: KeyboardEvent) => keys.current[e.key.toLowerCase()] = true;
    const handleUp = (e: KeyboardEvent) => keys.current[e.key.toLowerCase()] = false;
    window.addEventListener('keydown', handleDown);
    window.addEventListener('keyup', handleUp);
    return () => {
      window.removeEventListener('keydown', handleDown);
      window.removeEventListener('keyup', handleUp);
    };
  }, []);

  const speak = (text: string, isBoss = false, bossId = "") => {
    if (!('speechSynthesis' in window)) return;
    if (!isBoss && state.current.bossVulgarityTimer > 0) return; // Boss priority

    window.speechSynthesis.cancel();
    const utt = new SpeechSynthesisUtterance(text);
    if (isBoss) {
      switch (bossId) {
        case 'Artie Avalanche': utt.pitch = 1.6; utt.rate = 0.85; break;
        case 'Victor Volcano': utt.pitch = 0.4; utt.rate = 1.1; break;
        case 'Ernie Earthquake': utt.pitch = 0.1; utt.rate = 0.55; break;
        case 'Hector Hurricane': utt.pitch = 1.2; utt.rate = 2.1; break;
      }
      state.current.bossLastVulgarity = text;
      state.current.bossVulgarityTimer = 150;
    } else {
      utt.pitch = 0.1; utt.rate = 1.2;
      state.current.playerLastVulgarity = text;
      state.current.playerVulgarityTimer = 120;
    }
    window.speechSynthesis.speak(utt);
  };

  const speakVulgarity = (type: string) => {
    if (state.current.voiceLineCooldown > 0 && type !== 'death') return;
    const pool = (type === 'hurt' && state.current.arenaLocked && stageId && BOSS_HURT_VULGARITIES[stageId]) 
      ? BOSS_HURT_VULGARITIES[stageId] : VULGARITIES[type];
    if (pool) {
      speak(pool[Math.floor(Math.random() * pool.length)]);
      state.current.voiceLineCooldown = 90;
    }
  };

  const spawnExplosion = (pos: Vector2, color: string, count: number, spread = 15) => {
    for (let i = 0; i < count; i++) {
      if (state.current.particles.length > 800) break;
      state.current.particles.push({
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * spread, y: (Math.random() - 0.5) * spread },
        life: 20 + Math.random() * 80,
        color, size: 2 + Math.random() * 10
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing = 0, multiplier = 1) => {
    ['#8B0000', '#FF0000', '#f1c27d', '#FF4500'].forEach(c => spawnExplosion(pos, c, Math.ceil(10 * multiplier), 25));
  };

  const triggerBossDeath = (boss: Enemy, playerFacing: number) => {
    if (state.current.bossExplosionTimer > 0) return;
    const pos = { x: boss.pos.x + boss.width / 2, y: boss.pos.y + boss.height / 2 };
    speak(BOSS_THRESHOLDS[stageId || ""][0] || "DAMN IT.", true, stageId || "");
    state.current.bossExplosionTimer = 220; 
    state.current.bossExplosionPos = pos;
    state.current.arenaLocked = false;
    speakVulgarity('gun_kill');
  };

  const createLevel = useCallback(() => {
    const s = state.current;
    const doorX = BOSS_DOOR_X;
    s.arenaLocked = false;
    s.doorState = 'closed';
    s.doorOpenAmount = 0;
    s.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' },
      { x: 8000, y: -1000, w: 100, h: 2000, type: 'wall' },
      { x: 0, y: 550, w: 8000, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: DOOR_WIDTH, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: DOOR_WIDTH, h: 1400, type: 'wall' },
      { x: 7960, y: 100, w: 40, h: 500, type: 'wall' }
    ];

    // Generic platform generator
    for (let i = 600; i < doorX; i += 700) {
      s.blocks.push({ x: i, y: 400, w: 200, h: 25, type: 'platform' });
    }

    s.enemies = [];
    if (!jumpToBossEnabled) {
      for (let i = 1200; i < doorX - 500; i += 1200) {
        s.enemies.push({ id: `e-${i}`, pos: { x: i, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 100, maxHealth: 100, type: 'enemy', enemyType: 'tank', behavior: 'shoot', initialX: i, shootTimer: 0 });
      }
    }
    s.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 666, maxHealth: 666, type: 'boss', bossState: 'idle', stateTimer: 60 });
  }, [jumpToBossEnabled]);

  const update = useCallback(() => {
    const s = state.current;
    if (status === GameStatus.PAUSED || s.deathTimer > 0) {
      if (s.deathTimer > 0) { s.deathTimer--; if (s.deathTimer === 0) window.location.reload(); }
      return;
    }

    s.frame++;
    if (s.playerVulgarityTimer > 0) s.playerVulgarityTimer--;
    if (s.bossVulgarityTimer > 0) s.bossVulgarityTimer--;
    if (s.voiceLineCooldown > 0) s.voiceLineCooldown--;

    // Status checks
    if (status === GameStatus.LEVEL_INTRO) {
      s.introTimer++;
      if (s.introTimer === 30) speak(INTRO_QUOTES[stageId || ""], false);
      if (s.introTimer >= 140) onIntroComplete();
      return;
    }

    const p = s.player;
    const moveLeft = keys.current['a'] || keys.current['arrowleft'];
    const moveRight = keys.current['d'] || keys.current['arrowright'];
    const jump = keys.current[' '] || keys.current['z'];
    const charge = keys.current['shift'];

    // Player Physics & Movement
    if (!p.isCharging && !p.isUppercutting) {
      if (moveLeft) { p.vel.x = -PLAYER_SPEED; p.facing = -1; }
      else if (moveRight) { p.vel.x = PLAYER_SPEED; p.facing = 1; }
      else p.vel.x *= FRICTION;

      if (jump && p.isGrounded && p.jumpInputReleased) { p.vel.y = PLAYER_JUMP_FORCE; p.isGrounded = false; p.jumpInputReleased = false; }
      if (!jump) p.jumpInputReleased = true;
    }

    if (charge && p.chargeInputReleased && p.specialCharges > 0 && !p.isCharging) {
      p.isCharging = true; p.chargeDuration = CHARGE_DURATION; p.specialCharges--; p.chargeInputReleased = false;
      if (keys.current['w'] || keys.current['arrowup']) { p.isUppercutting = true; p.vel.y = UPPERCUT_FORCE; p.isGrounded = false; }
    }
    if (!charge) p.chargeInputReleased = true;

    if (p.isCharging) {
      p.chargeDuration--;
      if (!p.isUppercutting) p.vel.x = p.facing * CHARGE_SPEED;
      if (p.chargeDuration <= 0) { p.isCharging = false; p.isUppercutting = false; }
    }

    p.vel.y += GRAVITY;
    p.pos.x += p.vel.x; p.pos.y += p.vel.y;

    // Collisions
    p.isGrounded = false;
    s.blocks.forEach(b => {
      if (p.pos.x < b.x + b.w && p.pos.x + p.width > b.x && p.pos.y < b.y + b.h && p.pos.y + p.height > b.y) {
        if (b.type === 'door' && s.doorState === 'closed') {
          s.doorState = 'opening';
          s.enemies.forEach(e => { if (e.type !== 'boss') { e.health = 0; spawnDeathShower(e.pos); } });
        }
        const overlapY = Math.min(p.pos.y + p.height - b.y, b.y + b.h - p.pos.y);
        const overlapX = Math.min(p.pos.x + p.width - b.x, b.x + b.w - p.pos.x);
        if (overlapX < overlapY) { p.pos.x = p.pos.x + p.width/2 < b.x + b.w/2 ? b.x - p.width : b.x + b.w; p.vel.x = 0; }
        else { 
          if (p.pos.y + p.height/2 < b.y + b.h/2) { p.pos.y = b.y - p.height; p.vel.y = 0; p.isGrounded = true; }
          else { p.pos.y = b.y + b.h; p.vel.y = 0; }
        }
      }
    });

    // Door animation
    if (s.doorState === 'opening') {
      s.doorOpenAmount += 5;
      if (s.doorOpenAmount >= 150) { s.doorState = 'open'; s.arenaLocked = true; onBossTransition(); }
    }

    // Camera
    if (!s.arenaLocked) s.camera.x = Math.max(0, Math.min(BOSS_DOOR_X - CANVAS_WIDTH + DOOR_WIDTH, p.pos.x - CANVAS_WIDTH/2));

    // Special recharge
    if (p.specialCharges < MAX_SPECIAL_CHARGES) {
      p.specialChargeTimer++;
      if (p.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) { p.specialCharges++; p.specialChargeTimer = 0; }
    }

    onPlayerUpdate(p.health, p.specialCharges, p.specialChargeTimer);
  }, [status, stageId, onIntroComplete, onBossTransition, onPlayerUpdate]);

  const draw = useCallback(() => {
    const ctx = canvasRef.current?.getContext('2d');
    if (!ctx) return;
    const s = state.current;
    const colors = STAGE_COLORS[stageId || ""] || { ground: '#333', bg: '#000', accent: '#fff' };

    ctx.fillStyle = colors.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); ctx.translate(-s.camera.x, -s.camera.y);

    // Blocks
    s.blocks.forEach(b => {
      ctx.fillStyle = b.type === 'door' ? '#444' : colors.ground;
      ctx.fillRect(b.x, b.type === 'door' ? b.y - s.doorOpenAmount : b.y, b.w, b.h);
    });

    // Player
    const p = s.player;
    ctx.fillStyle = COLORS.MEATHEAD_SKIN;
    ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
    if (s.playerLastVulgarity && s.playerVulgarityTimer > 0) {
      ctx.fillStyle = 'white'; ctx.font = '10px "Press Start 2P"';
      ctx.fillText(s.playerLastVulgarity, p.pos.x, p.pos.y - 10);
    }

    // Boss text priority
    s.enemies.forEach(e => {
      if (e.type === 'boss') {
        ctx.fillStyle = 'red'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
        const taunt = (status === GameStatus.BOSS_INTRO && bossTauntText) ? bossTauntText : (s.bossVulgarityTimer > 0 ? s.bossLastVulgarity : "");
        if (taunt) {
          ctx.fillStyle = 'white'; ctx.font = '12px "Press Start 2P"';
          ctx.fillText(taunt, e.pos.x - 50, e.pos.y - 20);
        }
      } else {
        ctx.fillStyle = 'purple'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
      }
    });

    // Particles
    s.particles.forEach(pt => { ctx.fillStyle = pt.color; ctx.fillRect(pt.pos.x, pt.pos.y, pt.size, pt.size); });

    ctx.restore();
  }, [stageId, bossTauntText, status]);

  useEffect(() => {
    createLevel();
    let frame: number;
    const loop = () => { update(); draw(); frame = requestAnimationFrame(loop); };
    frame = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frame);
  }, [createLevel, update, draw]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

