                >
                  ALL WEAPONS: {cheatEnabled ? 'ON' : 'OFF'}
                </button>
                <button 
                  onClick={onToggleInvincibility}
                  className={`px-4 py-2 border-2 transition-all font-black text-[9px] uppercase shadow-[2px_2px_0px_white] hover:scale-105 active:translate-y-0.5 ${invincibilityEnabled ? 'bg-green-500 border-white text-black shadow-[2px_2px_0px_#fff]' : 'bg-gray-800 border-gray-600 text-gray-400 shadow-[2px_2px_0px_#333]'}`}
                >
                  INVINCIBILITY: {invincibilityEnabled ? 'ON' : 'OFF'}
                </button>
                <button 
                  onClick={onToggleInfiniteAmmo}
                  className={`px-4 py-2 border-2 transition-all font-black text-[9px] uppercase shadow-[2px_2px_0px_white] hover:scale-105 active:translate-y-0.5 ${infiniteAmmoEnabled ? 'bg-blue-500 border-white text-black shadow-[2px_2px_0px_#fff]' : 'bg-gray-800 border-gray-600 text-gray-400 shadow-[2px_2px_0px_#333]'}`}
                >
                  INFINITE AMMO: {infiniteAmmoEnabled ? 'ON' : 'OFF'}
                </button>
                <button 
                  onClick={onToggleJumpToBoss}
                  className={`px-4 py-2 border-2 transition-all font-black text-[9px] uppercase shadow-[2px_2px_0px_white] hover:scale-105 active:translate-y-0.5 ${jumpToBossEnabled ? 'bg-red-500 border-white text-black shadow-[2px_2px_0px_#fff]' : 'bg-gray-800 border-gray-600 text-gray-400 shadow-[2px_2px_0px_#333]'}`}
