        } 
    });
    particles.forEach(p => { 
      if (p.isWater) {
        ctx.save();
        ctx.globalAlpha = p.life < 10 ? p.life / 10 : 1.0;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.pos.x, p.pos.y, p.size / 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      } else {
        ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; 
        ctx.fillStyle = p.color; 
        ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); 
      }
    });

    damageNumbers.forEach(d => {
      ctx.save();
      const alpha = d.life / d.maxLife;
      ctx.globalAlpha = alpha;
      ctx.font = `bold ${d.isCritical ? '24px' : '16px'} "Press Start 2P"`;
      ctx.fillStyle = d.isCritical ? '#FFD700' : (d.value > 50 ? '#FF4500' : '#FFFFFF');
      ctx.strokeStyle = 'black';
      ctx.lineWidth = 2;
      ctx.textAlign = 'center';
      ctx.strokeText(d.value.toString(), d.pos.x, d.pos.y);
      ctx.fillText(d.value.toString(), d.pos.x, d.pos.y);
      ctx.restore();
    });

    ctx.restore();
    if (state.victoryString) { ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); }
    if (state.deathTimer > 0) { ctx.save(); ctx.font = 'bold 60px "Press Start 2P"'; ctx.fillStyle = '#FF0000'; ctx.textAlign = 'center'; ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
  }, [status, stageId, currentWeapon, invincibilityEnabled, jumpToBossEnabled, bossTauntText]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        gameStateRef.current.particles = [];
        gameStateRef.current.projectiles = [];
        gameStateRef.current.pickups = [];
        gameStateRef.current.enemies = []; 
        gameStateRef.current.damageNumbers = [];

        createLevel();

        const baseStartX = jumpToBossEnabled ? BOSS_DOOR_X - 800 : 0;
        gameStateRef.current.player = { ...gameStateRef.current.player, pos: { x: baseStartX + 150, y: 400 }, vel: { x: 0, y: 0 }, health: INITIAL_PLAYER_HEALTH, specialCharges: MAX_SPECIAL_CHARGES, specialChargeTimer: 0, pushbackTimer: 0, facing: 1, isCharging: false, isUppercutting: false, isDucking: false, jumpPrepTimer: 0, invincibilityTimer: 0, killSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true, currentWeapon: 'GUN', weaponAmmo: { ...initialAmmo } };
        gameStateRef.current.camera.x = baseStartX;
        gameStateRef.current.doorOpenAmount = 0; gameStateRef.current.doorState = 'closed'; gameStateRef.current.victoryString = ""; gameStateRef.current.introTimer = 0; gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.tsunamiActive = false; gameStateRef.current.deathTimer = 0; gameStateRef.current.deathString = ""; gameStateRef.current.arenaLocked = false;
        gameStateRef.current.bossVolcanoes = []; gameStateRef.current.bossVolcanoTelegraphs = []; gameStateRef.current.bossTsunamiSide = 0; gameStateRef.current.playerStunTimer = 0;
        gameStateRef.current.screenShakeTimer = 0;
        gameStateRef.current.playerLastVulgarity = ""; gameStateRef.current.playerVulgarityTimer = 0;
        gameStateRef.current.bossLastVulgarity = ""; gameStateRef.current.bossVulgarityTimer = 0;

        gameStateRef.current.frame = 1;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { 
      gameStateRef.current.particles = [];
      gameStateRef.current.projectiles = [];
      gameStateRef.current.pickups = [];
      gameStateRef.current.enemies = [];
      gameStateRef.current.damageNumbers = [];
      draw(); 
      gameStateRef.current.frame = 0; 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

